.cg-workspace-dock-btn {
    position: relative;
    width: 46px;
    height: 46px;
    border-radius: 14px;
    border: 1px solid rgba(15,23,42,0.08);
    background: rgba(255,255,255,0.92);
    color: #0f172a;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.65);
    transition: transform 0.16s ease, box-shadow 0.16s ease, border-color 0.16s ease, background 0.16s ease;
}
.cg-workspace-dock-btn i {
    font-size: 0.92rem;
}
.cg-workspace-dock-text-glyph {
    font-family: 'Raleway', ui-sans-serif, system-ui, sans-serif;
    font-size: 1.22rem;
    font-weight: 800;
    line-height: 1;
    letter-spacing: -0.06em;
    -webkit-font-smoothing: antialiased;
}
.cg-workspace-dock-btn:hover {
    transform: translateY(-2px);
    border-color: rgba(15,23,42,0.14);
    box-shadow: 0 12px 24px rgba(15,23,42,0.12);
}
.cg-workspace-dock-btn::after {
    content: attr(data-label) " (" attr(data-shortcut) ")";
    position: absolute;
    left: 50%;
    bottom: calc(100% + 10px);
    transform: translateX(-50%) translateY(4px);
    padding: 7px 10px;
    border-radius: 10px;
    background: rgba(15,23,42,0.92);
    color: #f8fafc;
    font-size: 0.76rem;
    font-weight: 600;
    white-space: nowrap;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.14s ease, transform 0.14s ease;
}
.cg-workspace-dock-btn:hover::after,
.cg-workspace-dock-btn:focus-visible::after {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
}
.cg-workspace-dock-btn:disabled {
    opacity: 0.48;
    cursor: not-allowed;
    box-shadow: none;
}
.cg-workspace-dock-btn.is-active {
    background: #e03131;
    color: #fff;
    border-color: rgba(224,49,49,0.44);
    box-shadow: 0 14px 26px rgba(224,49,49,0.24);
}
#cgBottomNavChat::after {
    content: attr(data-label);
}
