.cg-workspace-stage.is-marquee-active { cursor: crosshair; }
.cg-workspace-marquee {
    position: absolute;
    z-index: 12;
    border: 1px solid rgba(224, 49, 49, 0.55);
    background: rgba(224, 49, 49, 0.12);
    border-radius: 3px;
    pointer-events: none;
    box-sizing: border-box;
}
.cg-workspace-camera {
    position: absolute;
    inset: 0;
    z-index: 1;
    transform-origin: 0 0;
