}
.cg-workspace-item {
    position: absolute;
    min-width: 120px;
    min-height: 64px;
    border-radius: 10px;
    border: 1px solid rgba(15,23,42,0.10);
    box-shadow: none;
    overflow: hidden;
    pointer-events: auto;
    user-select: none;
    -webkit-user-select: none;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    contain: layout paint style;
}
.cg-workspace-item.is-dragging,
.cg-workspace-item.is-resizing {
    transition: none !important;
    box-shadow: none !important;
    will-change: transform;
}
.cg-workspace-perf-overlay {
