}
.kanban-theme-dark .cg-workspace-ai-prompt {
    background: rgba(30, 41, 59, 0.96);
    border-color: rgba(148, 163, 184, 0.2);
    color: #f1f5f9;
    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.4);
}
.kanban-theme-dark .cg-workspace-ai-prompt__main-input {
    background: rgba(15, 23, 42, 0.6);
    border-color: rgba(148, 163, 184, 0.2);
    color: #f8fafc;
}
.kanban-theme-dark .cg-workspace-ai-prompt__main-input::placeholder {
    color: #94a3b8;
}
.kanban-theme-dark .cg-workspace-ai-prompt__chip {
    background: rgba(15, 23, 42, 0.5);
    border-color: rgba(148, 163, 184, 0.18);
    color: #e2e8f0;
}
.kanban-theme-dark .cg-workspace-ai-prompt__chip > i {
    color: #94a3b8;
}
.kanban-theme-dark .cg-workspace-ai-prompt__chip-select {
    color: #f8fafc;
}
.kanban-theme-dark .cg-workspace-ai-prompt__chip-select option {
    background: #1e293b;
    color: #f8fafc;
}
.kanban-theme-dark .cg-workspace-ai-prompt__chips {
    border-top-color: rgba(148, 163, 184, 0.15);
}
.kanban-theme-dark .cg-workspace-ai-prompt__chip-input {
    color: #f8fafc;
}
.kanban-theme-dark .cg-workspace-ai-prompt__chip-input::placeholder {
    color: #64748b;
}
.kanban-theme-dark .cg-workspace-ai-prompt__chip-check {
    color: #f8fafc;
}
.kanban-theme-dark .cg-workspace-ai-prompt__ref-drop {
    border-color: rgba(148, 163, 184, 0.45);
    background: linear-gradient(165deg, rgba(148, 163, 184, 0.14) 0%, rgba(148, 163, 184, 0.05) 55%, rgba(15, 23, 42, 0.85) 100%);
    box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.12), 0 4px 18px rgba(0, 0, 0, 0.25);
}
.kanban-theme-dark .cg-workspace-ai-prompt__ref-drop.is-drag-hover {
    border-color: #94a3b8;
    background: linear-gradient(165deg, rgba(148, 163, 184, 0.22) 0%, rgba(148, 163, 184, 0.1) 50%, rgba(30, 41, 59, 0.95) 100%);
    box-shadow: inset 0 0 0 1px rgba(148, 163, 184, 0.2), 0 0 0 4px rgba(148, 163, 184, 0.18), 0 10px 28px rgba(0, 0, 0, 0.35);
}
.kanban-theme-dark .cg-workspace-ai-prompt__ref-drop-label {
    color: #cbd5e1;
}
.kanban-theme-dark .cg-workspace-ai-prompt__ref-drop-sublabel {
    color: #94a3b8;
}
.kanban-theme-dark .cg-workspace-ai-prompt__ref-strength {
    border-color: rgba(148, 163, 184, 0.22);
    background: rgba(15, 23, 42, 0.55);
    box-shadow: inset 0 1px 0 rgba(148, 163, 184, 0.06);
}
.kanban-theme-dark .cg-workspace-ai-prompt__ref-strength-label {
    color: #cbd5e1;
}
.kanban-theme-dark .cg-workspace-ai-prompt__ref-strength-value {
    color: #e2e8f0;
}
.kanban-theme-dark .cg-workspace-ai-prompt__sketch-icon-btn {
    background: rgba(15, 23, 42, 0.6);
    border-color: rgba(148, 163, 184, 0.2);
    color: #e2e8f0;
}
.kanban-theme-dark .cg-workspace-ai-prompt__sketch-icon-btn:hover {
    background: rgba(30, 41, 59, 0.85);
    border-color: rgba(148, 163, 184, 0.35);
    color: #e2e8f0;
}
.kanban-theme-dark .cg-workspace-ai-prompt__sketch-thumb-wrap {
    background: rgba(15, 23, 42, 0.5);
    border-color: rgba(148, 163, 184, 0.18);
}
.kanban-theme-dark .cg-workspace-ai-prompt__sketch-thumb {
    border-color: rgba(148, 163, 184, 0.25);
}
.kanban-theme-dark .cg-workspace-ai-prompt__sketch-remove {
    background: rgba(148, 163, 184, 0.12);
    color: #94a3b8;
}
.kanban-theme-dark .cg-workspace-sketch-modal__dialog {
    background: #1e293b;
    border-color: rgba(148, 163, 184, 0.2);
}
.kanban-theme-dark .cg-workspace-sketch-modal__head {
    border-bottom-color: rgba(148, 163, 184, 0.15);
}
.kanban-theme-dark .cg-workspace-sketch-modal__head span:first-child {
    color: #f1f5f9;
}
.kanban-theme-dark .cg-workspace-sketch-modal__hint {
    color: #94a3b8;
}
.kanban-theme-dark .cg-workspace-sketch-modal__canvas-wrap {
    background: #0f172a;
}
.kanban-theme-dark .cg-workspace-sketch-modal__canvas-wrap canvas {
    border-color: rgba(148, 163, 184, 0.2);
}
.kanban-theme-dark .cg-workspace-sketch-modal__actions {
    border-top-color: rgba(148, 163, 184, 0.15);
}
.kanban-theme-dark .cg-workspace-sketch-modal__btn--ghost {
    background: rgba(148, 163, 184, 0.12);
    color: #e2e8f0;
}
.kanban-theme-dark .cg-workspace-sketch-modal__btn--ghost:hover {
    background: rgba(148, 163, 184, 0.2);
}
@media (max-width: 720px) {
    .cg-workspace-ai-prompt__top {
        flex-wrap: wrap;
    }
    .cg-workspace-ai-prompt__field-row {
        flex: 1 1 100%;
        min-width: 100%;
    }
    .cg-workspace-ai-prompt__generate {
        flex: 1 1 auto;
        min-width: 100%;
    }
}
@media (max-width: 560px) {
    .cg-workspace-ai-prompt__chip-select {
        max-width: 100px;
    }
}
@media (max-width: 768px) {
    .cg-workspace-container {
        padding-left: 0 !important;
        padding-right: 0 !important;
    }
    .cg-workspace-floating-chrome {
        top: 8px;
        left: auto;
        right: 10px;
    }
    #workspaceBoardSelect {
        min-width: 120px;
        max-width: 200px;
    }
    .cg-workspace-stage {
        min-height: 0;
    }
    .cg-workspace-dock {
        bottom: 14px;
        gap: 8px;
        padding: 8px 10px;
        max-width: calc(100vw - 24px);
        overflow-x: auto;
    }
    .cg-workspace-brush-menu,
    .cg-workspace-text-menu {
        bottom: 66px;
        max-width: calc(100vw - 24px);
        overflow-x: auto;
        flex-wrap: wrap;
        justify-content: center;
    }
    .cg-workspace-status {
        left: 24px;
        right: 14px;
        bottom: 82px;
        max-width: none;
        overflow-x: auto;
    }
    .cg-workspace-dock-btn {
        width: 42px;
        height: 42px;
        border-radius: 12px;
        flex: 0 0 auto;
    }
}
.cg-workspace-page.cg-workspace-page--client #workspaceDock,
.cg-workspace-page.cg-workspace-page--client #workspaceLayersPanel,
.cg-workspace-page.cg-workspace-page--client #workspaceCharactersPanel,
.cg-workspace-page.cg-workspace-page--client #workspaceCharactersBtn,
.cg-workspace-page.cg-workspace-page--client #workspaceBrushMenu,
.cg-workspace-page.cg-workspace-page--client #workspaceSketchMenu,
.cg-workspace-page.cg-workspace-page--client #workspaceStoryboardMenu,
.cg-workspace-page.cg-workspace-page--client #workspaceTextMenu,
.cg-workspace-page.cg-workspace-page--client #workspaceTextCardToolbar,
.cg-workspace-page.cg-workspace-page--client #workspaceImageContextMenu,
.cg-workspace-page.cg-workspace-page--client #workspaceStageContextMenu,
.cg-workspace-page.cg-workspace-page--client #workspaceConnectorContextMenu,
.cg-workspace-page.cg-workspace-page--client #workspaceTextPropertyPanel,
.cg-workspace-page.cg-workspace-page--client #workspaceStickyNotePropertyPanel,
.cg-workspace-page.cg-workspace-page--client #workspaceFloatingChrome {
    display: none !important;
}
.cg-workspace-page.cg-workspace-page--client #workspaceItemLayer .cg-workspace-item,
.cg-workspace-page.cg-workspace-page--client #workspaceConnectorLayer,
.cg-workspace-page.cg-workspace-page--client #workspaceStrokeLayer {
    pointer-events: none !important;
}

/* Trash (Recycle Bin) */
.cg-workspace-trash-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(2, 6, 23, 0.38);
    z-index: 10050;
}
.cg-workspace-trash-panel {
    position: fixed;
    right: 18px;
    top: 76px;
    bottom: 18px;
    width: 380px;
    z-index: 10060;
    background: rgba(255, 255, 255, 0.96);
    border: 1px solid rgba(15, 23, 42, 0.12);
    border-radius: 16px;
    box-shadow: 0 28px 60px rgba(2, 6, 23, 0.28);
    overflow: hidden;
    display: flex;
    flex-direction: column;
}
.cg-workspace-trash-panel__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 14px;
    background: rgba(15, 23, 42, 0.06);
    border-bottom: 1px solid rgba(15, 23, 42, 0.10);
}
.cg-workspace-trash-panel__title {
    font-weight: 900;
    color: #0f172a;
}
.cg-workspace-trash-panel__close {
    border: 0;
    background: rgba(15, 23, 42, 0.08);
    color: #0f172a;
    width: 30px;
    height: 30px;
    border-radius: 10px;
    cursor: pointer;
    font-size: 18px;
    line-height: 30px;
}
.cg-workspace-trash-panel__close:hover {
    background: rgba(224, 49, 49, 0.16);
    color: #b91c1c;
}
.cg-workspace-trash-panel__subtitle {
    padding: 10px 14px 0;
    color: #475569;
    font-size: 0.85rem;
}
.cg-workspace-trash-panel__list {
    padding: 12px 10px 12px;
    overflow-y: auto;
    overflow-x: hidden;
    flex: 1 1 auto;
    display: flex;
    gap: 10px;
    align-items: flex-start;
}
.cg-workspace-trash-masonry__col {
    flex: 1 1 0;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 10px;
    align-items: stretch;
}
.cg-workspace-trash-item {
    padding: 10px 12px;
    border-radius: 12px;
    border: 1px solid rgba(15, 23, 42, 0.10);
    background: rgba(255, 255, 255, 0.82);
    margin-bottom: 0;
    cursor: context-menu;
    user-select: none;
    display: block;
    width: 100%;
}
.cg-workspace-trash-item:hover {
    border-color: rgba(224, 49, 49, 0.35);
    box-shadow: 0 8px 18px rgba(224, 49, 49, 0.10);
}
.cg-workspace-trash-item.is-selected {
    border-color: rgba(99, 102, 241, 0.75);
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.20);
}
/* Layers (stack order) — floating; drag handle repositions (no full-screen blocking) */
.cg-workspace-layers-panel {
    position: fixed;
    left: 18px;
    top: 76px;
    right: auto;
    bottom: auto;
    width: 320px;
    max-width: min(320px, calc(100vw - 24px));
    max-height: calc(100vh - 24px);
    min-height: 0;
    z-index: 10055;
    background: rgba(255, 255, 255, 0.96);
    border: 1px solid rgba(15, 23, 42, 0.12);
    border-radius: 16px;
    box-shadow: 0 28px 60px rgba(2, 6, 23, 0.22);
    overflow: hidden;
    display: flex;
    flex-direction: column;
    touch-action: manipulation;
    -webkit-user-select: none;
    user-select: none;
}
.cg-workspace-layers-panel.is-dragging {
    box-shadow: 0 32px 68px rgba(2, 6, 23, 0.32);
    opacity: 0.98;
}
.cg-workspace-layers-panel__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 10px 12px 10px 14px;
    border-bottom: 1px solid rgba(15, 23, 42, 0.08);
    flex: 0 0 auto;
}
.cg-workspace-layers-panel__drag {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
    flex: 1 1 auto;
    padding: 4px 6px;
    margin: -4px 0 -4px -6px;
    border-radius: 10px;
    cursor: grab;
    user-select: none;
    -webkit-user-select: none;
    touch-action: none;
}
.cg-workspace-layers-panel.is-dragging .cg-workspace-layers-panel__drag {
    cursor: grabbing;
}
.cg-workspace-layers-panel__grip {
    color: #94a3b8;
    font-size: 0.95rem;
    flex: 0 0 auto;
}
.cg-workspace-layers-panel__title {
    font-weight: 900;
    font-size: 0.95rem;
    letter-spacing: -0.02em;
    color: #0f172a;
    min-width: 0;
}
.cg-workspace-layers-panel__close {
    border: none;
    background: transparent;
    font-size: 1.35rem;
    line-height: 1;
    cursor: pointer;
    color: #64748b;
    padding: 4px 8px;
    border-radius: 8px;
}
.cg-workspace-layers-panel__close:hover {
    background: rgba(15, 23, 42, 0.06);
    color: #0f172a;
}
.cg-workspace-layers-panel__list {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 8px 10px 14px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    -webkit-user-select: none;
    user-select: none;
}
.cg-workspace-layers-empty {
    padding: 18px 12px;
    text-align: center;
    color: #94a3b8;
    font-size: 0.85rem;
    font-weight: 700;
}
/* Characters panel (Build Character) — same shell as Layers */
.cg-workspace-characters-panel {
    width: min(580px, calc(100vw - 24px));
    max-width: min(580px, calc(100vw - 24px));
    left: 360px;
    top: 76px;
}
.cg-workspace-characters-panel__tabs {
    display: flex;
    flex-wrap: nowrap;
    gap: 6px;
    padding: 6px 10px 0;
    overflow-x: auto;
    overflow-y: hidden;
    flex: 0 0 auto;
    scrollbar-width: thin;
}
.cg-workspace-characters-panel__tabs:not(:empty) {
    display: flex;
}
.cg-workspace-characters-tab {
    flex: 0 0 auto;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    max-width: 140px;
    padding: 5px 10px;
    border-radius: 999px;
    border: 1px solid rgba(15, 23, 42, 0.12);
    background: #fff;
    color: #334155;
    font-size: 0.72rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.cg-workspace-characters-tab:hover {
    border-color: rgba(99, 102, 241, 0.35);
    background: rgba(99, 102, 241, 0.06);
}
.cg-workspace-characters-tab.is-active {
    border-color: rgba(99, 102, 241, 0.55);
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.14), rgba(129, 140, 248, 0.1));
    color: #3730a3;
    box-shadow: 0 0 0 1px rgba(99, 102, 241, 0.2);
}
.cg-workspace-characters-tab__thumb {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    object-fit: cover;
    flex: 0 0 auto;
    background: rgba(15, 23, 42, 0.08);
}
.cg-workspace-characters-tab__label {
    overflow: hidden;
    text-overflow: ellipsis;
}
.cg-workspace-characters-panel__list {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    padding: 8px 10px 10px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.cg-workspace-character-card:not(.is-active-tab) {
    display: none;
}
.cg-workspace-character-card {
    border: 1px solid rgba(15, 23, 42, 0.1);
    border-radius: 12px;
    background: rgba(248, 250, 252, 0.95);
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.cg-workspace-character-card__main {
    display: grid;
    grid-template-columns: 1fr 1fr 80px;
    grid-template-rows: auto auto;
    gap: 8px;
    align-items: start;
}
.cg-workspace-character-card__field label {
    display: block;
    font-size: 0.65rem;
    font-weight: 800;
    color: #64748b;
    margin-bottom: 3px;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.cg-workspace-character-card__field input,
.cg-workspace-character-card__field select,
.cg-workspace-character-card__field textarea {
    width: 100%;
    box-sizing: border-box;
    font: inherit;
    font-size: 0.78rem;
    padding: 5px 7px;
    border-radius: 8px;
    border: 1px solid rgba(15, 23, 42, 0.12);
    background: #fff;
}
.cg-workspace-character-card__field textarea {
    min-height: 2.2em;
    resize: vertical;
}
.cg-workspace-character-card__portrait-col {
    grid-row: 1 / span 2;
    grid-column: 3;
    width: 100%;
    min-width: 0;
}
.cg-workspace-character-card__toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    align-items: center;
}
.cg-workspace-character-card__advanced-toggle {
    align-self: flex-start;
    border: none;
    background: transparent;
    color: #4f46e5;
    font-size: 0.75rem;
    font-weight: 800;
    cursor: pointer;
    padding: 2px 0;
}
.cg-workspace-character-card__advanced-toggle:hover {
    text-decoration: underline;
}
.cg-workspace-character-card__advanced {
    display: none;
    border-top: 1px solid rgba(15, 23, 42, 0.08);
    padding-top: 8px;
}
.cg-workspace-character-card.is-advanced-open .cg-workspace-character-card__advanced {
    display: block;
}
.cg-workspace-character-card__advanced-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
}
.cg-workspace-character-card__advanced-grid .cg-workspace-character-card__field--full {
    grid-column: 1 / -1;
}
.cg-workspace-characters-panel__hint {
    margin: 0;
    padding: 8px 14px 0;
    font-size: 0.72rem;
    line-height: 1.35;
    color: #64748b;
    font-weight: 600;
}
.cg-workspace-characters-panel__toolbar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    flex: 0 0 auto;
}
.cg-workspace-characters-panel__sheet-label {
    font-size: 0.75rem;
    font-weight: 800;
    color: #64748b;
    flex: 0 0 auto;
}
.cg-workspace-characters-panel__sheet-select {
    flex: 1 1 auto;
    min-width: 0;
    font-size: 0.8rem;
    padding: 6px 8px;
    border-radius: 8px;
    border: 1px solid rgba(15, 23, 42, 0.12);
    background: #fff;
}
.cg-workspace-characters-panel__table-wrap {
    flex: 1 1 auto;
    min-height: 0;
    overflow: auto;
    padding: 0 10px;
}
.cg-workspace-characters-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.78rem;
}
.cg-workspace-characters-table th {
    text-align: left;
    font-weight: 800;
    color: #64748b;
    padding: 6px 4px;
    border-bottom: 1px solid rgba(15, 23, 42, 0.08);
    white-space: nowrap;
}
.cg-workspace-characters-table td {
    vertical-align: top;
    padding: 6px 4px;
    border-bottom: 1px solid rgba(15, 23, 42, 0.06);
}
.cg-workspace-characters-table input,
.cg-workspace-characters-table select,
.cg-workspace-characters-table textarea {
    width: 100%;
    min-width: 56px;
    box-sizing: border-box;
    font: inherit;
    padding: 5px 6px;
    border-radius: 8px;
    border: 1px solid rgba(15, 23, 42, 0.12);
    background: #fff;
    resize: vertical;
}
.cg-workspace-characters-table textarea {
    min-height: 2.4em;
}
.cg-workspace-characters-portrait {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 4px;
    width: 100%;
    min-width: 0;
}
.cg-workspace-characters-portrait__thumb-wrap {
    position: relative;
    width: 100%;
    aspect-ratio: 1;
    flex: 0 0 auto;
}
.cg-workspace-characters-portrait__thumb {
    width: 100%;
    height: 100%;
    border-radius: 8px;
    object-fit: cover;
    background: rgba(15, 23, 42, 0.06);
    border: 1px solid rgba(15, 23, 42, 0.1);
    display: block;
}
.cg-workspace-characters-portrait__thumb--clickable {
    width: 100%;
    height: 100%;
    cursor: zoom-in;
    padding: 0;
    border: 1px solid rgba(15, 23, 42, 0.1);
    background: rgba(15, 23, 42, 0.06);
}
.cg-workspace-characters-portrait__thumb--clickable:hover {
    border-color: rgba(99, 102, 241, 0.45);
    box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.15);
}
.cg-workspace-characters-portrait__thumb--clickable img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 7px;
    display: block;
}
.cg-workspace-characters-portrait__thumb--empty {
    display: block;
}
.cg-workspace-characters-portrait__progress {
    position: absolute;
    inset: 0;
    border-radius: 8px;
    background: rgba(15, 23, 42, 0.55);
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-end;
    padding: 4px;
    gap: 3px;
    pointer-events: none;
}
.cg-workspace-characters-portrait__progress-track {
    height: 4px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.25);
    overflow: hidden;
}
.cg-workspace-characters-portrait__progress-bar {
    height: 100%;
    width: 0%;
    border-radius: 999px;
    background: linear-gradient(90deg, #818cf8, #a78bfa);
    transition: width 0.25s ease;
}
.cg-workspace-characters-portrait__progress-label {
    font-size: 0.55rem;
    font-weight: 800;
    color: #fff;
    text-align: center;
    line-height: 1.1;
}
.cg-workspace-characters-portrait.is-generating .cg-workspace-characters-portrait__thumb-wrap {
    opacity: 0.92;
}
.cg-workspace-character-portrait-modal {
    position: fixed;
    inset: 0;
    z-index: 10200;
    display: flex;
    align-items: center;
    justify-content: center;
