<script>
const CG_FK_API = <?php echo json_encode($cg_freelance_kanban_api_url, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>;
const CG_KANBAN_STATIC_ORIGIN = <?php echo json_encode($cg_kanban_static_origin, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>;
const CG_KANBAN_APP_ORIGIN = <?php echo json_encode($cg_kanban_app_origin, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>;
const CG_WORKSPACE_IMAGE_API_URL = <?php echo json_encode($cg_workspace_image_api_url, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?>;
function workspaceImageApiSupportsPreview(url) {
  return /\/api\/workspace_image(?:\.php)?(?:\?|$)/i.test(String(url || ''));
}
function workspaceImageApiEndpointPath() {
  return String(CG_WORKSPACE_IMAGE_API_URL || '/api/workspace_image');
}
function workspaceImageApiUrlForRelPath(relPath) {
  const rel = String(relPath || '').replace(/^\/+/, '');
  if (!rel.startsWith('uploads/workspace_images/')) return '';
  try {
    const configured = String(CG_WORKSPACE_IMAGE_API_URL || '/api/workspace_image').trim();
    let u;
    if (/^https?:\/\//i.test(configured)) {
      const pageOrigin = (typeof window !== 'undefined' && window.location && window.location.origin)
        ? window.location.origin
        : '';
      const cfgOrigin = new URL(configured).origin;
      if (pageOrigin && cfgOrigin === pageOrigin) {
        u = new URL('/api/workspace_image', pageOrigin);
      } else {
        u = new URL(configured);
      }
    } else {
      u = new URL(configured.startsWith('/') ? configured : `/${configured}`, window.location.origin);
    }
    u.searchParams.set('path', rel);
    return u.href;
  } catch (e) {
    return '';
  }
}
function workspaceImageDirectUrlForRelPath(relPath) {
  const rel = String(relPath || '').replace(/^\/+/, '');
  if (!rel.startsWith('uploads/workspace_images/')) return '';
  if (CG_KANBAN_APP_ORIGIN) {
    return `${String(CG_KANBAN_APP_ORIGIN).replace(/\/$/, '')}/${rel}`;
  }
  return `/${rel}`;
}
/** Prefer API proxy (stable on kanban subdomain); direct /uploads/ and cinegrid.net CDN URLs often 404. */
function workspaceImagePreferredUrlForRelPath(relPath) {
  const rel = String(relPath || '').replace(/^\/+/, '');
  if (!rel.startsWith('uploads/workspace_images/')) return '';
  if (/\/optimized\//i.test(rel)) {
    return workspaceImageDirectUrlForRelPath(rel);
  }
  const api = workspaceImageApiUrlForRelPath(rel);
  if (api) return api;
  return workspaceImageDirectUrlForRelPath(rel);
}
function workspaceImageOptimizedUrlForStem(stem) {
  const s = String(stem || '').trim();
  if (!s || !/^(?:ws|ws_ai)_[A-Za-z0-9._-]+$/i.test(s)) return '';
  return workspaceImageDirectUrlForRelPath(`uploads/workspace_images/optimized/${s}.webp`);
}
function workspaceImageOptimizedUrlFromFullSrc(fullSrc) {
  const rel = workspaceImageNormalizeStoredRelPath(fullSrc)
    || workspaceImageExtractUploadsPath(fullSrc);
  const stem = workspaceImageStemFromPath(rel || fullSrc);
  return workspaceImageOptimizedUrlForStem(stem);
}
function workspaceImageIsOptimizedUrl(url) {
