    const color = workspaceRandomCursorColor(actor);
    const userId = Number(row?.user_id || 0);
    if (Number.isFinite(userId) && userId > 0) {
      if (!activeByUserId.has(userId)) activeByUserId.set(userId, { actor, color });
      return;
    }
    const nameKey = normalizedName(row?.display_name || '');
    if (!nameKey) return;
    if (!activeByName.has(nameKey)) activeByName.set(nameKey, { actor, color });
  });
