  const signature = JSON.stringify(show.map((m) => {
    const uid = Number(m?.id || 0);
    const name = String(m?.name || '').trim();
    const presence = (uid > 0 && activeByUserId.has(uid))
      ? activeByUserId.get(uid)
      : activeByName.get(normalizedName(name)) || null;
    return {
      id: uid || 0,
      name,
      role: String(m?.role || ''),
      pic: String(m?.profile_pic || ''),
