function syncWorkspaceKanbanCardsFromBoardData(boardData) {
  if (!boardData || !Array.isArray(WS.items) || !WS.items.length) return;
  const cards = flattenCardsByColumn(boardData.cardsByColumn || {});
  if (!cards.length) return;
  const cardsById = new Map(cards.map(card => [Number(card.id), card]));
  const boardName = String(boardData.board_name || ((WS.bootstrap?.boards || []).find(entry => String(entry.id) === String(WS.boardId))?.name || ''));
  let hasLocalChanges = false;
  WS.items.forEach(item => {
    if (item.item_type !== 'kanban_card') return;
    const currentMeta = parseMaybeJson(item.meta_json, {});
    const cardId = Number(currentMeta.card_id || 0);
    if (!cardId) return;
    const liveCard = cardsById.get(cardId);
    if (!liveCard) return;
    const nextMeta = buildWorkspaceKanbanMetaFromCard(liveCard, boardName);
    const nextTitle = String(liveCard.title || item.title || 'Kanban Card');
    const nextSource = typeof window.cgPortalKanbanBoardHref === 'function'
      ? window.cgPortalKanbanBoardHref(WS.boardId || '', cardId)
      : `/kanban?board_id=${encodeURIComponent(WS.boardId || '')}&card_id=${encodeURIComponent(cardId)}`;
    const metaChanged = JSON.stringify(currentMeta || {}) !== JSON.stringify(nextMeta);
    const titleChanged = String(item.title || '') !== nextTitle;
    const sourceChanged = String(item.source_url || '') !== nextSource;
    if (!metaChanged && !titleChanged && !sourceChanged) return;
    item.meta_json = JSON.stringify(nextMeta);
    item.title = nextTitle;
    item.source_url = nextSource;
    hasLocalChanges = true;
  });
  /* Poll: keep kanban mirror data fresh in memory only — do not re-render card chrome (avoids iframe/embed flicker). */
}
