    syncWorkspaceKanbanCardsFromBoardData(boardData);
    WS.boardDateSummary = buildBoardDateSummary(boardData.cardsByColumn || {});
    if (Array.isArray(boardData.board_members)) {
      WS.board_members = boardData.board_members;
    }
    renderHeader();
    syncWorkspaceBoardChat();
