async function createTextCardAtWorldPoint(worldPoint) {
  try {
    const meta = buildTextCardMetaFromUi();
    const fontSize = meta.font_size_px;
    const item = await createWorkspaceItem(createPayloadAtWorldPoint({
      item_type: 'text_card',
      title: '',
      content: '',
      width: 220,
      height: Math.max(56, Math.round(fontSize * 2.6)),
      meta_json: JSON.stringify(meta),
      z_index: Math.max(1, ...WS.items.map(entry => Number(entry.z_index || 0)), ...WS.strokes.map(entry => Number(entry.z_index || 0)), ...WS.connectors.map(entry => Number(entry.z_index || 0))) + 1,
    }, worldPoint, { anchor: 'topleft' }));
    if (!item || !item.id) {
      alert('Could not create text card. Save may have been rejected — check that you can edit this board.');
      return;
    }
    setSelectedItems([Number(item.id)], Number(item.id));
    enterItemEditMode(item.id, 'content');
  } catch (err) {
    console.error('Text card error:', err);
    alert(err && err.message ? err.message : 'Could not create text card.');
  }
}
