  const head = patch.head != null && WORKSPACE_CONNECTOR_HEAD_IDS.has(patch.head) ? patch.head : cur.head;
  const color = patch.color != null ? (normalizeHexColor(String(patch.color)) || cur.color) : cur.color;
  let stroke_width = cur.strokeWidth;
  if (patch.stroke_width != null) {
    const n = Number(patch.stroke_width);
    if (Number.isFinite(n) && n > 0) {
      stroke_width = clamp(n, WORKSPACE_CONNECTOR_STROKE_WIDTH_MIN, WORKSPACE_CONNECTOR_STROKE_WIDTH_MAX);
    }
  }
  const idx = WS.connectors.findIndex(entry => Number(entry.id) === Number(connectorId));
