function workspaceItemViewLinkUrl(item) {
  if (!item) return '';
  const type = String(item.item_type || '').trim();
  const isEmbedType = type === 'youtube_embed'
    || type === 'iframe_embed'
    || type === 'map_embed'
    || type === 'instagram_embed';
  if (!isEmbedType) return '';
  const candidates = [
    String(item.source_url || '').trim(),
    String(item.embed_url || '').trim(),
  ];
  for (let i = 0; i < candidates.length; i++) {
    const raw = candidates[i];
    if (!raw) continue;
    try {
      const u = new URL(raw, window.location.href);
      if (u.protocol === 'http:' || u.protocol === 'https:') {
        return u.href;
      }
    } catch (e) {}
  }
  return '';
}
