function workspaceCollectPendingItemSaveIds() {
  const ids = new Set();
  Object.keys(WS.itemSaveTimers || {}).forEach((key) => {
    const n = Number(key);
    if (n) ids.add(n);
  });
  workspaceInFlightSaves.forEach((_, key) => {
    const n = Number(key);
    if (n) ids.add(n);
  });
  return Array.from(ids);
}
function workspaceHasPendingWorkspaceActions() {
  if ((WS.workspaceImageUploadDepth || 0) > 0) return true;
  if ((WS.workspaceMutatingDepth || 0) > 0) return true;
  if (WS.aiImageGenerating) return true;
  if (WS.characterPortraitUploadingId) return true;
  if (WS.characterDescribeInFlight) return true;
  if (Object.keys(WS.itemSaveTimers || {}).length) return true;
  if (workspaceInFlightSaves.size) return true;
  if (WS.historyTimer) return true;
  const ep = WS.eraserPersist;
  if (ep && (ep.serverDeletes.size || ep.saveByKey.size)) return true;
  return false;
}
async function workspaceWaitForPendingWorkspaceMutations(maxMs = 12000) {
  const start = Date.now();
  while (Date.now() - start < maxMs) {
    if (!workspaceHasPendingWorkspaceActions()) return;
    await new Promise((resolve) => setTimeout(resolve, 120));
  }
}
async function workspaceFlushPendingActionsBeforeRefresh() {
  flushWorkspaceEraserDragSamples();
  const eraserPersist = WS.eraserPersist;
  if (eraserPersist && (eraserPersist.serverDeletes.size || eraserPersist.saveByKey.size)) {
    await persistWorkspaceEraserDrag(eraserPersist);
    WS.eraserPersist = null;
  }
  clearWorkspaceHistoryTimer();
  pushWorkspaceHistorySnapshot();
  const pendingItemIds = workspaceCollectPendingItemSaveIds();
  if (pendingItemIds.length) flushWorkspaceItemSavesImmediate(pendingItemIds);
  await workspaceWaitForPendingWorkspaceMutations();
  cgWorkspaceImageWarmBackfillFromSeen();
}
