function workspaceEscapeItemIdForSelector(id) {
  const idStr = String(id ?? '');
  return typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(idStr) : idStr.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}
function focusWorkspaceItemField(itemId, field = 'content') {
  window.requestAnimationFrame(() => {
    const esc = workspaceEscapeItemIdForSelector(itemId);
    const itemEl = document.querySelector(`.cg-workspace-item[data-item-id="${esc}"]`);
    if (!itemEl) return;
    const titleInput = itemEl.querySelector('.cg-workspace-item__title');
    const contentInput = itemEl.querySelector('.cg-workspace-item__content');
    const target = field === 'title'
      ? (titleInput || contentInput)
      : (contentInput || titleInput);
    if (!target) return;
    try {
      target.focus({ preventScroll: true });
    } catch (err) {
      target.focus();
    }
    const isTextarea = target.matches && target.matches('textarea');
    if (isTextarea && target.setSelectionRange && target.value != null) {
      const end = String(target.value).length;
      target.setSelectionRange(end, end);
    } else if (typeof target.select === 'function' && target.matches('input, textarea')) {
      // Only use select() for inputs; selecting a textarea can place the caret in the wrong place.
      target.select();
    } else if (target.setSelectionRange && target.value != null) {
      const end = String(target.value).length;
      target.setSelectionRange(end, end);
    }
  });
}
function enterItemEditMode(itemId, field = 'content') {
