/** When nginx/OpenResty returns an HTML error page, avoid dumping tags into portal alert(). */
function formatHttpErrorMessage(status, rawText) {
  const st = Number(status) || 0;
  const raw = String(rawText || '').trim();
  if (raw && /<html[\s>]/i.test(raw)) {
    const titleM = raw.match(/<title[^>]*>([^<]*)<\/title>/i);
    if (titleM && titleM[1]) {
      const title = titleM[1].replace(/\s+/g, ' ').trim();
      if (title) return title;
    }
    const h1M = raw.match(/<h1[^>]*>([^<]*)<\/h1>/i);
    if (h1M && h1M[1]) {
      const h1 = h1M[1].replace(/\s+/g, ' ').trim();
      if (h1) return h1;
    }
    if (st === 415) {
      return 'The server rejected this upload (unsupported media type). Try PNG or JPEG, or save the image and upload again.';
    }
    if (st === 413) return 'The file is larger than the server allows.';
    return st ? `Server error (HTTP ${st}).` : 'Server error.';
  }
  if (raw.length > 240) return `${raw.slice(0, 240)}…`;
  return raw || (st ? `HTTP ${st}` : 'Request failed');
}
function isWorkspaceItemNotFoundError(err) {
  const message = String(err?.message || err || '').toLowerCase();
  return message.includes('workspace item not found');
}
function cgIsTransientPollFetchError(err) {
  if (!err) return false;
  const name = String(err.name || '');
  const msg = String(err.message || '');
  if (name === 'AbortError') return true;
  /* fetch(signal) after abort() — Chrome/Firefox may use DOMException with this text. */
  if (typeof DOMException !== 'undefined' && err instanceof DOMException) {
    if (name === 'AbortError' || Number(err.code) === 20) return true;
    if (/aborted|abort/i.test(msg)) return true;
  }
  if (/the operation was aborted|user rejected|request was cancelled/i.test(msg)) return true;
  if (typeof TypeError !== 'undefined' && err instanceof TypeError) {
    return /networkerror|failed to fetch|load failed|network request failed/i.test(msg);
  }
  return false;
}
function cgIsNetworkFetchFailure(err) {
  if (!err) return false;
  if (cgIsTransientPollFetchError(err)) return true;
  return /networkerror|failed to fetch|load failed|network request failed/i.test(String(err.message || err || ''));
}
/** Pause workspace_sync / presence while uploads, AI, character portrait work, or mutating saves are in flight. */
function workspaceShouldPauseBackgroundSync() {
  return (WS.workspaceImageUploadDepth || 0) > 0
    || (WS.workspaceMutatingDepth || 0) > 0
    || !!WS.aiImageGenerating
    || !!WS.characterPortraitUploadingId
    || !!WS.characterDescribeInFlight;
}
function logWorkspaceItemSaveError(err) {
  if (!err || cgIsNetworkFetchFailure(err)) return;
