}
function workspaceUserFacingErrorMessage(err, fallback) {
  const msg = (typeof err === 'string' ? err : String(err?.message || err || '')).trim();
  if (cgIsNetworkFetchFailure(err) || /networkerror|failed to fetch|load failed|network request failed/i.test(msg)) {
    return 'Connection was interrupted. Wait a moment and try again.';
  }
  return msg || fallback || 'Something went wrong.';
}
async function fetchJson(url, options = {}) {
  const resolvedUrl = cgResolveFreelanceKanbanApiUrl(url);
  const method = String(options.method || 'GET').toUpperCase();
  const isMutating = method !== 'GET' || !!options.body;
  const hasAbort = !!options.signal;
  const maxAttempts = (hasAbort || !isMutating) ? 1 : 3;
  if (isMutating && !hasAbort) {
    WS.workspaceMutatingDepth = (WS.workspaceMutatingDepth || 0) + 1;
  }
  try {
    let lastErr = null;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      let res;
      try {
        res = await fetch(resolvedUrl, {
          credentials: cgFetchCredentialsMode(),
          cache: 'no-store',
          ...options
        });
      } catch (err) {
        lastErr = err;
        if (cgIsTransientPollFetchError(err) || attempt >= maxAttempts) {
          if (cgIsTransientPollFetchError(err)) throw err;
          throw new Error(cgFormatFetchError(err, 'Request failed'));
        }
        await new Promise((resolve) => setTimeout(resolve, 350 * attempt));
        continue;
