async function navigateWorkspaceViewTimeline() {
  const boardId = String(WS.boardId || '').trim();
  if (!boardId) {
    alert('Please select a board to open the timeline.');
    return;
  }
  try {
    const boot = await fetchJson(cgFkApiUrl(`?action=bootstrap&board_id=${encodeURIComponent(boardId)}&_t=${workspaceNow()}${workspaceShareQuerySuffix()}`));
    if (!boot.is_board_owner) {
      const res = await fetch(cgFkApiUrl(`?action=get_client_view_url&board_id=${encodeURIComponent(boardId)}`), { credentials: cgFetchCredentialsMode() });
      const data = await res.json();
      if (!data.success) {
        alert(data.message || 'Client link not available. Ask the board owner to share the timeline.');
        return;
      }
      window.open(data.url || '', '_blank', 'noopener,noreferrer');
      return;
    }
    const res = await fetch(`/api/freelance_timeline.php?action=get_or_create_chart&board_id=${encodeURIComponent(boardId)}`, { credentials: cgFetchCredentialsMode() });
    const data = await res.json();
    if (!data.success) {
      alert(data.message || 'Failed to open timeline');
      return;
    }
    window.location.href = `project_timeline.php?chart_id=${encodeURIComponent(data.chart_id)}`;
  } catch (err) {
    console.error('Timeline navigation error:', err);
    alert(err.message || 'Failed to open timeline.');
  }
}

