function updateWorkspaceBoardStorageLabel(stats) {
  const el = qs('#workspaceBoardSizeLabel');
  if (!el || !stats) return;
  const activeBytes = Number(stats.active_storage_bytes ?? stats.storage_bytes ?? 0);
  const totalBytes = Number(stats.storage_bytes || 0);
  const trashedBytes = Number(stats.trashed_storage_bytes || 0);
  const activeLabel = String(stats.active_storage_label || '').trim() || formatWorkspaceBoardStorage(activeBytes);
  const totalLabel = String(stats.storage_label || '').trim() || formatWorkspaceBoardStorage(totalBytes);
  const trashedLabel = String(stats.trashed_storage_label || '').trim() || formatWorkspaceBoardStorage(trashedBytes);
  if (activeBytes <= 0 && trashedBytes <= 0) {
    el.textContent = '';
    el.title = 'Workspace canvas storage';
    return;
  }
  el.textContent = `(${activeLabel})`;
  if (trashedBytes > 0) {
    el.title = `Canvas: ${activeLabel} · Recycle bin: ${trashedLabel} · Total: ${totalLabel} (images, storyboards, strokes & attachments on this canvas)`;
  } else {
    el.title = `Workspace canvas storage: ${totalLabel} — images, storyboards, brush strokes & attachments`;
  }
}
