    visibleConnectors: visibleConnectorCount != null ? visibleConnectorCount : 0,
    totalStrokes: freeStrokes.length,
    visibleStrokes: visibleStrokeCount != null ? visibleStrokeCount : 0,
    domNodes: (layer ? layer.childElementCount : 0) + (connSvg ? connSvg.querySelectorAll('.cg-workspace-connector-group').length : 0),
