  const stageW = Number(stage.clientWidth || stage.offsetWidth || 0);
  const stageH = Number(stage.clientHeight || stage.offsetHeight || 0);
  const scale = Math.max(0.0001, Number(WS.camera.scale) || 1);
  const camX = Number(WS.camera.x) || 0;
  const camY = Number(WS.camera.y) || 0;
