  const sorted = [...WS.items].sort((a, b) => Number(a.z_index || 0) - Number(b.z_index || 0));
  const ids = [];
  sorted.forEach((item) => {
    const el = document.querySelector(`.cg-workspace-item[data-item-id="${item.id}"]`);
    if (!el) return;
    const r = el.getBoundingClientRect();
    if (r.right >= left && r.left <= right && r.bottom >= top && r.top <= bottom) {
