    renderConnectors();
    renderHeader();
    updateEmptyState();
    updateConnectorButton();
    try {
      await Promise.all(existingConnectorIds.map(connectorId => deleteWorkspaceConnector(connectorId)));
    } catch (err) {
      WS.connectors = previousConnectors;
      renderConnectors();
      renderHeader();
      updateEmptyState();
