    for (let s = 1; s <= steps; s += 1) {
      const t = s / steps;
      out.push({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t });
    }
  }
  return out;
}
function pointNearAnySample(pt, samples, radius) {
  const r = Math.max(0.5, Number(radius) || 1);
  const r2 = r * r;
  for (let i = 0; i < samples.length; i += 1) {
    const s = samples[i];
    const dx = pt.x - s.x;
    const dy = pt.y - s.y;
    if (dx * dx + dy * dy <= r2) return true;
  }
  return false;
}
function splitPolylineByPointRemoval(points, shouldRemove) {
  const segments = [];
  let cur = [];
  points.forEach((p) => {
    if (shouldRemove(p)) {
      if (cur.length >= 2) segments.push(cur);
      cur = [];
    } else {
      cur.push(p);
    }
  });
  if (cur.length >= 2) segments.push(cur);
  return segments;
}
/** Map world point to stroke-local coordinates for image or brush_card overlay. */
function worldPointToAttachedStrokeLocal(item, worldPoint) {
  if (!item || !worldPoint) return { x: 0, y: 0 };
  const vb = getWorkspaceAttachedStrokeViewBoxSize(item);
  const localX = Number(worldPoint.x || 0) - Number(item.x || 0);
  const localY = Number(worldPoint.y || 0) - Number(item.y || 0);
  const currW = Math.max(1, Number(item.width || 1));
  const currH = Math.max(1, Number(item.height || 1));
  return {
    x: localX * (vb.viewW / currW),
    y: localY * (vb.viewH / currH),
  };
}
/** rAF-coalesced local eraser preview (no network during drag). */
let workspaceEraserRafId = null;
let workspaceEraserLocalKeySeed = 0;

function resetWorkspaceEraserPersist() {
  WS.eraserPersist = {
    serverDeletes: new Set(),
    saveByKey: new Map(),
  };
}

function queueEraserRemovePendingSave(stroke) {
  const p = WS.eraserPersist;
  if (!p || !stroke) return;
  const sid = Number(stroke.id);
  if (sid > 0) p.saveByKey.delete(`u:${sid}`);
  else if (stroke._eraserLocalKey) p.saveByKey.delete(`c:${stroke._eraserLocalKey}`);
}

function queueEraserServerDelete(serverId) {
  const id = Number(serverId);
  if (!(id > 0)) return;
  const p = WS.eraserPersist;
  if (!p) return;
  p.serverDeletes.add(id);
  p.saveByKey.delete(`u:${id}`);
}

function queueEraserSaveStroke(stroke) {
  const p = WS.eraserPersist;
  if (!p || !stroke) return;
  const sid = Number(stroke.id);
  if (!(sid > 0)) {
    if (!stroke._eraserLocalKey) {
      workspaceEraserLocalKeySeed += 1;
      stroke._eraserLocalKey = `lk_${workspaceEraserLocalKeySeed}`;
    }
    p.saveByKey.set(`c:${stroke._eraserLocalKey}`, stroke);
  } else {
    p.saveByKey.set(`u:${sid}`, stroke);
  }
}

/** Mutates WS.strokes + render only; queues server work for persistWorkspaceEraserDrag. */
function applyWorkspaceEraserSessionLocal(session) {
  if (!session || workspaceIsClientView()) return;
  if (!WS.eraserPersist) resetWorkspaceEraserPersist();
  const rawSamples = Array.isArray(session.samples) ? session.samples : [];
  if (!rawSamples.length) return;
  const radius = Math.max(1.25, getEraserRadius());
  const dense = densifyPolylineSamples(rawSamples, Math.max(1.5, radius * 0.35));
  const targetItemId = Number(session.targetItemId || 0);
  const candidates = WS.strokes.filter((st) => {
    if (String(st.tool || 'brush') !== 'brush') return false;
    if (targetItemId > 0) {
      return strokeHasAttachedItem(st) && Number(st.item_id) === targetItemId;
    }
    return !strokeHasAttachedItem(st);
  });
  const shouldRenderAttached = targetItemId > 0;
  let didChange = false;
  for (const stroke of candidates) {
    const pts = parseWorkspaceStrokePathToPoints(stroke.stroke_data || '');
    if (pts.length < 2) continue;
    const shouldRemove = (p) => pointNearAnySample(p, dense, radius);
    let removed = 0;
    pts.forEach((p) => { if (shouldRemove(p)) removed += 1; });
    if (removed === 0) continue;
    const segments = splitPolylineByPointRemoval(pts, shouldRemove);
    didChange = true;
    if (!segments.length) {
      const sid = Number(stroke.id);
      WS.strokes = WS.strokes.filter((e) => e !== stroke);
      if (sid > 0) queueEraserServerDelete(sid);
      else queueEraserRemovePendingSave(stroke);
      continue;
    }
    if (segments.length === 1) {
      stroke.stroke_data = pathFromPoints(segments[0]);
      queueEraserSaveStroke(stroke);
      continue;
    }
    const sid = Number(stroke.id);
    WS.strokes = WS.strokes.filter((e) => e !== stroke);
    if (sid > 0) queueEraserServerDelete(sid);
    else queueEraserRemovePendingSave(stroke);
    segments.forEach((seg) => {
      workspaceEraserLocalKeySeed += 1;
      const nu = {
        item_id: stroke.item_id,
        tool: stroke.tool || 'brush',
        stroke_data: pathFromPoints(seg),
        bounds_json: stroke.bounds_json || '',
        style_json: stroke.style_json || '',
        z_index: Number(stroke.z_index || 0),
        _eraserLocalKey: `lk_${workspaceEraserLocalKeySeed}`,
      };
      WS.strokes.push(nu);
      queueEraserSaveStroke(nu);
    });
  }
  if (didChange) {
    workspaceStrokeSpatialIndexRebuild();
    if (shouldRenderAttached) renderItems();
    else scheduleWorkspaceRender({ strokes: true });
  }
}

async function persistWorkspaceEraserDrag(persist) {
  if (!persist) return;
  if (WS.eraserPersist === persist) WS.eraserPersist = null;
  const dels = [...persist.serverDeletes].filter((n) => n > 0).sort((a, b) => a - b);
  for (const id of dels) {
    await deleteWorkspaceStroke(id);
  }
  for (const st of persist.saveByKey.values()) {
    const payload = {
      id: Number(st.id) > 0 ? st.id : undefined,
      item_id: st.item_id,
      tool: st.tool || 'brush',
      stroke_data: st.stroke_data || '',
      bounds_json: st.bounds_json || '',
      style_json: st.style_json || '',
      z_index: Number(st.z_index || 0),
    };
    await saveWorkspaceStroke(payload);
  }
  if (dels.length || persist.saveByKey.size) scheduleWorkspaceHistoryCapture(220);
}

function flushWorkspaceEraserDragSamples() {
  if (!WS.eraserSession || workspaceIsClientView()) return;
  if (!WS.eraserPersist) resetWorkspaceEraserPersist();
  for (;;) {
    const sess = WS.eraserSession;
    if (!sess) return;
    const all = sess.samples;
    if (!Array.isArray(all) || !all.length) return;
    const nAtStart = all.length;
    if (nAtStart < 2) return;
    const snapshot = { targetItemId: sess.targetItemId, samples: all.slice() };
    applyWorkspaceEraserSessionLocal(snapshot);
    if (!WS.eraserSession) return;
    if (WS.eraserSession.samples.length >= nAtStart) {
      WS.eraserSession.samples = WS.eraserSession.samples.slice(nAtStart - 1);
    } else {
      WS.eraserSession.samples = [];
    }
    if (!WS.eraserSession.samples.length) return;
    if (WS.eraserSession.samples.length <= 1) return;
  }
}

function scheduleWorkspaceEraserApplyDuringDrag() {
  if (!WS.eraserSession || workspaceIsClientView()) return;
  if (workspaceEraserRafId != null) return;
  workspaceEraserRafId = requestAnimationFrame(() => {
    workspaceEraserRafId = null;
    try {
      flushWorkspaceEraserDragSamples();
    } catch (err) {
      console.error('Eraser drag apply error:', err);
    }
  });
}

async function clearWorkspaceImageDoodles(itemId) {
  const id = Number(itemId);
  if (!id) return;
  const strokes = getStrokesForItem(id);
  if (!strokes.length) return;
  const doodleOk = typeof window.cgPortalConfirm === 'function'
    ? await window.cgPortalConfirm(`Remove all ${strokes.length} doodle stroke(s) on this image?`, { title: 'Remove doodles' })
    : window.confirm(`Remove all ${strokes.length} doodle stroke(s) on this image?`);
  if (!doodleOk) return;
  for (const st of strokes) {
    await deleteWorkspaceStroke(st.id);
  }
  scheduleWorkspaceHistoryCapture(220);
}
// Smart brush snapping:
// - If the user stops drawing and briefly holds, snap the stroke into a perfect line.
// - If the stroke approximates a circular motion during that hold, snap it into a clean circle.
const WORKSPACE_SMART_BRUSH_SNAP_HOLD_MS = 120;
const WORKSPACE_SMART_BRUSH_STATIONARY_TAIL_POINT_COUNT = 9;

function getNowMs() {
  if (typeof performance !== 'undefined' && performance && typeof performance.now === 'function') return performance.now();
  return Date.now();
}

function distance(a, b) {
  const dx = Number(a.x || 0) - Number(b.x || 0);
  const dy = Number(a.y || 0) - Number(b.y || 0);
  return Math.hypot(dx, dy);
}

function median(values) {
  if (!Array.isArray(values) || !values.length) return 0;
  const sorted = [...values].sort((aa, bb) => aa - bb);
  const mid = Math.floor(sorted.length / 2);
  if (sorted.length % 2 === 0) return (sorted[mid - 1] + sorted[mid]) / 2;
  return sorted[mid];
}

function det3(a, b, c, d, e, f, g, h, i) {
  return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
}

function solve3x3(C, b) {
  // C row-major 3x3, b length 3: solve Cx = b via Cramer's rule.
  const detC = det3(
    C[0][0], C[0][1], C[0][2],
    C[1][0], C[1][1], C[1][2],
    C[2][0], C[2][1], C[2][2]
  );
  if (!Number.isFinite(detC) || Math.abs(detC) < 1e-9) return null;

  const detD = det3(
    b[0], C[0][1], C[0][2],
    b[1], C[1][1], C[1][2],
    b[2], C[2][1], C[2][2]
  );
  const detE = det3(
    C[0][0], b[0], C[0][2],
    C[1][0], b[1], C[1][2],
    C[2][0], b[2], C[2][2]
  );
  const detF = det3(
    C[0][0], C[0][1], b[0],
    C[1][0], C[1][1], b[1],
    C[2][0], C[2][1], b[2]
  );

  return [detD / detC, detE / detC, detF / detC];
}

function isBrushStrokeStationaryAtEnd(points, brushSize) {
  if (!Array.isArray(points) || points.length < 4) return false;
  const last = points[points.length - 1];
  const stationaryEps = Math.max(0.9, Number(brushSize || 3.5) * 0.75);
  const tailCount = Math.min(points.length, WORKSPACE_SMART_BRUSH_STATIONARY_TAIL_POINT_COUNT);
  const tailDists = [];
  for (let i = points.length - tailCount; i < points.length; i += 1) {
    tailDists.push(distance(points[i], last));
  }
  tailDists.sort((a, b) => a - b);
  const tailMed = median(tailDists);
  const tailP90 = tailDists[Math.floor(0.9 * Math.max(0, tailDists.length - 1))] || 0;

  // Also require a bit of actual stroke length so we don't snap tiny dots.
  const span = distance(points[0], points[points.length - 1]);
  return span >= stationaryEps * 1.4
    && tailMed <= stationaryEps * 1.15
    && tailP90 <= stationaryEps * 2.7;
}

function fitLine(points, brushSize) {
  if (!Array.isArray(points) || points.length < 3) return null;
  const start = points[0];
  const end = points[points.length - 1];
  const ax = Number(start.x || 0);
  const ay = Number(start.y || 0);
  const bx = Number(end.x || 0);
  const by = Number(end.y || 0);
  const dx = bx - ax;
  const dy = by - ay;
  const len = Math.hypot(dx, dy);
  if (len < Math.max(6, Number(brushSize || 3.5) * 3.0)) return null;

  // Distance from point to infinite line through start/end.
  const denom = len || 1;
  const dists = [];
  let maxDist = 0;
  for (const p of points) {
    const px = Number(p.x || 0);
    const py = Number(p.y || 0);
    const cross = Math.abs((px - ax) * dy - (py - ay) * dx);
    const dist = cross / denom;
    dists.push(dist);
    maxDist = Math.max(maxDist, dist);
  }
  const med = median(dists);
  const lineTol = Math.max(1.0, Number(brushSize || 3.5) * 0.6);
  const passes = med <= lineTol && maxDist <= lineTol * 2.3;
  if (!passes) return null;

  return {
    snapType: 'line',
    quality: med / lineTol, // lower is better
    snappedPoints: [start, end],
  };
}

function fitCircleLeastSquares(points) {
  if (!Array.isArray(points) || points.length < 6) return null;

  // Fit x^2 + y^2 + D*x + E*y + F = 0 (least squares), then:
  // center = (-D/2, -E/2), radius^2 = center.x^2 + center.y^2 - F
  const n = points.length;
  let sumX = 0;
  let sumY = 0;
  let sumX2 = 0;
  let sumY2 = 0;
  let sumXY = 0;
  let sumB = 0; // sum of -(x^2+y^2)
  let sumXB = 0; // sum x * -(x^2+y^2)
  let sumYB = 0; // sum y * -(x^2+y^2)

  for (const p of points) {
    const x = Number(p.x || 0);
    const y = Number(p.y || 0);
    const x2 = x * x;
    const y2 = y * y;
    const b = -(x2 + y2);
    sumX += x;
    sumY += y;
    sumX2 += x2;
    sumY2 += y2;
    sumXY += x * y;
    sumB += b;
    sumXB += x * b;
    sumYB += y * b;
  }

  // A^T A
  const C = [
    [sumX2, sumXY, sumX],
    [sumXY, sumY2, sumY],
    [sumX, sumY, n],
  ];
  const bb = [sumXB, sumYB, sumB];

  const sol = solve3x3(C, bb);
  if (!sol) return null;
  const D = sol[0];
  const E = sol[1];
  const F = sol[2];

  const cx = -D / 2;
  const cy = -E / 2;
  const rSq = cx * cx + cy * cy - F;
  if (!Number.isFinite(rSq) || rSq <= 0) return null;
  const r = Math.sqrt(rSq);

  // Residual in a scale-free relative unit.
  let sumAbs = 0;
  const angles = points.map(p => Math.atan2(Number(p.y || 0) - cy, Number(p.x || 0) - cx));
  for (let i = 0; i < points.length; i += 1) {
    const px = Number(points[i].x || 0);
    const py = Number(points[i].y || 0);
    const dist = Math.hypot(px - cx, py - cy);
    sumAbs += Math.abs(dist - r);
  }
  const meanAbs = sumAbs / points.length;
  const residualRel = meanAbs / Math.max(1e-6, r);

  // Estimate arc span (signed) by unwrapping angles in stroke order.
  let sumDelta = 0;
  for (let i = 1; i < angles.length; i += 1) {
    let delta = angles[i] - angles[i - 1];
    while (delta > Math.PI) delta -= 2 * Math.PI;
    while (delta < -Math.PI) delta += 2 * Math.PI;
    sumDelta += delta;
  }

  return {
    cx,
    cy,
    r,
    residualRel,
    angleSpanAbs: Math.abs(sumDelta),
    angleSum: sumDelta,
    startAngle: angles[0],
  };
}

function snapPointsToCircle(points, circleFit) {
  const { cx, cy, r, angleSum } = circleFit;
  const direction = angleSum >= 0 ? 1 : -1;

  // Estimate how much of the circle the user actually drew using arc length.
  // This is more reliable for partial circles than unwrapped angle sums.
  let arcLen = 0;
  for (let i = 1; i < points.length; i += 1) {
    arcLen += distance(points[i - 1], points[i]);
  }
  const arcAngleEstimate = Math.max(0, Math.min(2 * Math.PI, arcLen / Math.max(1e-6, r)));

  const wantsFullCircle = arcAngleEstimate >= Math.PI * 1.75; // ~87.5% of full circle

  // Start angle comes from the stroke start point (not the first point in the fit subset).
  const startAngle = Math.atan2(Number(points[0].y || 0) - cy, Number(points[0].x || 0) - cx);

  const steps = clamp(
    Math.round(Math.max(18, Math.min(72, points.length * 1.6))),
    18,
    86
  );

  const totalAngle = wantsFullCircle ? direction * 2 * Math.PI : direction * arcAngleEstimate;

  const out = [];
  if (wantsFullCircle) {
    for (let i = 0; i <= steps; i += 1) {
      const t = i / steps;
      const ang = startAngle + totalAngle * t;
      out.push({ x: cx + r * Math.cos(ang), y: cy + r * Math.sin(ang) });
    }
    // Ensure closure with identical first/last point.
    if (out.length >= 2) out[out.length - 1] = { ...out[0] };
  } else {
    for (let i = 0; i < steps; i += 1) {
      const t = steps === 1 ? 0 : i / (steps - 1);
      const ang = startAngle + totalAngle * t;
      out.push({ x: cx + r * Math.cos(ang), y: cy + r * Math.sin(ang) });
    }
  }
  return out;
}

function applySmartBrushConstraint(points, brushSize, opts) {
  opts = opts || {};
  const shiftAssist = !!opts.shiftAssist;
  if (!Array.isArray(points) || points.length < 2) return points;
  const bSize = Number(brushSize || 3.5);
  if (!Number.isFinite(bSize) || bSize <= 0) return points;

  const circleFit = points.length >= 8 ? fitCircleLeastSquares(points) : null;

  // Circle intent gate.
  let circleOk = null;
  if (circleFit) {
    // Shift+draw: no stationary hold required. Otherwise require end hold / stationary tail.
    const circleStationaryOk = shiftAssist ? true : isBrushStrokeStationaryAtEnd(points, bSize);
    if (circleStationaryOk) {
      // Use the same arc-length based estimate as snap generation.
      let arcLen = 0;
      for (let i = 1; i < points.length; i += 1) arcLen += distance(points[i - 1], points[i]);
      const arcAngleEstimate = Math.max(0, Math.min(2 * Math.PI, arcLen / Math.max(1e-6, circleFit.r)));

      const minRadius = Math.max(10, bSize * 1.0);
      const circleTolRel = 0.12;
      const minArcSpan = Math.PI * 0.55; // allow more partial circles
      circleOk = circleFit.r >= minRadius
        && circleFit.residualRel <= circleTolRel
        && arcAngleEstimate >= minArcSpan;
    }
  }
  if (circleFit && circleOk) return snapPointsToCircle(points, circleFit);

  // Shift+draw: straight line from first to last point (no tail straightness gate).
  if (shiftAssist) {
    return [{ ...points[0] }, { ...points[points.length - 1] }];
  }

  // Line intent gate: only snap if the stroke tail is approximately straight.
  const tailCount = Math.max(6, Math.min(points.length, Math.ceil(points.length * 0.45)));
  const tailStartIdx = Math.max(0, points.length - tailCount);
  const fitTail = points.slice(tailStartIdx);
  const lineFit = fitLine(fitTail, bSize);
  if (!lineFit) return null;

  return [{ ...points[0] }, { ...points[points.length - 1] }];
}

function shouldSmartSnapBrushStroke(drawing, pointsToSnap, heldElapsedMs) {
  if (!drawing || !Array.isArray(pointsToSnap) || pointsToSnap.length < 2) return false;
  const brushSize = Number(drawing.size || 3.5);
  if (!Number.isFinite(brushSize) || brushSize <= 0) return false;
  const minHeldMs = Math.round(WORKSPACE_SMART_BRUSH_SNAP_HOLD_MS * 0.55);
  if (!Number.isFinite(heldElapsedMs) || heldElapsedMs < minHeldMs) return false;
  // Require stationary end + meaningful length.
  if (!isBrushStrokeStationaryAtEnd(pointsToSnap, brushSize)) return false;
  const span = distance(pointsToSnap[0], pointsToSnap[pointsToSnap.length - 1]);
  const minSpan = Math.max(6, brushSize * 1.4);
  if (span < minSpan) return false;

  // Intent gate: either the tail is approximately a line, or it's a decent circle.
  const tailCount = Math.max(6, Math.min(pointsToSnap.length, Math.ceil(pointsToSnap.length * 0.45)));
  const fitTail = pointsToSnap.slice(Math.max(0, pointsToSnap.length - tailCount));
  const lineFit = fitLine(fitTail, brushSize);
  const circleFit = pointsToSnap.length >= 8 ? fitCircleLeastSquares(pointsToSnap) : null;

  // Circle validity gate (same style thresholds as applySmartBrushConstraint).
  let circleOk = null;
  if (circleFit) {
    let arcLen = 0;
    for (let i = 1; i < pointsToSnap.length; i += 1) arcLen += distance(pointsToSnap[i - 1], pointsToSnap[i]);
    const arcAngleEstimate = Math.max(0, Math.min(2 * Math.PI, arcLen / Math.max(1e-6, circleFit.r)));
    const minRadius = Math.max(10, brushSize * 1.0);
    const circleTolRel = 0.12;
    const minArcSpan = Math.PI * 0.55;
    circleOk = circleFit.r >= minRadius
      && circleFit.residualRel <= circleTolRel
      && arcAngleEstimate >= minArcSpan;
  }

  return !!lineFit || !!(circleFit && circleOk);
}

function cancelSmartBrushSnapTimer() {
  if (!WS.drawing) return;
  if (WS.drawing.smartSnapTimerId) {
    clearTimeout(WS.drawing.smartSnapTimerId);
    WS.drawing.smartSnapTimerId = null;
  }
}

function scheduleSmartBrushSnapTimer() {
  cancelSmartBrushSnapTimer();
  if (!WS.drawing) return;
  const drawing = WS.drawing;
  drawing.smartSnapApplied = false;
  const brushHoldMs = WORKSPACE_SMART_BRUSH_SNAP_HOLD_MS;

  drawing.smartSnapTimerId = window.setTimeout(() => {
    if (!WS.drawing || WS.drawing !== drawing) return;
    if (drawing.smartSnapApplied) return;

    const heldElapsedMs = getNowMs() - Number(drawing.lastMoveTime || 0);
    const pointsToSnap = drawing.targetItemId ? drawing.localPoints : drawing.points;
    if (!shouldSmartSnapBrushStroke(drawing, pointsToSnap, heldElapsedMs)) return;

    const brushSize = Number(drawing.size || 3.5);
    const snapped = applySmartBrushConstraint(pointsToSnap, brushSize);
    if (!snapped || !Array.isArray(snapped) || snapped.length < 2) return;

    if (drawing.targetItemId) {
      drawing.localPoints = snapped;
      drawing.localPreviewPath = pathFromPoints(snapped);
    } else {
      drawing.points = snapped;
      drawing.previewPath = pathFromPoints(snapped);
    }

    drawing.smartSnapApplied = true;
    drawing.smartSnapMode = snapped.length > 2 ? 'circle' : 'line';
    // Keep anchor stable so line direction can be updated while holding.
    if (drawing.smartSnapMode === 'line') {
      drawing.smartSnapAnchorWorld = { ...(drawing.points?.[0] || pointsToSnap[0]) };
      drawing.smartSnapAnchorLocal = { ...(drawing.localPoints?.[0] || pointsToSnap[0]) };
      drawing.smartSnapFixedPoints = null;
      drawing.smartSnapFixedLocalPoints = null;
    } else {
      // For circles, freeze the generated points so wobble while holding doesn't
      // corrupt the snapped geometry.
      if (drawing.targetItemId) {
        drawing.smartSnapFixedLocalPoints = snapped.map(p => ({ ...p }));
        drawing.smartSnapFixedPoints = null;
      } else {
        drawing.smartSnapFixedPoints = snapped.map(p => ({ ...p }));
        drawing.smartSnapFixedLocalPoints = null;
      }
    }
    // Ensure the snapped preview renders immediately while the pointer is still down.
    if (drawing.targetItemId) {
      renderItems();
    } else {
      renderStrokes();
    }
  }, brushHoldMs + 12); // tiny jitter to avoid edge timing issues
}

/** Shift held or pressed mid-stroke: straight line preview (full points kept) or circle snap when the stroke fits. */
function refreshBrushShiftShapeAssist(drawing) {
  if (!drawing) return false;
  const brushSize = Number(drawing.size || 3.5);
  const pointsForSnap = drawing.targetItemId ? drawing.localPoints : drawing.points;
