async function buildWorkspaceCastCompositeSketchBlob(characters) {
  const entries = (characters || [])
    .map((ch) => ({ ch, url: workspaceCharacterPortraitUrl(ch) }))
    .filter((e) => e.url)
    .slice(0, 3);
  if (entries.length < 2) return null;
  try {
    const images = await Promise.all(entries.map(async (e) => {
      const res = await fetch(e.url, { credentials: cgFetchCredentialsMode(), cache: 'no-store' });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      return loadImageElement(blob);
    }));
    const cellW = 220;
    const cellH = 280;
    const gap = 10;
    const canvas = document.createElement('canvas');
    canvas.width = images.length * cellW + (images.length - 1) * gap;
    canvas.height = cellH;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    images.forEach((img, i) => {
      const scale = Math.min(cellW / img.naturalWidth, cellH / img.naturalHeight);
      const w = img.naturalWidth * scale;
      const h = img.naturalHeight * scale;
      const x = i * (cellW + gap) + (cellW - w) / 2;
      const y = (cellH - h) / 2;
      ctx.drawImage(img, x, y, w, h);
