  if (!item || item.item_type !== WORKSPACE_STORYBOARD_ITEM_TYPE) return;
  const { meta, rows: sbRows, cols: sbCols, cells, characters } = parseStoryboardSheetModel(item.meta_json);
  const i = Number(cellIndex);
  if (!Number.isFinite(i) || i < 0 || i >= cells.length) return;
  const nextPath = imagePatch && imagePatch.image_path != null ? String(imagePatch.image_path).trim() : String(cells[i].image_path || '').trim();
  const nextDisplay = imagePatch && imagePatch.image_display_url != null ? String(imagePatch.image_display_url).trim() : '';
  cells[i] = { ...cells[i], image_path: nextPath, image_display_url: nextDisplay };
  item.meta_json = stringifyStoryboardSheetMeta(meta, sbRows, sbCols, cells, characters);
  const storyIdx = WS.items.findIndex((e) => Number(e.id) === Number(itemId));
  if (storyIdx >= 0) WS.items[storyIdx] = item;
  const hasImage = !!(nextPath || nextDisplay);
  if (!transient || hasImage) {
    workspaceProtectStoryboardMeta(Number(itemId), item.meta_json);
  } else {
    workspaceClearStoryboardMetaProtect(Number(itemId));
  }
  renderWorkspace();
  if (!transient) {
    scheduleWorkspaceHistoryCapture();
    try {
      const c = window.__cgWorkspaceCollab;
      if (c && typeof c.upsertItem === 'function') c.upsertItem(item);
    } catch (e) {}
