async function uploadStoryboardImageToCell(itemId, cellIndex, file) {
  if (!file || workspaceIsClientView()) return;
  let blobUrl = '';
  WS.workspaceImageUploadDepth = (WS.workspaceImageUploadDepth || 0) + 1;
  try {
    setWorkspaceStoryboardCellUpload(itemId, cellIndex, {
      progress: 2,
      label: 'Preparing image...',
      serverWait: false,
      wireTail: false,
    });
    blobUrl = URL.createObjectURL(file);
    setWorkspaceStoryboardCellUpload(itemId, cellIndex, { blobUrl });
    applyWorkspaceStoryboardCellImage(itemId, cellIndex, { image_path: '', image_display_url: blobUrl }, { transient: true });
    setWorkspaceStoryboardCellUpload(itemId, cellIndex, { progress: 4 });
    const imageEl = await loadImageElement(file);
    setWorkspaceStoryboardCellUpload(itemId, cellIndex, { progress: 6, label: 'Compressing...' });
    const optimizedFile = await workspaceEncodeStoryboardUploadFile(file, imageEl);
    setWorkspaceStoryboardCellUpload(itemId, cellIndex, { progress: 8, label: 'Uploading image...' });
    const formData = new FormData();
    formData.append('board_id', String(WS.boardId));
    formData.append('image', optimizedFile, optimizedFile.name || 'storyboard-shot.jpg');
    appendWorkspaceShareToFormData(formData);
    const data = await uploadJsonWithProgress('/api/freelance_kanban.php?action=upload_workspace_image', formData, (percent) => {
      if (percent < 0) {
        setWorkspaceStoryboardCellUpload(itemId, cellIndex, {
          progress: 99,
          label: 'Saving on server...',
          serverWait: true,
          wireTail: false,
        });
        return;
      }
      const p = clamp(percent, 8, 99);
      const patch = { progress: p, serverWait: false };
      if (p >= 99) {
        patch.wireTail = true;
        patch.label = 'Finishing upload…';
      } else {
        patch.wireTail = false;
        patch.label = 'Uploading image...';
      }
      setWorkspaceStoryboardCellUpload(itemId, cellIndex, patch);
    });
    const path = String(data.image_path || '').trim();
    if (!path) throw new Error('Upload failed');
    const normRel = workspaceImageNormalizeStoredRelPath(path) || workspaceImageExtractUploadsPath(path) || path;
    const apiUrl = workspaceImageApiUrlForRelPath(normRel) || buildWorkspacePublicImageUrl(normRel) || '';
    clearWorkspaceStoryboardCellUpload(itemId, cellIndex);
    applyWorkspaceStoryboardCellImage(itemId, cellIndex, {
      image_path: normRel,
      image_display_url: apiUrl,
    });
    scheduleWorkspaceBoardStorageRefresh();
  } catch (err) {
    clearWorkspaceStoryboardCellUpload(itemId, cellIndex);
    applyWorkspaceStoryboardCellImage(itemId, cellIndex, { image_path: '', image_display_url: '' }, { transient: true });
    alert(workspaceUserFacingErrorMessage(err, 'Could not add image to this shot.'));
  } finally {
    WS.workspaceImageUploadDepth = Math.max(0, (WS.workspaceImageUploadDepth || 0) - 1);
    if (blobUrl) {
      try {
        URL.revokeObjectURL(blobUrl);
      } catch (e) {}
    }
  }
}
function bindWorkspaceStoryboardCellImportDnD() {
