  layer.dataset.storyboardCellDnDBound = '1';
  layer.addEventListener('change', (e) => {
    const t = e.target;
    if (!t || !t.classList || !t.classList.contains('cg-workspace-storyboard-cell__file-input')) return;
    const dz = t.closest('[data-storyboard-upload]');
    if (!dz || workspaceIsClientView()) return;
    const f = t.files && t.files[0];
    try {
      t.value = '';
