async function downloadStoryboardCellImage(itemId, cellIndex) {
  const item = getItemById(itemId);
  if (!item || item.item_type !== WORKSPACE_STORYBOARD_ITEM_TYPE) return;
  const { cells } = parseStoryboardSheetModel(item.meta_json);
  const i = Number(cellIndex);
  if (!Number.isFinite(i) || i < 0 || i >= cells.length) return;
  const cell = cells[i];
  const url = workspaceStoryboardCellImageDownloadUrl(cell);
  if (!url) {
    alert('Could not resolve image URL.');
    return;
  }
  const shotLabel = String(cell.shot || `shot-${i + 1}`).replace(/[^a-zA-Z0-9._-]+/g, '_').replace(/^_|_$/g, '') || `shot-${i + 1}`;
  const filename = workspaceImageDownloadFilename(url, `storyboard-${itemId}-${shotLabel}`);
  try {
    const res = await fetch(url, { credentials: 'same-origin', mode: 'cors' });
    if (!res.ok) throw new Error('bad status');
    const blob = await res.blob();
    const objectUrl = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = objectUrl;
    a.download = filename;
    a.rel = 'noopener';
    document.body.appendChild(a);
    a.click();
    a.remove();
    window.setTimeout(() => URL.revokeObjectURL(objectUrl), 4000);
  } catch (err) {
    try {
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      a.rel = 'noopener noreferrer';
      a.target = '_blank';
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (e2) {
      window.open(url, '_blank', 'noopener,noreferrer');
    }
  }
}
