function applyStoryboardCellToAiPromptControls(cell) {
  const styleEl = qs('#workspaceAiStyle');
  if (styleEl) styleEl.value = 'storyboard';
  syncWorkspaceAiPhotoFiltersForStyle();
  const shotSel = qs('#workspaceAiStoryboardShot');
  const angSel = qs('#workspaceAiStoryboardAngle');
  if (!shotSel || !angSel) return;
  const detail = String(cell?.camera_detail || '');
  const norm = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
  const dFull = norm(detail);
  const chunks = detail.split(/\s*(?:[·|]|\/|—|-)\s*|\s+-\s+/).map((s) => s.trim()).filter(Boolean);
  const matchOption = (options) => {
    const sorted = [...options].filter((o) => o.value).sort((a, b) => String(b.label).length - String(a.label).length);
    for (const o of sorted) {
      const on = norm(o.label);
      if (!on) continue;
      if (dFull.includes(on)) return o.value;
      for (const c of chunks) {
        const cn = norm(c);
        if (cn.includes(on) || on.includes(cn)) return o.value;
      }
    }
    return '';
  };
  const shotVal = matchOption(WS_AI_STORYBOARD_SHOT_OPTIONS);
  const angVal = matchOption(WS_AI_STORYBOARD_ANGLE_ONLY_OPTIONS);
  if (shotVal) shotSel.value = shotVal;
  if (angVal) angSel.value = angVal;
}
