      visibleCount = renderVisibleItems({ rebuildVisible: true });
    }
  }
  const sorted = workspaceGetRenderableItems();
  updateWorkspaceTableSelectionUi();
  setActiveItem(WS.activeItemId);
  updateEmptyState();
  processInstagramEmbeds();
  if (!WS.resize) {
    positionWorkspaceTextCardToolbar();
  }
  workspaceUpdatePerfStats(visibleCount, null, null, null);
}
function connectorHiddenBecauseLayerHidden(connector) {
  const fromItem = connector.from_item_id ? getItemById(connector.from_item_id) : null;
  const toItem = connector.to_item_id ? getItemById(connector.to_item_id) : null;
  if (fromItem && (isWorkspaceItemLayerHidden(fromItem) || workspaceItemHiddenFromCanvas(fromItem))) return true;
  if (toItem && (isWorkspaceItemLayerHidden(toItem) || workspaceItemHiddenFromCanvas(toItem))) return true;
  return false;
}
function ensureConnectorBounds(connector) {
  if (!connector) return connector;
  const fromItem = connector.from_item_id ? getItemById(connector.from_item_id) : null;
  const toItem = connector.to_item_id ? getItemById(connector.to_item_id) : null;
  let start;
  let end;
  if (fromItem && toItem) {
    const pts = getConnectorEndpointsForItems(fromItem, toItem);
    start = pts.start;
    end = pts.end;
  } else {
    start = fromItem ? getItemAnchor(fromItem) : { x: Number(connector.start_x || 0), y: Number(connector.start_y || 0) };
    end = toItem ? getItemAnchor(toItem) : { x: Number(connector.end_x || 0), y: Number(connector.end_y || 0) };
  }
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const len = Math.hypot(dx, dy) || 1;
  const ux = dx / len;
  const uy = dy / len;
  const controlDist = Math.min(Math.max(48, len * 0.38), len * 0.55);
  const xs = [start.x, end.x, start.x + ux * controlDist, end.x - ux * controlDist];
  const ys = [start.y, end.y, start.y + uy * controlDist, end.y - uy * controlDist];
  const pad = 24;
  connector.minX = Math.min(...xs) - pad;
  connector.minY = Math.min(...ys) - pad;
  connector.maxX = Math.max(...xs) + pad;
  connector.maxY = Math.max(...ys) + pad;
  return connector;
}
function isConnectorVisible(connector, bounds) {
  ensureConnectorBounds(connector);
  return !workspaceBoundsSeparated(connector.minX, connector.minY, connector.maxX, connector.maxY, bounds);
}
function ensureStrokeBounds(stroke) {
  if (!stroke) return stroke;
  const dataKey = String(stroke.stroke_data || '');
  if (stroke._boundsStrokeData === dataKey && Number.isFinite(stroke.minX)) return stroke;
  const pts = parseWorkspaceStrokePathToPoints(dataKey);
  if (!pts.length) {
    stroke.minX = 0;
    stroke.minY = 0;
    stroke.maxX = 0;
    stroke.maxY = 0;
  } else {
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    pts.forEach((p) => {
      minX = Math.min(minX, p.x);
      minY = Math.min(minY, p.y);
      maxX = Math.max(maxX, p.x);
      maxY = Math.max(maxY, p.y);
    });
    const sw = Number(parseMaybeJson(stroke.style_json, {}).size || 3);
    const pad = sw + 4;
    stroke.minX = minX - pad;
    stroke.minY = minY - pad;
    stroke.maxX = maxX + pad;
    stroke.maxY = maxY + pad;
  }
  stroke._boundsStrokeData = dataKey;
  return stroke;
}
function isStrokeVisible(stroke, bounds) {
  ensureStrokeBounds(stroke);
  return !workspaceBoundsSeparated(stroke.minX, stroke.minY, stroke.maxX, stroke.maxY, bounds);
}
function renderConnectors() {
  return syncVisibleConnectors(getVisibleBounds());
}
function renderStrokes() {
  const svg = qs('#workspaceStrokeLayer');
  if (svg) svg.innerHTML = '';
