}
function renderWorkspace() {
  renderHeader();
  renderItems();
  renderConnectors();
  renderStrokes();
  renderMode();
  applyCamera();
}
function isMissingBoardIdError(err) {
  const msg = String(err?.message || err || '').toLowerCase();
  return msg.includes('missing board_id');
}
