  overlay.setAttribute('aria-hidden', 'true');
  workspaceLoadOverlayVisible = false;
}
function beginWorkspaceLoadingOverlayDelay() {
  if (workspaceLoadOverlayDelayTimer) {
    clearTimeout(workspaceLoadOverlayDelayTimer);
    workspaceLoadOverlayDelayTimer = null;
  }
  workspaceLoadOverlayDelayTimer = setTimeout(() => {
    workspaceLoadOverlayDelayTimer = null;
    showWorkspaceLoadingOverlay();
  }, 280);
}
function endWorkspaceLoadingOverlayDelay() {
  if (workspaceLoadOverlayDelayTimer) {
    clearTimeout(workspaceLoadOverlayDelayTimer);
    workspaceLoadOverlayDelayTimer = null;
  }
  if (workspaceLoadOverlayVisible) {
