}
async function loadWorkspaceData() {
  const loadGen = ++workspaceBoardLoadGeneration;
  const boardIdRequested = String(WS.boardId || '').trim();
  beginWorkspaceLoadingOverlayDelay();
  const overlayFailsafe = setTimeout(() => {
    try { endWorkspaceLoadingOverlayDelay(); } catch (e) {}
  }, 12000);
  try {
    if (!String(WS.boardId || '').trim()) {
      try {
        const boot = await fetchJson(cgFkApiUrl(`?action=bootstrap&_t=${workspaceNow()}${workspaceShareQuerySuffix()}`));
        if (boot && boot.board_id != null && String(boot.board_id).trim() !== '') {
          WS.boardId = String(boot.board_id);
          updateHistoryParams();
        }
      } catch (err) {
        console.error('Workspace board resolution:', err);
        return;
      }
    }
    if (!String(WS.boardId || '').trim()) {
      return;
    }

    let data;
    try {
      data = await fetchJson(`/api/freelance_kanban.php?action=workspace_bootstrap&board_id=${encodeURIComponent(WS.boardId || '')}&_t=${workspaceNow()}${workspaceShareQuerySuffix()}`);
    } catch (err) {
      if (isMissingBoardIdError(err)) {
        console.warn(err.message || err);
        return;
      }
      throw err;
    }

    if (loadGen !== workspaceBoardLoadGeneration) return;
