  ids.forEach((id) => {
    const item = getItemById(id);
    if (!item) return;
    WS.itemSaveSeq[id] = (WS.itemSaveSeq[id] || 0) + 1;
    const seq = WS.itemSaveSeq[id];
    workspaceInFlightSaves.set(id, seq);
    void saveWorkspaceItem(item, seq).catch(logWorkspaceItemSaveError).finally(() => {
