    if (String(cur.item_type || '') !== 'image') continue;
    const sp = String(cur.image_path || '').trim();
    const ep = String(ent.item.image_path || '').trim();
    if (!sp && ep) {
      cur.image_path = ent.item.image_path;
      if (String(ent.item.image_display_url || '').trim()) cur.image_display_url = ent.item.image_display_url;
