    const id = Number(it.id);
    if (!id) return;
    const key = String(id);
    const t0 = WS.recentlyPositionedItemIds.get(key);
    if (!t0 || now - t0 > WORKSPACE_POSITION_PROTECT_MS) return;
    const prev = prevById.get(id);
    if (!prev) return;
    const px = Number(prev.x || 0);
    const py = Number(prev.y || 0);
    const sx = Number(it.x || 0);
