  renderConnectors();
  renderStrokes();
  renderHeader();
  updateEmptyState();
  setActiveItem(WS.activeItemId);
  if (WS.layersOpen) renderWorkspaceLayersPanel();
}
function scheduleWorkspaceItemRemovalEffects() {
  if (workspaceItemRemovalEffectsRafId != null) return;
  const run = () => renderWorkspaceItemRemovalEffects();
  if (typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function') {
    workspaceItemRemovalEffectsRafId = window.requestAnimationFrame(() => {
      workspaceItemRemovalEffectsRafId = setTimeout(run, 0);
    });
  } else {
    workspaceItemRemovalEffectsRafId = setTimeout(run, 0);
  }
}
function captureWorkspaceItemRemovalSnapshot() {
  return {
    items: [...WS.items],
    connectors: [...WS.connectors],
    strokes: [...WS.strokes],
    activeItemId: WS.activeItemId,
    selectedItemIds: [...WS.selectedItemIds],
  };
}
function restoreWorkspaceItemRemovalSnapshot(snapshot) {
  if (!snapshot) return;
  WS.items = snapshot.items;
  WS.connectors = snapshot.connectors;
  WS.strokes = snapshot.strokes;
  WS.activeItemId = snapshot.activeItemId;
  WS.selectedItemIds = snapshot.selectedItemIds;
  workspaceRebuildAllSpatialIndexes();
  renderWorkspace();
}
function applyWorkspaceItemRemoval(itemId, options = {}) {
  const render = options.render !== false;
  const captureHistory = options.captureHistory !== false;
  const notify = options.notify !== false;
  const idNum = Number(itemId);
  const idStr = String(itemId);

  WS.items = WS.items.filter(entry => Number(entry.id) !== idNum);
  WS.connectors = WS.connectors.filter(entry => Number(entry.from_item_id) !== idNum && Number(entry.to_item_id) !== idNum);
  WS.strokes = WS.strokes.filter(entry => Number(entry.item_id) !== idNum);
  workspaceSpatialIndexRemove(idNum);
  workspaceConnectorSpatialIndexRebuild();
  workspaceStrokeSpatialIndexRebuild();
  if (WS.activeItemId != null && String(WS.activeItemId) === idStr) WS.activeItemId = null;
  WS.selectedItemIds = WS.selectedItemIds.filter((id) => String(id) !== idStr);
  workspaceClearPositionProtection(itemId);
  workspaceClearRecentUploadGuard(itemId);

  if (render) {
