function applyWorkspaceResizeScaleToItem(item, originW, originH, scaleW, scaleH) {
  if (!item) return;
  const t = item.item_type;
  const cm = getWorkspaceItemResizeContentMins(item);
  let loW = cm ? cm.minWidth : 72;
  let loH = cm ? cm.minHeight : 72;
  if (cm) {
    loW = Math.min(loW, Number(originW));
    loH = Math.min(loH, Number(originH));
  }
  if (t === 'image' || t === 'brush_card' || t === 'palette_card') {
    const uniform = Math.min(scaleW, scaleH);
    const ar = t === 'image'
      ? getWorkspaceImageAspectRatio(item)
      : (t === 'brush_card' ? getWorkspaceBrushCardAspectRatio(item) : getWorkspacePaletteCardAspectRatio(item));
    let w = Math.max(1, Number(originW) * uniform);
    let h = Math.max(1, w / Math.max(0.0001, ar));
    if (t === 'palette_card') {
      w = clamp(w, Math.max(220, loW), 1400);
      h = clamp(h, Math.max(28, loH), 220);
    } else {
      w = clamp(w, loW, 960);
      h = clamp(h, loH, 720);
    }
    item.width = w;
    item.height = h;
    if (t === 'palette_card') {
      const meta = parseMaybeJson(item.meta_json, {});
      item.meta_json = JSON.stringify({
        ...meta,
        aspect_ratio: w / Math.max(1, h),
      });
    }
  } else {
    item.width = clamp(Number(originW) * scaleW, loW, 960);
    item.height = clamp(Number(originH) * scaleH, loH, 720);
  }
}
async function deleteWorkspaceItem(itemId, options = {}) {
  const it = getItemById(itemId);
  if (it && isWorkspaceItemLayerLocked(it)) return;
  const snapshot = captureWorkspaceItemRemovalSnapshot();
  applyWorkspaceItemRemoval(itemId, { ...options, captureHistory: false, notify: false });
  const formData = new FormData();
  formData.append('item_id', String(itemId));
  appendWorkspaceShareToFormData(formData);
  try {
    await fetchJson('/api/freelance_kanban.php?action=delete_workspace_item', {
      method: 'POST',
      body: formData
    });
  } catch (err) {
    if (!isWorkspaceItemNotFoundError(err)) {
      restoreWorkspaceItemRemovalSnapshot(snapshot);
      throw err;
    }
  }
  if (options.captureHistory !== false) scheduleWorkspaceHistoryCapture();
  if (options.notify !== false) notifyWorkspaceItemRemoved(itemId);
  scheduleWorkspaceBoardStorageRefresh(0);
}

async function trashWorkspaceItem(itemId, options = {}) {
  const it = getItemById(itemId);
  if (it && isWorkspaceItemLayerLocked(it)) return;
  const snapshot = captureWorkspaceItemRemovalSnapshot();
  applyWorkspaceItemRemoval(itemId, { ...options, captureHistory: false, notify: false });
  const formData = new FormData();
  formData.append('item_id', String(itemId));
  appendWorkspaceShareToFormData(formData);
  try {
    await fetchJson('/api/freelance_kanban.php?action=trash_workspace_item', {
      method: 'POST',
      body: formData
    });
  } catch (err) {
    if (!isWorkspaceItemNotFoundError(err)) {
      restoreWorkspaceItemRemovalSnapshot(snapshot);
      throw err;
    }
  }
  // Hide immediately in the current view. Server keeps strokes/connectors for restore.
  if (options.captureHistory !== false) scheduleWorkspaceHistoryCapture();
  if (options.notify !== false) notifyWorkspaceItemRemoved(itemId);
  scheduleWorkspaceBoardStorageRefresh(0);
}

function getWorkspaceTrashPanel() {
  return qs('#workspaceTrashPanel');
}
function getWorkspaceTrashBackdrop() {
  return qs('#workspaceTrashBackdrop');
}
function getWorkspaceTrashList() {
  return qs('#workspaceTrashList');
}
function getWorkspaceTrashSubtitleEl() {
  return qs('#workspaceTrashSubtitle');
}
function getWorkspaceTrashContextMenuEl() {
  return qs('#workspaceTrashContextMenu');
}
function getWorkspaceLayerGroupContextMenuEl() {
  return qs('#workspaceLayerGroupContextMenu');
}

function workspaceTrashItemLabel(item) {
  const t = String(item?.title || '').trim();
  if (t) return t;
  const c = String(item?.content || '').trim();
  if (c) return c.length > 70 ? `${c.slice(0, 70)}…` : c;
  return 'Untitled';
}

function workspaceTrashItemSnippet(item) {
  const c = String(item?.content || '').trim();
  if (!c) return '';
  return c.length > 140 ? `${c.slice(0, 140)}…` : c;
}

function getTrashStrokesForItem(itemId) {
  const idStr = String(itemId || '').trim();
  if (!idStr) return [];
  return (WS.trashStrokes || []).filter((s) => {
    const sid = s?.item_id;
    return sid != null && String(sid).trim() === idStr;
  });
}

function buildWorkspaceTrashPreview(item) {
  const itemType = item?.item_type || '';
  if (itemType === 'image') {
    const thumbSrc = workspaceItemImagePreviewUrl(item, 120);
    const imgMeta = parseMaybeJson(item.meta_json, {});
    const flipH = !!imgMeta.flip_horizontal;
    const flipV = !!imgMeta.flip_vertical;
    const sx = flipH ? -1 : 1;
    const sy = flipV ? -1 : 1;
    const tf = (flipH || flipV) ? `transform: scale(${sx}, ${sy})` : '';
    return `
      <div class="cg-workspace-trash-item__preview cg-workspace-trash-item__preview--image">
        ${thumbSrc
          ? `<img src="${escapeHtml(thumbSrc)}" alt="" loading="lazy" decoding="async" style="${tf}">`
          : '<div style="padding:10px;color:#64748b;font-weight:800;">No image</div>'}
      </div>
    `;
  }

  if (itemType === 'palette_card') {
    const colors = getPaletteColorsFromItem(item) || [];
    const swatches = colors.slice(0, 10).map((hex) => (
      `<div class="cg-workspace-trash-item__palette-swatch" style="background:${escapeHtml(hex)};"></div>`
    )).join('');
    return `
      <div class="cg-workspace-trash-item__preview cg-workspace-trash-item__preview--palette" aria-hidden="true">
        ${swatches || '<div style="color:#64748b;font-weight:800;">Palette</div>'}
      </div>
    `;
  }

  if (itemType === 'brush_card') {
    const cardWidth = Math.max(Number(item.width || 220), 140);
    const bodyHeight = Math.max(Number(item.height || 180), 80);
    const strokes = getTrashStrokesForItem(item.id);
    const strokeMarkup = strokes.map(stroke => {
      const style = parseMaybeJson(stroke.style_json, {});
      const strokeColor = escapeHtml(resolveWorkspaceStrokeColorForDisplay(style.color));
      const strokeW = Number(style.size || 3);
      const opacity = Number(style.opacity || 1);
      return `
        <path
          d="${escapeHtml(stroke.stroke_data || '')}"
          stroke="${strokeColor}"
          stroke-width="${strokeW}"
          opacity="${opacity}"
          fill="none"
          stroke-linecap="round"
          stroke-linejoin="round"
        ></path>
      `;
    }).join('');
    return `
      <div class="cg-workspace-trash-item__preview cg-workspace-trash-item__preview--sketch">
        <svg viewBox="0 0 ${cardWidth} ${bodyHeight}" preserveAspectRatio="none">
          ${strokeMarkup || ''}
        </svg>
      </div>
    `;
  }

  // Text-like items.
  const previewText = (() => {
    const content = String(item?.content || '').trim();
    if (content) return content.length > 160 ? `${content.slice(0, 160)}…` : content;
    const title = String(item?.title || '').trim();
    return title ? title.length > 120 ? `${title.slice(0, 120)}…` : title : '';
  })();
  return `
    <div class="cg-workspace-trash-item__preview cg-workspace-trash-item__preview--text">
      ${escapeHtml(previewText || '—')}
    </div>
  `;
}

async function loadWorkspaceTrashItems() {
  if (!WS.boardId) return;
  const url = `/api/freelance_kanban.php?action=workspace_trash_bootstrap&board_id=${encodeURIComponent(String(WS.boardId))}${workspaceShareQuerySuffix()}`;
  const data = await fetchJson(url);
  const w = data?.workspace || {};
  WS.trashItems = Array.isArray(w.items) ? w.items : [];
  WS.trashStrokes = Array.isArray(w.strokes) ? w.strokes : [];
  WS.trashConnectors = Array.isArray(w.connectors) ? w.connectors : [];
  // Keep any existing selection/context-menu targets valid after reload.
  const trashIdSet = new Set(WS.trashItems.map(it => Number(it?.id)).filter(n => Number.isFinite(n)));
  WS.trashSelectedItemIds = (WS.trashSelectedItemIds || []).map(n => Number(n)).filter(id => trashIdSet.has(id));
  WS.trashContextItemIds = (WS.trashContextItemIds || []).map(n => Number(n)).filter(id => trashIdSet.has(id));
  if (!WS.trashContextItemIds.length) WS.trashContextItemId = null;
  if (WS.trashOpen) renderWorkspaceTrashList();
}

function applyWorkspaceTrashMasonryLayout() {
  const list = getWorkspaceTrashList();
  if (!list) return;
  const itemEls = Array.from(list.children).filter(el => el?.classList?.contains('cg-workspace-trash-item'));
  if (!itemEls.length) return;

  // Reflow into 2 greedy height-balanced columns (classic masonry look).
  list.innerHTML = '';
  const col1 = document.createElement('div');
  col1.className = 'cg-workspace-trash-masonry__col';
  const col2 = document.createElement('div');
  col2.className = 'cg-workspace-trash-masonry__col';
  list.append(col1, col2);

  for (const itemEl of itemEls) {
    const targetCol = col1.scrollHeight <= col2.scrollHeight ? col1 : col2;
    targetCol.appendChild(itemEl);
  }
}

function syncWorkspaceTrashSelectionUi() {
  const list = getWorkspaceTrashList();
  if (!list) return;
  const selSet = new Set((WS.trashSelectedItemIds || []).map(n => Number(n)).filter(id => Number.isFinite(id)));
  const itemEls = list.querySelectorAll('.cg-workspace-trash-item[data-trash-item-id]');
  for (const el of itemEls) {
    const id = Number(el.getAttribute('data-trash-item-id'));
    const isSelected = selSet.has(id);
    el.classList.toggle('is-selected', isSelected);
    el.setAttribute('aria-selected', isSelected ? 'true' : 'false');
  }
}

function renderWorkspaceTrashList() {
  const list = getWorkspaceTrashList();
  const subtitleEl = getWorkspaceTrashSubtitleEl();
  if (!list) return;
  if (subtitleEl) subtitleEl.textContent = `${WS.trashItems.length} item(s) in Trash`;

  list.innerHTML = WS.trashItems.map((item) => {
    const typeLabel = item.item_type === 'sticky_note'
      ? 'Note'
      : (item.item_type === 'text_card' ? 'Text' : (item.item_type || 'Item'));
    const label = workspaceTrashItemLabel(item);
    const snippet = workspaceTrashItemSnippet(item);
    const isTextCard = item.item_type === 'text_card';
    const previewHtml = isTextCard ? '' : buildWorkspaceTrashPreview(item);
    const showSnippet = snippet && (item.item_type === 'sticky_note' || item.item_type === 'text_card' || item.item_type === 'kanban_card');
    const showLabelLine = !isTextCard;
    return `
      <div class="cg-workspace-trash-item" data-trash-item-id="${item.id}" role="button" tabindex="0">
        ${previewHtml}
        <div class="cg-workspace-trash-item__top">
          <div class="cg-workspace-trash-item__type">${escapeHtml(typeLabel)}</div>
          <div class="cg-workspace-trash-item__id">#${escapeHtml(String(item.id))}</div>
        </div>
        ${showLabelLine ? `<div class="cg-workspace-trash-item__label">${escapeHtml(label)}</div>` : ''}
        ${showSnippet ? `<div class="cg-workspace-trash-item__snippet">${escapeHtml(snippet)}</div>` : ''}
      </div>
    `;
  }).join('');

  applyWorkspaceTrashMasonryLayout();
  syncWorkspaceTrashSelectionUi();
}

function closeWorkspaceTrash() {
  WS.trashOpen = false;
  const panel = getWorkspaceTrashPanel();
  const backdrop = getWorkspaceTrashBackdrop();
  if (panel) {
    panel.hidden = true;
    panel.setAttribute('aria-hidden', 'true');
  }
  if (backdrop) backdrop.hidden = true;
  hideWorkspaceTrashContextMenu();
}

function getWorkspaceLayersSortedItems() {
  return [...workspaceGetRenderableItems()].sort((a, b) => {
    const z = Number(b.z_index || 0) - Number(a.z_index || 0);
    if (z !== 0) return z;
    return Number(b.id || 0) - Number(a.id || 0);
  });
}

const WS_GROUP_META_ID = 'ws_group_id';
const WS_GROUP_META_NAME = 'ws_group_name';
const WS_META_LAYER_HIDDEN = 'ws_layer_hidden';
const WS_META_LAYER_LOCKED = 'ws_layer_locked';

function isWorkspaceItemLayerHidden(item) {
  if (!item) return false;
  return !!parseMaybeJson(item.meta_json, {})[WS_META_LAYER_HIDDEN];
}
function isWorkspaceItemLayerLocked(item) {
  if (!item) return false;
  return !!parseMaybeJson(item.meta_json, {})[WS_META_LAYER_LOCKED];
}
function setWorkspaceItemLayerHidden(item, hidden) {
  if (!item) return;
  const meta = parseMaybeJson(item.meta_json, {});
  if (hidden) meta[WS_META_LAYER_HIDDEN] = true;
  else delete meta[WS_META_LAYER_HIDDEN];
  item.meta_json = JSON.stringify(meta);
}
function setWorkspaceItemLayerLocked(item, locked) {
  if (!item) return;
  const meta = parseMaybeJson(item.meta_json, {});
  if (locked) meta[WS_META_LAYER_LOCKED] = true;
  else delete meta[WS_META_LAYER_LOCKED];
  item.meta_json = JSON.stringify(meta);
}

function parseWorkspaceItemGroupMeta(item) {
  const m = parseMaybeJson(item?.meta_json, {});
  const id = m[WS_GROUP_META_ID];
  if (id === undefined || id === null || id === '') return null;
  const sid = String(id).trim();
  if (!sid) return null;
  const rawName = m[WS_GROUP_META_NAME];
  const name = typeof rawName === 'string' && rawName.trim() ? rawName.trim() : 'Group';
  return { id: sid, name };
}

function setWorkspaceItemGroupMeta(item, groupId, groupName) {
  if (!item) return;
  const meta = parseMaybeJson(item.meta_json, {});
  meta[WS_GROUP_META_ID] = String(groupId);
  meta[WS_GROUP_META_NAME] = String(groupName || 'Group');
  item.meta_json = JSON.stringify(meta);
}

function clearWorkspaceItemGroupMeta(item) {
  if (!item) return;
  const meta = parseMaybeJson(item.meta_json, {});
  delete meta[WS_GROUP_META_ID];
  delete meta[WS_GROUP_META_NAME];
  item.meta_json = JSON.stringify(meta);
}

function generateWorkspaceGroupId() {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return `g_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`;
}

function getWorkspaceLayersGroupExpandedStorageKey() {
  const bid = String(WS.boardId || '').trim() || 'default';
  return `cg_workspace_layers_groups_exp_${bid}`;
}

function ensureWorkspaceLayersGroupExpandedMapLoaded() {
  if (WS.layersGroupExpandedMapLoadedBoardId === WS.boardId && WS.layersGroupExpandedMap && typeof WS.layersGroupExpandedMap === 'object') return;
  WS.layersGroupExpandedMapLoadedBoardId = WS.boardId;
  try {
    const raw = sessionStorage.getItem(getWorkspaceLayersGroupExpandedStorageKey());
    if (!raw) {
      WS.layersGroupExpandedMap = {};
      return;
    }
    const p = JSON.parse(raw);
    WS.layersGroupExpandedMap = (typeof p === 'object' && p && !Array.isArray(p)) ? p : {};
  } catch (e) {
    WS.layersGroupExpandedMap = {};
  }
}

function persistWorkspaceLayersGroupExpandedMap() {
  try {
    sessionStorage.setItem(getWorkspaceLayersGroupExpandedStorageKey(), JSON.stringify(WS.layersGroupExpandedMap || {}));
  } catch (e) {}
}

function isWorkspaceLayerGroupExpanded(groupId) {
  ensureWorkspaceLayersGroupExpandedMapLoaded();
  const m = WS.layersGroupExpandedMap || {};
  if (Object.prototype.hasOwnProperty.call(m, groupId)) return m[groupId] !== false;
  return true;
}

function setWorkspaceLayerGroupExpanded(groupId, expanded) {
  ensureWorkspaceLayersGroupExpandedMapLoaded();
  WS.layersGroupExpandedMap = WS.layersGroupExpandedMap || {};
  WS.layersGroupExpandedMap[groupId] = !!expanded;
  persistWorkspaceLayersGroupExpandedMap();
}

function buildWorkspaceLayersPanelEntries(sorted) {
  const byG = new Map();
  const loose = [];
  for (const item of sorted) {
    const g = parseWorkspaceItemGroupMeta(item);
    if (!g) {
      loose.push({ kind: 'item', item, sortZ: Number(item.z_index || 0) });
      continue;
    }
    if (!byG.has(g.id)) {
      byG.set(g.id, { kind: 'group', id: g.id, items: [] });
    }
    byG.get(g.id).items.push(item);
  }
  const groups = [];
  for (const bundle of byG.values()) {
    bundle.items.sort((a, b) => Number(b.z_index || 0) - Number(a.z_index || 0));
    const first = parseWorkspaceItemGroupMeta(bundle.items[0]);
    bundle.displayName = (first && first.name) ? first.name : 'Group';
    bundle.sortZ = Math.max(...bundle.items.map(i => Number(i.z_index || 0)));
    groups.push(bundle);
  }
  groups.sort((a, b) => b.sortZ - a.sortZ);
  loose.sort((a, b) => b.sortZ - a.sortZ);
  return [...groups, ...loose];
}

function buildWorkspaceLayerRowActionsHtml(item) {
  if (workspaceIsClientView()) return '';
  const id = Number(item.id);
  const hidden = isWorkspaceItemLayerHidden(item);
  const locked = isWorkspaceItemLayerLocked(item);
  const eyeIcon = hidden ? 'fa-eye-slash' : 'fa-eye';
  const eyeTitle = hidden ? 'Show on canvas' : 'Hide on canvas';
  const lockIcon = locked ? 'fa-lock' : 'fa-unlock';
  const lockTitle = locked ? 'Unlock' : 'Lock';
  return `<div class="cg-workspace-layer-row__actions">
    <button type="button" class="cg-workspace-layer-row__action" draggable="false" data-layer-action="visibility" data-layer-item-id="${id}" title="${escapeHtml(eyeTitle)}" aria-label="${escapeHtml(eyeTitle)}"><i class="fas ${eyeIcon}" aria-hidden="true"></i></button>
    <button type="button" class="cg-workspace-layer-row__action" draggable="false" data-layer-action="lock" data-layer-item-id="${id}" title="${escapeHtml(lockTitle)}" aria-label="${escapeHtml(lockTitle)}"><i class="fas ${lockIcon}" aria-hidden="true"></i></button>
  </div>`;
}

function buildWorkspaceLayerGroupActionsHtml(groupItems, gidRaw) {
  if (workspaceIsClientView() || !groupItems.length) return '';
  const allH = groupItems.every(it => isWorkspaceItemLayerHidden(it));
  const allL = groupItems.every(it => isWorkspaceItemLayerLocked(it));
  const eyeIcon = allH ? 'fa-eye-slash' : 'fa-eye';
  const eyeTitle = allH ? 'Show all on canvas' : 'Hide all on canvas';
  const lockIcon = allL ? 'fa-lock' : 'fa-unlock';
  const lockTitle = allL ? 'Unlock group' : 'Lock group';
  const gidEsc = escapeHtml(String(gidRaw || ''));
  return `<div class="cg-workspace-layer-group__actions">
    <button type="button" class="cg-workspace-layer-group__action" data-layer-group-action="visibility" data-group-id="${gidEsc}" title="${escapeHtml(eyeTitle)}" aria-label="${escapeHtml(eyeTitle)}"><i class="fas ${eyeIcon}" aria-hidden="true"></i></button>
    <button type="button" class="cg-workspace-layer-group__action" data-layer-group-action="lock" data-group-id="${gidEsc}" title="${escapeHtml(lockTitle)}" aria-label="${escapeHtml(lockTitle)}"><i class="fas ${lockIcon}" aria-hidden="true"></i></button>
  </div>`;
}

async function toggleWorkspaceLayerItemVisibility(itemId) {
  if (workspaceIsClientView()) return;
  const item = getItemById(itemId);
  if (!item) return;
  setWorkspaceItemLayerHidden(item, !isWorkspaceItemLayerHidden(item));
  updateItemElement(item.id);
  renderConnectors();
  if (WS.layersOpen) renderWorkspaceLayersPanel();
  try {
    await saveWorkspaceItem(item);
  } catch (err) {
    console.error('Layer visibility save error:', err);
  }
}

async function toggleWorkspaceLayerItemLock(itemId) {
  if (workspaceIsClientView()) return;
  const item = getItemById(itemId);
  if (!item) return;
  const next = !isWorkspaceItemLayerLocked(item);
  setWorkspaceItemLayerLocked(item, next);
  updateItemElement(item.id);
  if (next) {
    const nextSel = WS.selectedItemIds.filter((id) => Number(id) !== Number(itemId));
    setSelectedItems(nextSel, nextSel.length ? nextSel[nextSel.length - 1] : null);
  }
  if (WS.layersOpen) renderWorkspaceLayersPanel();
  try {
    await saveWorkspaceItem(item);
  } catch (err) {
    console.error('Layer lock save error:', err);
  }
}

async function toggleWorkspaceLayerGroupVisibility(groupId) {
  if (workspaceIsClientView()) return;
  const gid = String(groupId || '').trim();
  if (!gid) return;
  const items = WS.items.filter(it => parseWorkspaceItemGroupMeta(it)?.id === gid);
  if (!items.length) return;
  const showAll = items.every(it => isWorkspaceItemLayerHidden(it));
  items.forEach((it) => setWorkspaceItemLayerHidden(it, !showAll));
  items.forEach((it) => updateItemElement(it.id));
  renderConnectors();
  if (WS.layersOpen) renderWorkspaceLayersPanel();
  try {
    await Promise.all(items.map(it => saveWorkspaceItem(it)));
  } catch (err) {
    console.error('Group visibility save error:', err);
  }
}

async function toggleWorkspaceLayerGroupLock(groupId) {
  if (workspaceIsClientView()) return;
  const gid = String(groupId || '').trim();
  if (!gid) return;
  const items = WS.items.filter(it => parseWorkspaceItemGroupMeta(it)?.id === gid);
  if (!items.length) return;
  const unlockAll = items.every(it => isWorkspaceItemLayerLocked(it));
  items.forEach((it) => setWorkspaceItemLayerLocked(it, !unlockAll));
  items.forEach((it) => updateItemElement(it.id));
  if (!unlockAll) {
    const idSet = new Set(items.map(it => Number(it.id)));
    const nextSel = WS.selectedItemIds.filter((id) => !idSet.has(Number(id)));
    setSelectedItems(nextSel, nextSel.length ? nextSel[nextSel.length - 1] : null);
  }
  if (WS.layersOpen) renderWorkspaceLayersPanel();
  try {
    await Promise.all(items.map(it => saveWorkspaceItem(it)));
  } catch (err) {
    console.error('Group lock save error:', err);
  }
}

function buildWorkspaceLayerRowHtml(item, selectedSet, nested, groupIdStr = '') {
  const id = Number(item.id);
  const type = itemTypeLabel(item.item_type || 'sticky_note');
  const label = escapeHtml(getWorkspaceLayerRowLabel(item));
  const sel = selectedSet.has(id);
  const thumb = buildWorkspaceLayerPreview(item);
  const nest = nested ? ' cg-workspace-layer-row--nested' : '';
  const gidAttr = escapeHtml(String(groupIdStr || ''));
  const drag = workspaceIsClientView()
    ? ''
    : `<span class="cg-workspace-layer-row__drag" draggable="false" title="Drag handle" aria-hidden="true"><i class="fas fa-grip-vertical" aria-hidden="true"></i></span>`;
  const actions = buildWorkspaceLayerRowActionsHtml(item);
  const rowDrag = workspaceIsClientView() ? '' : ' draggable="true"';
  return `<div class="cg-workspace-layer-row${nest}${sel ? ' is-selected' : ''}" role="listitem" tabindex="0" data-layer-item-id="${id}" data-layer-group-id="${gidAttr}"${rowDrag} title="Drag anywhere on this row to reorder">
      ${drag}
      <div class="cg-workspace-layer-row__main">
        <span class="cg-workspace-layer-row__type">${escapeHtml(type)}</span>
        <span class="cg-workspace-layer-row__label">${label}</span>
      </div>
      <div class="cg-workspace-layer-row__thumb">${thumb}</div>
      ${actions}
    </div>`;
}

function layersPanelGetSortedIdsForGroupOrLoose(groupIdStr) {
  const gid = String(groupIdStr || '').trim();
  if (gid) {
    return WS.items
      .filter(it => parseWorkspaceItemGroupMeta(it)?.id === gid)
      .sort((a, b) => Number(b.z_index || 0) - Number(a.z_index || 0) || Number(b.id || 0) - Number(a.id || 0))
      .map(it => Number(it.id))
      .filter(Number.isFinite);
  }
  return WS.items
    .filter(it => !parseWorkspaceItemGroupMeta(it))
    .sort((a, b) => Number(b.z_index || 0) - Number(a.z_index || 0) || Number(b.id || 0) - Number(a.id || 0))
    .map(it => Number(it.id))
    .filter(Number.isFinite);
}

function layersPanelGetRowIdsInContainer(containerEl) {
  return [...containerEl.querySelectorAll(':scope > .cg-workspace-layer-row')]
    .map(el => Number(el.getAttribute('data-layer-item-id')))
    .filter(Number.isFinite);
}

function layersPanelDropInsertIndex(containerEl, clientY) {
  const rows = [...containerEl.querySelectorAll(':scope > .cg-workspace-layer-row')];
  let insert = rows.length;
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i].getBoundingClientRect();
    if (clientY < r.top + r.height / 2) {
      insert = i;
      break;
    }
  }
  return insert;
}

/** Drop UI: `insertBeforeIdx` = index from layersPanelDropInsertIndex (insert before that row). */
function layersPanelReorderByInsertBeforeIndex(ids, fromIdx, insertBeforeIdx) {
  const next = [...ids];
  const [removed] = next.splice(fromIdx, 1);
  let adj = insertBeforeIdx;
  if (fromIdx < insertBeforeIdx) adj -= 1;
  adj = Math.max(0, Math.min(adj, next.length));
  next.splice(adj, 0, removed);
  return next;
}

/** Keyboard / explicit move: `finalIdx` = 0-based index in the full list after the move. */
function layersPanelReorderByFinalIndex(ids, fromIdx, finalIdx) {
  const next = [...ids];
  const [removed] = next.splice(fromIdx, 1);
  const idx = Math.max(0, Math.min(finalIdx, next.length));
  next.splice(idx, 0, removed);
  return next;
}

function applyZPermutationFromOrderedIds(orderedIds) {
  const items = orderedIds.map(id => getItemById(id)).filter(Boolean);
  if (items.length !== orderedIds.length) return;
  const zSorted = [...items].sort((a, b) => {
    const dz = Number(b.z_index || 0) - Number(a.z_index || 0);
    if (dz !== 0) return dz;
    return Number(b.id || 0) - Number(a.id || 0);
  });
  const zValues = zSorted.map(i => Number(i.z_index || 0));
  orderedIds.forEach((id, idx) => {
    const item = getItemById(id);
    if (item) item.z_index = zValues[idx];
  });
  syncWorkspaceItemLayerDomOrder();
}

function layersPanelEnsureGroupBodyVisibleForDrop(wrap) {
  if (!wrap) return;
  const gid = wrap.getAttribute('data-group-id');
  const body = wrap.querySelector('.cg-workspace-layer-group__body');
  if (!gid || !body) return;
  if (body.hasAttribute('hidden')) {
    body.removeAttribute('hidden');
    setWorkspaceLayerGroupExpanded(gid, true);
  }
}

/** Drag/pointer events may target a Text node — it has no .closest(). */
function layersPanelPointerTargetEl(event) {
  const t = event.target;
  if (!t) return null;
  return t.nodeType === Node.TEXT_NODE ? t.parentElement : t;
}

const LAYER_DND_MIME_ID = 'application/x-cg-workspace-layer';
const LAYER_DND_MIME_SRC_GID = 'application/x-cg-layer-src-gid';

function layersPanelDragEventIsLayerRow(e) {
  const tid = Number(WS.layersPanelDragItemId);
  if (Number.isFinite(tid) && tid > 0) return true;
  const dt = e.dataTransfer;
  if (!dt || !dt.types) return false;
  try {
    return Array.from(dt.types).includes(LAYER_DND_MIME_ID);
  } catch (err) {
    return false;
  }
}

function resolveLayersPanelDropZone(event) {
  const t = layersPanelPointerTargetEl(event);
  if (!t || typeof t.closest !== 'function') return null;
  if (t.closest('.cg-workspace-layer-group__toggle')) return null;
  if (t.closest('.cg-workspace-layer-group__action')) return null;
  if (t.closest('[data-layer-group-action]')) return null;

  let body = t.closest('.cg-workspace-layer-group__body');
  if (body) {
    const wrap = body.closest('.cg-workspace-layer-group');
    const gid = wrap?.getAttribute('data-group-id');
    if (gid) {
      layersPanelEnsureGroupBodyVisibleForDrop(wrap);
      return { container: body, groupId: gid };
    }
  }

  const header = t.closest('.cg-workspace-layer-group__header');
  if (header) {
    const wrap = header.closest('.cg-workspace-layer-group');
    const gid = wrap?.getAttribute('data-group-id');
    const groupBody = wrap?.querySelector('.cg-workspace-layer-group__body');
    if (gid && groupBody) {
      layersPanelEnsureGroupBodyVisibleForDrop(wrap);
      return { container: groupBody, groupId: gid };
    }
  }

  const looseRow = t.closest('.cg-workspace-layer-row');
  if (looseRow && !looseRow.closest('.cg-workspace-layer-group__body')) {
    return { container: qs('#workspaceLayersList'), groupId: '' };
  }
  const list = qs('#workspaceLayersList');
  if (list && t.closest('#workspaceLayersList') === list && !t.closest('.cg-workspace-layer-group')) {
    return { container: list, groupId: '' };
  }
  const panel = qs('#workspaceLayersPanel');
  if (panel && panel.contains(t) && !t.closest('#workspaceLayerGroupContextMenu')) {
    if (list) return { container: list, groupId: '' };
  }
  return null;
}

async function commitLayersPanelDrop(event, draggedId, srcGid) {
  if (workspaceIsClientView()) return;
  if (!Number.isFinite(Number(draggedId))) return;
  let zone = resolveLayersPanelDropZone(event);
  if (!zone) {
    const el = document.elementFromPoint(event.clientX, event.clientY);
    if (el) {
      zone = resolveLayersPanelDropZone({ target: el, clientX: event.clientX, clientY: event.clientY });
    }
  }
  if (!zone) return;
  const tgtGid = String(zone.groupId || '');
  const container = zone.container;
  const insertIdx = layersPanelDropInsertIndex(container, event.clientY);
  const sid = String(srcGid ?? '');
  const tid = String(tgtGid ?? '');

  if (sid === tid) {
    const domIds = layersPanelGetRowIdsInContainer(container);
    const fromIdx = domIds.indexOf(Number(draggedId));
    if (fromIdx < 0) return;
    const newIds = layersPanelReorderByInsertBeforeIndex(domIds, fromIdx, insertIdx);
    applyZPermutationFromOrderedIds(newIds);
    await Promise.all(newIds.map(id => saveWorkspaceItem(getItemById(id))));
    renderWorkspaceLayersPanel();
    return;
  }

  const dragged = getItemById(draggedId);
  if (!dragged) return;

  const zSnap = new Map();
  WS.items.forEach(it => zSnap.set(Number(it.id), Number(it.z_index || 0)));

  const zSnapN = (id) => zSnap.get(Number(id)) ?? 0;
  const tgtBeforeIds = layersPanelGetSortedIdsForGroupOrLoose(tid).filter(id => id !== Number(draggedId));
  const multisetTgt = [...tgtBeforeIds.map(id => zSnapN(id)), zSnapN(draggedId)].sort((a, b) => b - a);

  const srcBeforeIds = layersPanelGetSortedIdsForGroupOrLoose(sid).filter(id => id !== Number(draggedId));
  const multisetSrc = srcBeforeIds.map(id => zSnapN(id)).sort((a, b) => b - a);

  if (tid) {
    const gItems = WS.items.filter(it => parseWorkspaceItemGroupMeta(it)?.id === tid);
    const name = parseWorkspaceItemGroupMeta(gItems[0])?.name || 'Group';
    setWorkspaceItemGroupMeta(dragged, tid, name);
  } else {
    clearWorkspaceItemGroupMeta(dragged);
  }

  const newTargetOrder = [...tgtBeforeIds];
  const ins = Math.max(0, Math.min(insertIdx, newTargetOrder.length));
  newTargetOrder.splice(ins, 0, Number(draggedId));
  newTargetOrder.forEach((id, i) => {
    const it = getItemById(id);
    if (it) it.z_index = multisetTgt[i];
  });

  srcBeforeIds.forEach((id, i) => {
    const it = getItemById(id);
    if (it) it.z_index = multisetSrc[i];
  });

  const toSave = new Set([...newTargetOrder, ...srcBeforeIds]);
  await Promise.all([...toSave].map(id => saveWorkspaceItem(getItemById(id))));
  renderWorkspaceLayersPanel();
}

function layersPanelRemoveDragGhost() {
  if (WS.layersPanelDragGhostEl) {
    try {
      WS.layersPanelDragGhostEl.remove();
    } catch (err) {}
    WS.layersPanelDragGhostEl = null;
  }
}

function layersPanelSetDragGhost(event, row) {
  layersPanelRemoveDragGhost();
  if (!event.dataTransfer || !row) return;
  const ghost = row.cloneNode(true);
  ghost.classList.add('cg-workspace-layer-row--drag-ghost');
  ghost.classList.remove('is-selected', 'is-layer-dragging');
  ghost.style.cssText = `position:fixed;left:-9999px;top:0;width:${row.offsetWidth}px;pointer-events:none;z-index:2147483647;`;
  ghost.removeAttribute('draggable');
  ghost.removeAttribute('role');
  ghost.removeAttribute('tabindex');
  ghost.removeAttribute('title');
  ghost.querySelectorAll('button').forEach((btn) => {
    btn.setAttribute('draggable', 'false');
  });
  document.body.appendChild(ghost);
  WS.layersPanelDragGhostEl = ghost;
  const rect = row.getBoundingClientRect();
  const ox = Math.max(12, Math.min(Math.max(12, rect.width - 12), event.clientX - rect.left));
  const oy = Math.max(10, Math.min(Math.max(10, rect.height - 6), event.clientY - rect.top));
  try {
    event.dataTransfer.setDragImage(ghost, ox, oy);
  } catch (err) {}
}

function layersPanelMoveRowInList(itemId, delta) {
  if (workspaceIsClientView()) return;
  const id = Number(itemId);
  if (!Number.isFinite(id) || !delta) return;
  const row = document.querySelector(`.cg-workspace-layer-row[data-layer-item-id="${id}"]`);
  if (!row || !row.closest('#workspaceLayersList')) return;
  const container = row.parentElement;
  if (!container || (!container.classList.contains('cg-workspace-layer-group__body') && container.id !== 'workspaceLayersList')) return;
  const domIds = layersPanelGetRowIdsInContainer(container);
  const fromIdx = domIds.indexOf(id);
  if (fromIdx < 0) return;
  const finalIdx = Math.max(0, Math.min(domIds.length - 1, fromIdx + delta));
  if (finalIdx === fromIdx) return;
  const newIds = layersPanelReorderByFinalIndex(domIds, fromIdx, finalIdx);
  applyZPermutationFromOrderedIds(newIds);
  Promise.all(newIds.map((rid) => saveWorkspaceItem(getItemById(rid))))
    .then(() => {
      if (WS.layersOpen) renderWorkspaceLayersPanel();
    })
    .catch((err) => {
      console.error('Layers reorder error:', err);
      alert(err.message || 'Failed to reorder layers.');
    });
}

function layersPanelOnDocumentKeydown(e) {
  if (workspaceIsClientView()) return;
  if (!WS.layersOpen) return;
  if (!e.altKey || (e.key !== 'ArrowUp' && e.key !== 'ArrowDown')) return;
  const ids = [...(WS.selectedItemIds || [])].map(Number).filter(Number.isFinite);
  if (ids.length !== 1) return;
  e.preventDefault();
  e.stopPropagation();
  const delta = e.key === 'ArrowUp' ? -1 : 1;
  layersPanelMoveRowInList(ids[0], delta);
}

function initWorkspaceLayersPanelDnD() {
  const list = qs('#workspaceLayersList');
  const panel = qs('#workspaceLayersPanel');
  if (!list || list.dataset.layersDndInit === '1') return;
  list.dataset.layersDndInit = '1';

  document.addEventListener('keydown', layersPanelOnDocumentKeydown, true);

  list.addEventListener('selectstart', (e) => {
    e.preventDefault();
  }, true);

  list.addEventListener('pointerdown', (e) => {
    const el = layersPanelPointerTargetEl(e);
    if (el && el.closest && el.closest('.cg-workspace-layer-row__drag')) e.stopPropagation();
  });

  list.addEventListener('dragstart', (e) => {
    const el = layersPanelPointerTargetEl(e);
    if (!el) return;
    const row = el.closest('.cg-workspace-layer-row');
    if (!row) return;
    if (el.closest('.cg-workspace-layer-row__action') || el.closest('[data-layer-action]')) {
      e.preventDefault();
      return;
    }
    if (workspaceIsClientView()) {
      e.preventDefault();
      return;
    }
    const id = Number(row.getAttribute('data-layer-item-id'));
    if (!Number.isFinite(id)) return;
    e.stopPropagation();
    WS.layersPanelDragItemId = id;
    WS.layersPanelDragSourceGroupId = String(row.getAttribute('data-layer-group-id') || '');
    row.classList.add('is-layer-dragging');
    try {
      const sel = window.getSelection && window.getSelection();
      if (sel && sel.rangeCount) sel.removeAllRanges();
    } catch (err) {}
    try {
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData(LAYER_DND_MIME_ID, String(id));
      e.dataTransfer.setData('text/plain', String(id));
      e.dataTransfer.setData(LAYER_DND_MIME_SRC_GID, String(row.getAttribute('data-layer-group-id') || ''));
    } catch (err) {}
    layersPanelSetDragGhost(e, row);
  });

  list.addEventListener('dragend', (e) => {
    layersPanelRemoveDragGhost();
    const el = layersPanelPointerTargetEl(e);
    const row = el && el.closest ? el.closest('.cg-workspace-layer-row') : null;
    if (row) row.classList.remove('is-layer-dragging');
    // Defer clear: some browsers fire dragend before drop; drop must still read id / allow preventDefault chain.
    setTimeout(() => {
      WS.layersPanelDragItemId = null;
      WS.layersPanelDragSourceGroupId = null;
    }, 0);
  });

  const onLayersPanelDragEnter = (e) => {
    if (!layersPanelDragEventIsLayerRow(e)) return;
    const zone = resolveLayersPanelDropZone(e);
    if (zone) e.preventDefault();
  };
  const onLayersPanelDragOver = (e) => {
    if (!layersPanelDragEventIsLayerRow(e)) return;
    const zone = resolveLayersPanelDropZone(e);
    if (zone) {
      e.preventDefault();
      try {
        e.dataTransfer.dropEffect = 'move';
      } catch (err) {}
    }
  };
  const onLayersPanelDrop = (e) => {
    const dt = e.dataTransfer;
    let dId = Number(WS.layersPanelDragItemId);
    if (!Number.isFinite(dId) || dId <= 0) {
      dId = Number((dt && dt.getData(LAYER_DND_MIME_ID)) || (dt && dt.getData('text/plain')) || '');
    }
    let sGid = String(WS.layersPanelDragSourceGroupId ?? '');
    if (!sGid && dt) {
      sGid = String(dt.getData(LAYER_DND_MIME_SRC_GID) || '');
    }
    if (!Number.isFinite(dId) || dId <= 0) return;
    e.preventDefault();
    e.stopPropagation();
    WS.layersPanelSuppressRowClick = true;
    commitLayersPanelDrop(e, dId, sGid).catch(err => {
      console.error('Layers reorder error:', err);
      alert(err.message || 'Failed to reorder layers.');
    });
  };
  const dndHost = panel || list;
  dndHost.addEventListener('dragenter', onLayersPanelDragEnter);
  dndHost.addEventListener('dragover', onLayersPanelDragOver);
  dndHost.addEventListener('drop', onLayersPanelDrop);
}

function showWorkspaceLayerGroupContextMenuAt(x, y, groupId) {
  WS.layerGroupContextGroupId = String(groupId || '');
  const menu = getWorkspaceLayerGroupContextMenuEl();
  if (!menu) return;
  menu.hidden = false;
  menu.setAttribute('aria-hidden', 'false');
  const left = Math.max(12, Math.min(x, window.innerWidth - 240));
  const top = Math.max(12, Math.min(y, window.innerHeight - 120));
  workspacePositionFixedShellDescendantFromViewport(menu, left, top);
}

function hideWorkspaceLayerGroupContextMenu() {
  const menu = getWorkspaceLayerGroupContextMenuEl();
  if (!menu) return;
  menu.hidden = true;
  menu.setAttribute('aria-hidden', 'true');
  WS.layerGroupContextGroupId = null;
}

async function groupSelectedWorkspaceItems() {
  if (workspaceIsClientView()) {
    alert('Grouping is not available in client view.');
    return;
  }
  const ids = [...(WS.selectedItemIds || [])].map(Number).filter(Number.isFinite);
  if (ids.length < 2) {
    alert('Select at least two cards to group. Use Shift+click, ⌘/Ctrl+click, or drag a box on the canvas.');
    return;
  }
  const groupId = generateWorkspaceGroupId();
  const groupName = 'Group';
  const saves = [];
  for (const id of ids) {
    const item = getItemById(id);
    if (!item) continue;
    setWorkspaceItemGroupMeta(item, groupId, groupName);
    saves.push(saveWorkspaceItem(item));
  }
  await Promise.all(saves);
  if (!WS.layersOpen) openWorkspaceLayers();
  else renderWorkspaceLayersPanel();
}

async function renameWorkspaceLayerGroupFromPrompt(groupId) {
  const gid = String(groupId || '').trim();
  if (!gid || workspaceIsClientView()) return;
  const items = WS.items.filter(it => parseWorkspaceItemGroupMeta(it)?.id === gid);
  if (!items.length) return;
  const current = parseWorkspaceItemGroupMeta(items[0])?.name || 'Group';
  const next = window.prompt('Group name', current);
  if (next === null) return;
  const name = String(next).trim() || 'Group';
  const saves = [];
  for (const item of items) {
    setWorkspaceItemGroupMeta(item, gid, name);
    saves.push(saveWorkspaceItem(item));
  }
  await Promise.all(saves);
  hideWorkspaceLayerGroupContextMenu();
  if (WS.layersOpen) renderWorkspaceLayersPanel();
}

async function ungroupWorkspaceLayerGroup(groupId) {
  const gid = String(groupId || '').trim();
  if (!gid || workspaceIsClientView()) return;
  const items = WS.items.filter(it => parseWorkspaceItemGroupMeta(it)?.id === gid);
  if (!items.length) return;
  const saves = [];
  for (const item of items) {
    clearWorkspaceItemGroupMeta(item);
    saves.push(saveWorkspaceItem(item));
  }
  await Promise.all(saves);
  ensureWorkspaceLayersGroupExpandedMapLoaded();
  if (WS.layersGroupExpandedMap && Object.prototype.hasOwnProperty.call(WS.layersGroupExpandedMap, gid)) {
    delete WS.layersGroupExpandedMap[gid];
    persistWorkspaceLayersGroupExpandedMap();
  }
  hideWorkspaceLayerGroupContextMenu();
  if (WS.layersOpen) renderWorkspaceLayersPanel();
}
function getWorkspaceLayerRowLabel(item) {
  const t = String(item.title || '').trim();
  if (t) return t.slice(0, 80);
  const raw = String(item.content || '');
  const plain = raw.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  if (plain) return plain.slice(0, 80);
  return '';
}

function buildWorkspaceLayerPreview(item) {
  const itemType = item?.item_type || '';
  if (itemType === 'image') {
    const fullSrc = workspaceItemImageDisplayUrl(item);
    const thumbSrc = workspaceItemImagePreviewUrl(item, 96);
    const imgMeta = parseMaybeJson(item.meta_json, {});
    const flipH = !!imgMeta.flip_horizontal;
    const flipV = !!imgMeta.flip_vertical;
    const sx = flipH ? -1 : 1;
    const sy = flipV ? -1 : 1;
    const tf = (flipH || flipV) ? `transform: scale(${sx}, ${sy})` : '';
    const pair = workspaceImageProgressivePairFromFull(fullSrc);
    const layerFullAttr = pair.progressive ? ` data-full-src="${escapeHtml(pair.full)}"` : '';
    const layerOnload = pair.progressive ? ' onload="cgWorkspaceImageOnLoad(this)"' : '';
    return `
      <div class="cg-workspace-layer-thumb cg-workspace-layer-thumb--image">
        ${thumbSrc
          ? `<img src="${escapeHtml(thumbSrc)}" alt="" draggable="false" loading="lazy" decoding="async"${layerFullAttr}${layerOnload} style="${tf}">`
          : '<div class="cg-workspace-layer-thumb__empty">—</div>'}
      </div>
    `;
  }
  if (itemType === 'palette_card') {
    const colors = getPaletteColorsFromItem(item) || [];
    const swatches = colors.slice(0, 6).map((hex) => (
      `<div class="cg-workspace-layer-thumb__swatch" style="background:${escapeHtml(hex)};"></div>`
    )).join('');
    return `
      <div class="cg-workspace-layer-thumb cg-workspace-layer-thumb--palette" aria-hidden="true">
        ${swatches || '<div class="cg-workspace-layer-thumb__empty">—</div>'}
      </div>
    `;
  }
  if (itemType === 'storyboard_sheet') {
    return '<div class="cg-workspace-layer-thumb cg-workspace-layer-thumb--icon" aria-hidden="true"><i class="fas fa-film"></i></div>';
  }
  if (itemType === 'brush_card') {
    const cardWidth = Math.max(Number(item.width || 220), 140);
    const bodyHeight = Math.max(Number(item.height || 180), 80);
    const strokes = getStrokesForItem(item.id);
    const strokeMarkup = strokes.map(stroke => {
      const style = parseMaybeJson(stroke.style_json, {});
      const strokeColor = escapeHtml(resolveWorkspaceStrokeColorForDisplay(style.color));
      const strokeW = Number(style.size || 3);
      const opacity = Number(style.opacity || 1);
      return `
        <path
          d="${escapeHtml(stroke.stroke_data || '')}"
          stroke="${strokeColor}"
          stroke-width="${strokeW}"
          opacity="${opacity}"
          fill="none"
          stroke-linecap="round"
          stroke-linejoin="round"
        ></path>
      `;
    }).join('');
    return `
      <div class="cg-workspace-layer-thumb cg-workspace-layer-thumb--sketch">
        <svg viewBox="0 0 ${cardWidth} ${bodyHeight}" preserveAspectRatio="xMidYMid meet">
          ${strokeMarkup || ''}
        </svg>
      </div>
    `;
  }
  if (itemType === 'youtube_embed') {
    return '<div class="cg-workspace-layer-thumb cg-workspace-layer-thumb--icon" aria-hidden="true"><i class="fas fa-play-circle"></i></div>';
  }
  if (itemType === 'map_embed') {
    return '<div class="cg-workspace-layer-thumb cg-workspace-layer-thumb--icon" aria-hidden="true"><i class="fas fa-map"></i></div>';
  }
  if (itemType === 'iframe_embed') {
    return '<div class="cg-workspace-layer-thumb cg-workspace-layer-thumb--icon" aria-hidden="true"><i class="fas fa-link"></i></div>';
  }
  if (itemType === 'instagram_embed') {
    return '<div class="cg-workspace-layer-thumb cg-workspace-layer-thumb--icon" aria-hidden="true"><i class="fas fa-camera"></i></div>';
  }
  const rawContent = String(item?.content || '');
  const plainContent = rawContent.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const previewText = (() => {
    if (plainContent) return plainContent.length > 96 ? `${plainContent.slice(0, 96)}…` : plainContent;
    const title = String(item?.title || '').trim();
    if (title) return title.length > 96 ? `${title.slice(0, 96)}…` : title;
    return '';
  })();
  return `
    <div class="cg-workspace-layer-thumb cg-workspace-layer-thumb--text" aria-hidden="true">
      ${previewText ? escapeHtml(previewText) : ''}
    </div>
  `;
}

let workspaceLayersPanelDrag = null;

function clampLayersPanelPosition(left, top, panel) {
  const p = panel || qs('#workspaceLayersPanel');
  const vw = window.innerWidth || document.documentElement.clientWidth || 1200;
  const vh = window.innerHeight || document.documentElement.clientHeight || 800;
  const shell = getWorkspaceShellScaleElement();
  const scale = getWorkspaceShellViewportScale();
  const sr = shell ? shell.getBoundingClientRect() : { left: 0, top: 0 };
  let layoutL = Number.isFinite(Number(left)) ? Number(left) : 18;
  let layoutT = Number.isFinite(Number(top)) ? Number(top) : 76;
  let vLeft = shell ? sr.left + layoutL * scale : layoutL;
  let vTop = shell ? sr.top + layoutT * scale : layoutT;
  const pr = p && !p.hidden ? p.getBoundingClientRect() : null;
  const estWVis = shell ? Math.min(320, Math.max(120, p ? p.offsetWidth || 320 : 320)) * scale : Math.min(320, vw - 24);
  const estHVis = shell ? Math.max(120, p ? p.offsetHeight || 200 : 200) * scale : 200;
  const pwVis = pr && pr.width > 4 ? pr.width : estWVis;
  const phVis = pr && pr.height > 4 ? pr.height : estHVis;
  const margin = 8;
  vLeft = clamp(vLeft, margin, Math.max(margin, vw - pwVis - margin));
  vTop = clamp(vTop, margin, Math.max(margin, vh - phVis - margin));
  if (!shell) return { left: vLeft, top: vTop };
  return {
    left: (vLeft - sr.left) / scale,
    top: (vTop - sr.top) / scale,
  };
}
function loadLayersPanelPosFromStorage() {
  try {
    const bid = String(WS.boardId || '').trim() || 'default';
    const raw = localStorage.getItem(`cg_workspace_layers_pos_${bid}`);
    if (!raw) return null;
    const p = JSON.parse(raw);
    if (typeof p.left !== 'number' || typeof p.top !== 'number') return null;
    if (!Number.isFinite(p.left) || !Number.isFinite(p.top)) return null;
    return { left: p.left, top: p.top };
  } catch (e) {
    return null;
  }
}
function saveLayersPanelPosToStorage(left, top) {
  try {
    const bid = String(WS.boardId || '').trim() || 'default';
    localStorage.setItem(`cg_workspace_layers_pos_${bid}`, JSON.stringify({ left, top }));
  } catch (e) {}
}
function applyWorkspaceLayersPanelPosition() {
  const panel = qs('#workspaceLayersPanel');
  if (!panel || panel.hidden) return;
  let pos = WS.layersPanelPos;
  if (!pos) pos = loadLayersPanelPosFromStorage();
  if (!pos) pos = { left: 18, top: 76 };
  WS.layersPanelPos = clampLayersPanelPosition(pos.left, pos.top, panel);
  panel.style.left = `${WS.layersPanelPos.left}px`;
  panel.style.top = `${WS.layersPanelPos.top}px`;
  panel.style.right = 'auto';
  panel.style.bottom = 'auto';
}
function initWorkspaceLayersPanelDrag() {
  const handle = qs('#workspaceLayersDragHandle');
  const panel = qs('#workspaceLayersPanel');
  if (!handle || !panel) return;
  handle.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    if (e.target.closest && e.target.closest('#workspaceLayersCloseBtn')) return;
    e.preventDefault();
    const scale = getWorkspaceShellViewportScale();
    let startLayoutLeft;
    let startLayoutTop;
    const mem = WS.layersPanelPos;
    if (mem && Number.isFinite(mem.left) && Number.isFinite(mem.top)) {
      startLayoutLeft = mem.left;
      startLayoutTop = mem.top;
    } else {
      const shell = getWorkspaceShellScaleElement();
      const pr = panel.getBoundingClientRect();
      if (shell) {
        const sr = shell.getBoundingClientRect();
        startLayoutLeft = (pr.left - sr.left) / scale;
        startLayoutTop = (pr.top - sr.top) / scale;
      } else {
        startLayoutLeft = pr.left;
        startLayoutTop = pr.top;
      }
    }
    workspaceLayersPanelDrag = {
      pointerId: e.pointerId,
      startClientX: e.clientX,
      startClientY: e.clientY,
      startLayoutLeft,
      startLayoutTop,
      shellScale: scale,
    };
    panel.classList.add('is-dragging');
    handle.setPointerCapture(e.pointerId);
  });
  const endDrag = (e) => {
    if (!workspaceLayersPanelDrag || workspaceLayersPanelDrag.pointerId !== e.pointerId) return;
    const d = workspaceLayersPanelDrag;
    const moved = Math.hypot(e.clientX - d.startClientX, e.clientY - d.startClientY) > 4;
    if (moved) WS.suppressNextWorkspaceClick = true;
    panel.classList.remove('is-dragging');
    try {
      handle.releasePointerCapture(e.pointerId);
    } catch (err) {}
    if (WS.layersPanelPos) {
      saveLayersPanelPosToStorage(WS.layersPanelPos.left, WS.layersPanelPos.top);
    }
    workspaceLayersPanelDrag = null;
  };
  handle.addEventListener('pointermove', (e) => {
    if (!workspaceLayersPanelDrag || workspaceLayersPanelDrag.pointerId !== e.pointerId) return;
    e.preventDefault();
    const d = workspaceLayersPanelDrag;
    const sc = Number(d.shellScale) > 0 ? d.shellScale : 1;
    const nextLeft = d.startLayoutLeft + (e.clientX - d.startClientX) / sc;
    const nextTop = d.startLayoutTop + (e.clientY - d.startClientY) / sc;
    WS.layersPanelPos = clampLayersPanelPosition(nextLeft, nextTop, panel);
    panel.style.left = `${WS.layersPanelPos.left}px`;
    panel.style.top = `${WS.layersPanelPos.top}px`;
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
  });
  handle.addEventListener('pointerup', endDrag);
  handle.addEventListener('pointercancel', endDrag);
}

function renderWorkspaceLayersPanel() {
  const list = qs('#workspaceLayersList');
  if (!list || !WS.layersOpen) return;
  ensureWorkspaceLayersGroupExpandedMapLoaded();
  const sorted = getWorkspaceLayersSortedItems();
  if (!sorted.length) {
    list.innerHTML = '<div class="cg-workspace-layers-empty">No items on this board.</div>';
    return;
  }
  const selected = new Set((WS.selectedItemIds || []).map(n => Number(n)).filter(Number.isFinite));
  const entries = buildWorkspaceLayersPanelEntries(sorted);
  const parts = [];
  for (const entry of entries) {
    if (entry.kind === 'item') {
      parts.push(buildWorkspaceLayerRowHtml(entry.item, selected, false, ''));
      continue;
    }
    const expanded = isWorkspaceLayerGroupExpanded(entry.id);
    const chev = expanded ? '▾' : '▸';
    const gidEsc = escapeHtml(String(entry.id));
    const titleEsc = escapeHtml(String(entry.displayName || 'Group'));
    const groupActions = buildWorkspaceLayerGroupActionsHtml(entry.items, entry.id);
    parts.push(`<div class="cg-workspace-layer-group" data-group-id="${gidEsc}">
      <div class="cg-workspace-layer-group__header" role="button" tabindex="0" data-group-id="${gidEsc}" title="Click to expand/collapse; right-click for options">
        <button type="button" class="cg-workspace-layer-group__toggle" aria-label="${expanded ? 'Collapse group' : 'Expand group'}" aria-expanded="${expanded ? 'true' : 'false'}" data-group-id="${gidEsc}">${chev}</button>
        <span class="cg-workspace-layer-group__title">${titleEsc}</span>
        <span class="cg-workspace-layer-group__badge">${entry.items.length}</span>
        ${groupActions}
      </div>
      <div class="cg-workspace-layer-group__body"${expanded ? '' : ' hidden'}>
        ${entry.items.map(it => buildWorkspaceLayerRowHtml(it, selected, true, entry.id)).join('')}
      </div>
    </div>`);
  }
  list.innerHTML = parts.join('');
}

function closeWorkspaceLayers() {
  WS.layersOpen = false;
  WS.layersSelectionAnchorIndex = null;
  hideWorkspaceLayerGroupContextMenu();
  const panel = qs('#workspaceLayersPanel');
  if (panel) {
    panel.hidden = true;
    panel.setAttribute('aria-hidden', 'true');
  }
  qs('#workspaceLayersBtn')?.classList.remove('is-active');
}

function openWorkspaceLayers() {
  if (WS.layersOpen) return;
  closeWorkspaceTrash();
  closeWorkspaceCharacters();
  WS.layersOpen = true;
  const panel = qs('#workspaceLayersPanel');
  if (panel) {
    panel.hidden = false;
    panel.setAttribute('aria-hidden', 'false');
  }
  qs('#workspaceLayersBtn')?.classList.add('is-active');
  renderWorkspaceLayersPanel();
  requestAnimationFrame(() => {
    applyWorkspaceLayersPanelPosition();
  });
}

function toggleWorkspaceLayers() {
  if (WS.layersOpen) closeWorkspaceLayers();
  else openWorkspaceLayers();
}

