function applyWorkspaceCharactersPanelPosition() {
  const panel = qs('#workspaceCharactersPanel');
  if (!panel || panel.hidden) return;
  let pos = WS.charactersPanelPos;
  if (!pos) pos = loadCharactersPanelPosFromStorage();
  if (!pos) pos = { left: 360, top: 76 };
  WS.charactersPanelPos = clampCharactersPanelPosition(pos.left, pos.top, panel);
  panel.style.left = `${WS.charactersPanelPos.left}px`;
  panel.style.top = `${WS.charactersPanelPos.top}px`;
  panel.style.right = 'auto';
  panel.style.bottom = 'auto';
}
function initWorkspaceCharactersPanelDrag() {
  const handle = qs('#workspaceCharactersDragHandle');
  const panel = qs('#workspaceCharactersPanel');
  if (!handle || !panel) return;
  handle.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    if (e.target.closest && e.target.closest('#workspaceCharactersCloseBtn')) return;
    e.preventDefault();
    const scale = getWorkspaceShellViewportScale();
    let startLayoutLeft;
    let startLayoutTop;
    const mem = WS.charactersPanelPos;
    if (mem && Number.isFinite(mem.left) && Number.isFinite(mem.top)) {
      startLayoutLeft = mem.left;
      startLayoutTop = mem.top;
    } else {
      const shell = getWorkspaceShellScaleElement();
      const pr = panel.getBoundingClientRect();
      if (shell) {
        const sr = shell.getBoundingClientRect();
        startLayoutLeft = (pr.left - sr.left) / scale;
        startLayoutTop = (pr.top - sr.top) / scale;
      } else {
        startLayoutLeft = pr.left;
        startLayoutTop = pr.top;
      }
    }
    workspaceCharactersPanelDrag = {
      pointerId: e.pointerId,
      startClientX: e.clientX,
      startClientY: e.clientY,
      startLayoutLeft,
      startLayoutTop,
      shellScale: scale,
    };
    panel.classList.add('is-dragging');
    handle.setPointerCapture(e.pointerId);
  });
  const endDrag = (e) => {
    if (!workspaceCharactersPanelDrag || workspaceCharactersPanelDrag.pointerId !== e.pointerId) return;
    const moved = Math.hypot(e.clientX - workspaceCharactersPanelDrag.startClientX, e.clientY - workspaceCharactersPanelDrag.startClientY) > 4;
    if (moved) WS.suppressNextWorkspaceClick = true;
    panel.classList.remove('is-dragging');
    try {
      handle.releasePointerCapture(e.pointerId);
    } catch (err) {}
    if (WS.charactersPanelPos) {
      saveCharactersPanelPosToStorage(WS.charactersPanelPos.left, WS.charactersPanelPos.top);
    }
    workspaceCharactersPanelDrag = null;
  };
  handle.addEventListener('pointermove', (e) => {
    if (!workspaceCharactersPanelDrag || workspaceCharactersPanelDrag.pointerId !== e.pointerId) return;
    e.preventDefault();
    const d = workspaceCharactersPanelDrag;
    const sc = Number(d.shellScale) > 0 ? d.shellScale : 1;
    const nextLeft = d.startLayoutLeft + (e.clientX - d.startClientX) / sc;
    const nextTop = d.startLayoutTop + (e.clientY - d.startClientY) / sc;
    WS.charactersPanelPos = clampCharactersPanelPosition(nextLeft, nextTop, panel);
    panel.style.left = `${WS.charactersPanelPos.left}px`;
    panel.style.top = `${WS.charactersPanelPos.top}px`;
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
  });
  handle.addEventListener('pointerup', endDrag);
  handle.addEventListener('pointercancel', endDrag);
}
async function getWorkspaceCharacterBibleItemForEdit() {
  return ensureWorkspaceCharacterBibleItem();
}
function readCharactersFromPanelDom() {
  const list = qs('#workspaceCharactersList');
  if (!list) return [];
  const rows = [];
  list.querySelectorAll('.cg-workspace-character-card[data-character-id]').forEach((card) => {
    const ch = readCharacterFieldsFromCardEl(card);
    if (ch?.name) rows.push(ch);
  });
  return rows;
}
function readCharacterFromPanelRow(characterId) {
  return readCharacterFieldsFromCardEl(getWorkspaceCharacterCardEl(characterId));
