async function saveWorkspaceCharacterRow(characterId, opts) {
  if (workspaceIsClientView()) return false;
  const ch = readCharacterFromPanelRow(characterId);
  if (!ch || !ch.name) {
    if (!opts?.silent) alert('Enter a character name before saving.');
    return false;
  }
  const item = await getWorkspaceCharacterBibleItemForEdit();
  if (!item) return false;
  const { meta, characters } = parseCharacterBibleModel(item.meta_json);
  const idx = characters.findIndex((c) => String(c.id) === String(characterId));
  if (idx >= 0) {
    characters[idx] = { ...characters[idx], ...ch };
  } else {
    characters.push(ch);
  }
  let activateId = String(characterId);
  if (!opts?.silent) {
    const newCh = normalizeWorkspaceCharacterEntry({
      id: generateWorkspaceCharacterId(),
      name: 'New character',
      role: '',
      keywords: '',
    });
    characters.push(newCh);
    activateId = String(newCh.id);
  }
  item.meta_json = stringifyCharacterBibleMeta(meta, characters);
  const si = WS.items.findIndex((e) => Number(e.id) === Number(item.id));
  if (si >= 0) WS.items[si] = item;
  scheduleWorkspaceHistoryCapture();
  try {
    const c = window.__cgWorkspaceCollab;
    if (c && typeof c.upsertItem === 'function') c.upsertItem(item);
  } catch (e) {}
  notifyWorkspaceCollabItemsChanged();
  await saveWorkspaceItem(item).catch((err) => console.error('Characters save:', err));
  WS.charactersActiveTabId = activateId;
  if (!opts?.silent) {
    const btn = qs(`#workspaceCharactersPanel [data-char-save="${characterId}"]`);
    if (btn) {
      btn.classList.add('is-saved');
      const prev = btn.textContent;
      btn.textContent = 'Saved';
      setTimeout(() => {
        btn.classList.remove('is-saved');
        btn.textContent = prev || 'Save';
      }, 1400);
    }
    await renderWorkspaceCharactersPanel();
    focusWorkspaceCharacterNameField(activateId);
  } else {
    syncWorkspaceCharacterTabsFromDom(characters);
  }
  return true;
}
