function syncWorkspaceCharacterTabsFromDom(characters) {
  const tabsEl = qs('#workspaceCharactersTabs');
  if (!tabsEl) return;
  const list = characters || readCharactersFromPanelDom();
  if (!list.length) {
    tabsEl.innerHTML = '';
    tabsEl.hidden = true;
    return;
  }
  const activeId = WS.charactersActiveTabId && list.some((c) => String(c.id) === String(WS.charactersActiveTabId))
    ? String(WS.charactersActiveTabId)
    : String(list[0].id);
  WS.charactersActiveTabId = activeId;
  tabsEl.hidden = false;
  tabsEl.innerHTML = list.map((ch) => buildWorkspaceCharacterTabHtml(ch, String(ch.id) === activeId)).join('');
  setWorkspaceCharacterActiveTab(activeId, { skipScroll: true });
