          <img src="${escapeHtml(thumb)}" alt="${thumbAlt}">
        </button>
      </div>`
    : `<div class="cg-workspace-characters-portrait__thumb-wrap"><span class="cg-workspace-characters-portrait__thumb cg-workspace-characters-portrait__thumb--empty" aria-hidden="true"></span></div>`;
  const pathAttr = escapeHtml(String(ch.image_path || ''));
  const dispAttr = escapeHtml(String(ch.image_display_url || ''));
  const advancedOpen = isWorkspaceCharacterAdvancedExpanded(ch.id);
  const advancedFields = WORKSPACE_CHARACTER_ADVANCED_FIELDS.map((f) => buildWorkspaceCharacterAdvancedFieldHtml(f, ch)).join('');
  const isActiveTab = String(WS.charactersActiveTabId || '') === String(ch.id || '');
  return `<article class="cg-workspace-character-card${advancedOpen ? ' is-advanced-open' : ''}${isActiveTab ? ' is-active-tab' : ''}" data-character-id="${id}" data-image-path="${pathAttr}" data-image-display-url="${dispAttr}">
    <div class="cg-workspace-character-card__main">
      <div class="cg-workspace-character-card__field"><label>Name</label><input type="text" data-char-field="name" value="${name}" placeholder="Character name" aria-label="Character name"></div>
      <div class="cg-workspace-character-card__field"><label>Role</label><input type="text" data-char-field="role" value="${role}" placeholder="e.g. Doctor, Lead" aria-label="Character role"></div>
      <div class="cg-workspace-character-card__field" style="grid-column:1/-2"><label>Keywords</label><textarea data-char-field="keywords" rows="2" placeholder="Quick visual notes (optional if Advanced is filled)" aria-label="Character keywords">${keywords}</textarea></div>
      <div class="cg-workspace-character-card__portrait-col cg-workspace-characters-portrait">
        ${thumbHtml}
        <div class="cg-workspace-characters-portrait__actions">
