          <input type="file" class="cg-workspace-characters-portrait__file" data-char-file="${id}" accept="image/jpeg,image/png,image/gif,image/webp" hidden>
        </div>
      </div>
    </div>
    <button type="button" class="cg-workspace-character-card__advanced-toggle" data-char-advanced-toggle="${id}" aria-expanded="${advancedOpen ? 'true' : 'false'}">${advancedOpen ? 'Advanced ▾' : 'Advanced ▸'}</button>
    <div class="cg-workspace-character-card__advanced">
      <div class="cg-workspace-character-card__advanced-grid">${advancedFields}</div>
    </div>
    <div class="cg-workspace-character-card__toolbar">
      <button type="button" class="cg-workspace-characters-row__save" data-char-save="${id}">Save</button>
      <button type="button" class="cg-workspace-characters-row__del" data-char-delete="${id}" aria-label="Remove character">&times;</button>
    </div>
  </article>`;
}
async function renderWorkspaceCharactersPanel() {
  const list = qs('#workspaceCharactersList');
  const tabsEl = qs('#workspaceCharactersTabs');
  if (!list || !WS.charactersOpen) return;
  const item = await getWorkspaceCharacterBibleItemForEdit();
  if (!item) {
    if (tabsEl) {
      tabsEl.innerHTML = '';
      tabsEl.hidden = true;
    }
    list.innerHTML = '<div class="cg-workspace-characters-panel__empty">Could not load character library.</div>';
    return;
  }
  const { characters } = parseCharacterBibleModel(item.meta_json);
  if (!characters.length) {
    WS.charactersActiveTabId = null;
    if (tabsEl) {
      tabsEl.innerHTML = '';
      tabsEl.hidden = true;
    }
    list.innerHTML = '<div class="cg-workspace-characters-panel__empty">No characters yet — add one below. Open <strong>Advanced</strong> to define height, hair, body type, and more.</div>';
    return;
  }
  if (!WS.charactersActiveTabId || !characters.some((c) => String(c.id) === String(WS.charactersActiveTabId))) {
    WS.charactersActiveTabId = String(characters[characters.length - 1].id);
  }
  if (tabsEl) {
    tabsEl.hidden = false;
    tabsEl.innerHTML = characters.map((ch) => buildWorkspaceCharacterTabHtml(ch, String(ch.id) === String(WS.charactersActiveTabId))).join('');
  }
  list.innerHTML = characters.map(buildWorkspaceCharacterCardHtml).join('');
  setWorkspaceCharacterActiveTab(WS.charactersActiveTabId, { skipScroll: true });
}
function hideWorkspaceCharacterActionMenu() {
  const menu = qs('#workspaceCharacterActionMenu');
  if (menu) {
    menu.hidden = true;
    menu.setAttribute('aria-hidden', 'true');
  }
  WS.characterActionMenuState = null;
