  if (!menu || !anchorBtn) return;
  WS.characterActionMenuState = { characterId: String(characterId) };
  menu.hidden = false;
  menu.setAttribute('aria-hidden', 'false');
  const rect = anchorBtn.getBoundingClientRect();
