function closeWorkspaceCharacters() {
  WS.charactersOpen = false;
  hideWorkspaceCharacterAcMenu();
  hideWorkspaceCharacterActionMenu();
  closeWorkspaceCharacterPortraitModal();
  const panel = qs('#workspaceCharactersPanel');
  if (panel) {
    panel.hidden = true;
    panel.setAttribute('aria-hidden', 'true');
  }
  qs('#workspaceCharactersBtn')?.classList.remove('is-active');
}
function openWorkspaceCharacters() {
  if (workspaceIsClientView()) return;
  if (WS.charactersOpen) {
    void renderWorkspaceCharactersPanel();
    return;
  }
  closeWorkspaceTrash();
  closeWorkspaceLayers();
  WS.charactersOpen = true;
  const panel = qs('#workspaceCharactersPanel');
  if (panel) {
    panel.hidden = false;
    panel.setAttribute('aria-hidden', 'false');
  }
  qs('#workspaceCharactersBtn')?.classList.add('is-active');
  void renderWorkspaceCharactersPanel();
  requestAnimationFrame(() => applyWorkspaceCharactersPanelPosition());
}
function toggleWorkspaceCharacters() {
  if (WS.charactersOpen) closeWorkspaceCharacters();
  else openWorkspaceCharacters();
}
function onWorkspaceCharacterPortraitUploadProgress(characterId, pct) {
  if (!characterId) return;
  if (pct < 0) {
    setCharacterPortraitGeneratingUI(characterId, true, 'Saving on server…', 99);
    return;
  }
  const n = Math.max(0, Math.min(99, Math.round(Number(pct) || 0)));
  const label = n >= 99 ? 'Saving on server…' : `Uploading ${n}%`;
  setCharacterPortraitGeneratingUI(characterId, true, label, Math.max(8, n));
}
async function uploadWorkspaceCharacterPortrait(characterId, file, opts) {
  if (!file || workspaceIsClientView()) return;
  if (WS.characterPortraitUploadingId || WS.aiImageGenerating) return;
  await saveWorkspaceCharacterRow(characterId, { silent: true });
  const item = await getWorkspaceCharacterBibleItemForEdit();
  if (!item) return;
  const { meta, characters } = parseCharacterBibleModel(item.meta_json);
  const idx = characters.findIndex((c) => String(c.id) === String(characterId));
  if (idx < 0) return;
  WS.characterPortraitUploadingId = characterId;
  WS.workspaceImageUploadDepth = (WS.workspaceImageUploadDepth || 0) + 1;
  setCharacterPortraitGeneratingUI(characterId, true, 'Preparing image…', 6);
  try {
    const imageEl = await loadImageElement(file);
    setCharacterPortraitGeneratingUI(characterId, true, 'Compressing…', 12);
    const optimizedFile = await compressImageForWorkspace(file, 650 * 1024, { preloadedImage: imageEl });
    const formData = new FormData();
    formData.append('board_id', String(WS.boardId));
    formData.append('image', optimizedFile, optimizedFile.name || 'character-portrait.jpg');
    appendWorkspaceShareToFormData(formData);
    setCharacterPortraitGeneratingUI(characterId, true, 'Uploading…', 15);
    const data = await uploadJsonWithProgress(
      cgFkApiUrl('?action=upload_workspace_image'),
      formData,
      (pct) => onWorkspaceCharacterPortraitUploadProgress(characterId, pct),
    );
    setCharacterPortraitGeneratingUI(characterId, true, 'Done', 100);
    const path = String(data.image_path || '').trim();
    if (!path) throw new Error('Upload failed');
    characters[idx] = { ...characters[idx], image_path: path, image_display_url: workspaceImageApiUrlForRelPath(path) || '' };
    item.meta_json = stringifyCharacterBibleMeta(meta, characters);
    const si = WS.items.findIndex((e) => Number(e.id) === Number(item.id));
    if (si >= 0) WS.items[si] = item;
    void renderWorkspaceCharactersPanel();
    await saveWorkspaceItem(item);
    if (opts?.describeAfter) {
      void describeWorkspaceCharacterFromImage(characterId);
    } else if (!opts?.skipDescribePrompt && await (typeof window.cgPortalConfirm === 'function'
      ? window.cgPortalConfirm('Use AI to fill appearance fields (Keywords and Advanced) from this image?', {
          title: 'Portrait uploaded',
          okText: 'Use AI',
        })
      : window.confirm('Portrait uploaded. Use AI to fill appearance fields (Keywords and Advanced) from this image?'))) {
      void describeWorkspaceCharacterFromImage(characterId);
    }
  } catch (err) {
    alert(workspaceUserFacingErrorMessage(err, 'Portrait upload failed.'));
  } finally {
    WS.characterPortraitUploadingId = null;
    WS.workspaceImageUploadDepth = Math.max(0, (WS.workspaceImageUploadDepth || 0) - 1);
    setCharacterPortraitGeneratingUI(characterId, false);
  }
}
function normalizeWorkspaceCharacterDescriptionFromApi(raw) {
  const src = raw && typeof raw === 'object' ? raw : {};
  const out = {};
  const textKeys = [
    'keywords', 'hair_style', 'hair_color', 'skin_tone', 'facial_features',
    'distinguishing_marks', 'typical_outfit', 'demeanor', 'appearance_notes',
    'suggested_name', 'suggested_role', 'generation_prompt',
  ];
  textKeys.forEach((k) => {
    const v = String(src[k] || '').trim();
    if (v) out[k] = v.slice(0, 2000);
  });
  WORKSPACE_CHARACTER_ADVANCED_FIELDS.forEach((f) => {
    if (f.type !== 'select') return;
    const v = String(src[f.key] || '').trim().toLowerCase();
    if (!v) return;
    const match = (f.options || []).find((o) => o && String(o).toLowerCase() === v);
    if (match) out[f.key] = match;
  });
  return out;
}
function applyWorkspaceCharacterDescriptionToCard(characterId, fields) {
  const card = getWorkspaceCharacterCardEl(characterId);
  if (!card || !fields) return;
  const applyText = (key, val) => {
    const el = card.querySelector(`[data-char-field="${key}"]`);
    if (el && val) el.value = String(val);
  };
  if (fields.keywords) applyText('keywords', fields.keywords);
  else if (fields.generation_prompt) applyText('keywords', fields.generation_prompt);
  WORKSPACE_CHARACTER_ADVANCED_FIELDS.forEach((f) => {
    if (fields[f.key]) applyText(f.key, fields[f.key]);
  });
  const nameEl = card.querySelector('[data-char-field="name"]');
  const roleEl = card.querySelector('[data-char-field="role"]');
  if (fields.suggested_name && nameEl && !String(nameEl.value || '').trim()) {
    nameEl.value = fields.suggested_name;
  }
  if (fields.suggested_role && roleEl && !String(roleEl.value || '').trim()) {
    roleEl.value = fields.suggested_role;
  }
  if (!WS.charactersExpandedIds) WS.charactersExpandedIds = new Set();
  WS.charactersExpandedIds.add(String(characterId));
  card.classList.add('is-advanced-open');
  const advToggle = card.querySelector('[data-char-advanced-toggle]');
  if (advToggle) {
    advToggle.textContent = 'Advanced ▾';
    advToggle.setAttribute('aria-expanded', 'true');
  }
}
async function blobUrlToCharacterReferenceFile(blobUrl, fileName) {
  const res = await fetch(blobUrl);
  if (!res.ok) throw new Error('Could not read image');
  const blob = await res.blob();
  const type = blob.type && /^image\//i.test(blob.type) ? blob.type : 'image/jpeg';
  return new File([blob], fileName || 'character-reference.jpg', { type });
}
async function buildWorkspaceCharacterDescribeFormData(characterId, file) {
  const ch = readCharacterFromPanelRow(characterId) || {};
  const formData = new FormData();
  formData.append('board_id', String(WS.boardId));
  formData.append('character_name', String(ch.name || ''));
  formData.append('character_role', String(ch.role || ''));
  appendWorkspaceShareToFormData(formData);
  if (file) {
    const imageEl = await loadImageElement(file);
    const optimized = await compressImageForWorkspace(file, 650 * 1024, { preloadedImage: imageEl });
    formData.append('reference_sketch', optimized, optimized.name || 'character-reference.jpg');
    return formData;
  }
  const path = String(ch.image_path || '').trim();
  const refUrl = workspaceCharacterPortraitUrl(ch);
  if (path) formData.append('image_path', path);
  if (refUrl) formData.append('reference_image_url', refUrl);
  if (!path && !refUrl) {
    const src = workspaceCharacterPortraitSrc(ch);
    if (src && src.startsWith('blob:')) {
      const refFile = await blobUrlToCharacterReferenceFile(src, 'character-reference.jpg');
      const imageEl = await loadImageElement(refFile);
      const optimized = await compressImageForWorkspace(refFile, 650 * 1024, { preloadedImage: imageEl });
      formData.append('reference_sketch', optimized, optimized.name || 'character-reference.jpg');
    }
  }
  return formData;
}
async function describeWorkspaceCharacterFromImage(characterId, file) {
  if (workspaceIsClientView() || WS.characterDescribeInFlight) return;
  const card = getWorkspaceCharacterCardEl(characterId);
  if (!card) return;
  const ch = readCharacterFromPanelRow(characterId) || {};
  const hasPortrait = !!(file || ch.image_path || workspaceCharacterPortraitSrc(ch));
  if (!hasPortrait) {
    WS.characterDescribePendingId = String(characterId);
    card.querySelector('[data-char-file]')?.click();
    return;
  }
  WS.characterDescribeInFlight = true;
  setCharacterPortraitGeneratingUI(characterId, true, 'Analyzing image…');
  try {
    const formData = await buildWorkspaceCharacterDescribeFormData(characterId, file || null);
    const hasImage = formData.has('reference_sketch') || formData.has('image_path') || formData.has('reference_image_url');
    if (!hasImage) {
      throw new Error('Add or upload a portrait image first.');
    }
    const data = await fetchJson(cgWorkspaceCharacterDescribeApiUrl(), {
      method: 'POST',
      body: formData,
    });
    const fields = normalizeWorkspaceCharacterDescriptionFromApi(data?.character);
    if (!fields.keywords && !WORKSPACE_CHARACTER_ADVANCED_FIELDS.some((f) => fields[f.key])) {
      throw new Error('AI returned no usable description. Try a clearer photo.');
    }
    applyWorkspaceCharacterDescriptionToCard(characterId, fields);
    alert('Appearance fields filled from the image. Review Keywords and Advanced, then click Save.');
  } catch (err) {
    alert(workspaceUserFacingErrorMessage(err, 'AI character description failed.'));
  } finally {
    WS.characterDescribeInFlight = false;
    setCharacterPortraitGeneratingUI(characterId, false);
  }
}
function buildWorkspaceCharacterPortraitPrompt(ch, opts) {
  const styleTransfer = !!(opts && opts.styleTransfer);
  const name = String(ch.name || '').trim() || 'character';
  const role = String(ch.role || '').trim();
  const fullDesc = buildWorkspaceCharacterFullDescription(ch);
  const parts = [];
  if (styleTransfer) {
    parts.push('Same person as the reference portrait — preserve face shape, age, ethnicity, hairstyle, and distinguishing features');
    parts.push('do not copy any text, names, or lettering from the reference; do not invent a different person');
  }
  if (fullDesc) parts.push(fullDesc);
  parts.push('storyboard character portrait, single figure, no caption area');
  parts.push(getWorkspaceStoryboardPositiveStyle());
  parts.push('single character centered, white background, character design reference sheet, monochrome pencil only');
  parts.push(`Avoid: ${getWorkspaceStoryboardNegativeStyle()}`);
  if (role) parts.push(`casting role: ${role} (do not write this word on the image)`);
  const textRule = workspaceImageTextPromptSuffix(fullDesc, role);
  if (textRule) parts.push(textRule);
  parts.push('no watermark');
  return parts.join(', ').slice(0, 3800);
}
async function generateWorkspaceCharacterPortrait(characterId) {
  if (workspaceIsClientView() || WS.aiImageGenerating) return;
  const chDom = readCharacterFromPanelRow(characterId);
  if (!chDom?.name) {
    alert('Enter a character name before generating a portrait.');
    return;
  }
  if (!workspaceCharacterHasVisualDefinition(chDom)) {
    alert('Add Keywords or fill in Advanced fields (height, hair, body type, etc.) before generating.');
    return;
  }
  await saveWorkspaceCharacterRow(characterId, { silent: true });
  const item = await getWorkspaceCharacterBibleItemForEdit();
  if (!item) return;
  const { meta, characters } = parseCharacterBibleModel(item.meta_json);
  const idx = characters.findIndex((c) => String(c.id) === String(characterId));
  if (idx < 0) return;
  const ch = { ...characters[idx], ...chDom };
  const cp = Math.max(0, Math.floor(Number(WS.cinePoints) || 0));
  if (cp < 1) {
    alert('Not enough CinePoints to generate a portrait.');
    return;
  }
  WS.characterPortraitGeneratingId = characterId;
  setCharacterPortraitGeneratingUI(characterId, true);
  const portraitRef = workspaceCharacterPortraitUrl(ch);
  const styleTransfer = !!portraitRef;
  const prompt = buildWorkspaceCharacterPortraitPrompt(ch, { styleTransfer });
  WS.aiImageGenerating = true;
  startWorkspaceAiImageProgress(styleTransfer ? 'Matching character…' : 'Generating portrait…');
  try {
    const formData = buildWorkspaceAiGenerationFormData(prompt, {
      useUserRefFirst: false,
      referenceUrl: portraitRef || '',
      referenceStrength: styleTransfer ? 86 : null,
      sequenceAnchorRef: !!portraitRef,
      skipStoryboardSketchMode: true,
    });
    const data = await fetchJson('/api/freelance_kanban.php?action=generate_workspace_ai_image', {
      method: 'POST',
      body: formData,
    });
    stopWorkspaceAiImageProgress(92);
    const genItem = data?.item;
    const imagePath = String(genItem?.image_path || '').trim();
    const imageDisplayUrl = String(genItem?.image_display_url || '').trim();
    if (!imagePath && !imageDisplayUrl) throw new Error('Portrait generation failed.');
    characters[idx] = { ...characters[idx], image_path: imagePath, image_display_url: imageDisplayUrl };
    item.meta_json = stringifyCharacterBibleMeta(meta, characters);
    const si = WS.items.findIndex((e) => Number(e.id) === Number(item.id));
    if (si >= 0) WS.items[si] = item;
    const genId = Number(genItem?.id);
    if (genId) {
      applyWorkspaceItemRemoval(genId, { captureHistory: false, notify: false });
      void trashWorkspaceItem(genId, { captureHistory: false, notify: false });
    }
    if (data?.cine_points != null) {
      WS.cinePoints = Math.max(0, Math.floor(Number(data.cine_points)));
    } else {
      WS.cinePoints = Math.max(0, cp - 1);
    }
    syncWorkspaceAiGenerateButtonLabel();
    stopWorkspaceAiImageProgress(100);
    void renderWorkspaceCharactersPanel();
    await saveWorkspaceItem(item);
  } catch (err) {
    stopWorkspaceAiImageProgress(0, 160);
    alert(workspaceUserFacingErrorMessage(err, 'Portrait generation failed.'));
  } finally {
    WS.aiImageGenerating = false;
    setCharacterPortraitGeneratingUI(characterId, false);
    WS.characterPortraitGeneratingId = null;
  }
}
function hideWorkspaceCharacterAcMenu() {
  const menu = qs('#workspaceCharacterAcMenu');
  if (menu) {
    menu.hidden = true;
    menu.setAttribute('aria-hidden', 'true');
    menu.innerHTML = '';
  }
  WS.characterAcState = null;
}
function showWorkspaceCharacterAcMenu(input, matches, tokenStart, tokenEnd) {
  const menu = qs('#workspaceCharacterAcMenu');
  if (!menu || !input || !matches.length) {
    hideWorkspaceCharacterAcMenu();
    return;
  }
  menu.innerHTML = matches.map((ch, i) => {
    const label = `${ch.name} (${ch.role || 'character'})`;
    const thumb = workspaceCharacterPortraitSrc(ch);
    const thumbHtml = thumb ? `<img class="cg-workspace-character-ac-menu__thumb" src="${escapeHtml(thumb)}" alt="">` : '';
    return `<button type="button" class="cg-workspace-character-ac-menu__item${i === 0 ? ' is-active' : ''}" role="option" data-ac-index="${i}">
      ${thumbHtml}
      <span class="cg-workspace-character-ac-menu__meta">
        <span class="cg-workspace-character-ac-menu__label">${escapeHtml(label)}</span>
        <span class="cg-workspace-character-ac-menu__sub">${escapeHtml(String(ch.sourceLabel || ''))}</span>
      </span>
    </button>`;
  }).join('');
  menu.hidden = false;
  menu.setAttribute('aria-hidden', 'false');
  const rect = input.getBoundingClientRect();
  menu.style.left = `${Math.max(8, rect.left)}px`;
  menu.style.top = `${rect.bottom + 4}px`;
  WS.characterAcState = { input, matches, tokenStart, tokenEnd, activeIndex: 0 };
}
function applyWorkspaceCharacterAcPick(ch) {
  const st = WS.characterAcState;
  if (!st?.input || !ch) return;
  const insert = `${ch.name} (${ch.role || 'character'})`;
  const val = String(st.input.value || '');
  const before = val.slice(0, st.tokenStart);
  const after = val.slice(st.tokenEnd);
  const needSpaceBefore = before.length && !/\s$/.test(before);
  const needSpaceAfter = after.length && !/^\s/.test(after);
  st.input.value = `${before}${needSpaceBefore ? ' ' : ''}${insert}${needSpaceAfter ? ' ' : ''}${after}`;
  const pos = (before + (needSpaceBefore ? ' ' : '') + insert + (needSpaceAfter ? ' ' : '')).length;
  st.input.setSelectionRange(pos, pos);
  st.input.dispatchEvent(new Event('input', { bubbles: true }));
  hideWorkspaceCharacterAcMenu();
  if (st.input.getAttribute('data-sb-field') === 'action') {
    fitStoryboardActionTextarea(st.input);
  }
}
function workspaceCharacterAcTokenAtCursor(input) {
  const val = String(input.value || '');
  const pos = input.selectionStart ?? val.length;
  const before = val.slice(0, pos);
  const m = before.match(/@([A-Za-z][A-Za-z0-9''\-]*)$/);
  if (!m) return null;
  const query = m[1];
  const tokenStart = pos - m[0].length;
  return { token: query, tokenStart, tokenEnd: pos };
}
function updateWorkspaceCharacterAutocomplete(input) {
  if (!input || workspaceIsClientView()) return;
  const tok = workspaceCharacterAcTokenAtCursor(input);
  if (!tok) {
    hideWorkspaceCharacterAcMenu();
    return;
  }
  const q = String(tok.token || '').toLowerCase();
  const pool = getWorkspaceBoardCharacterPool();
  const matches = pool.filter((ch) => {
    if (!q) return true;
    const n = String(ch.name || '').toLowerCase();
    const r = String(ch.role || '').toLowerCase();
    return (n && n.startsWith(q)) || (r && r.startsWith(q));
  }).slice(0, 12);
  if (!matches.length) {
    hideWorkspaceCharacterAcMenu();
    return;
  }
  showWorkspaceCharacterAcMenu(input, matches, tok.tokenStart, tok.tokenEnd);
}
function initWorkspaceCharacterAutocomplete() {
  const onInput = (e) => {
    const t = e.target;
    if (!t) return;
    const isAi = t.id === 'workspaceAiPromptInput' || t.matches?.('#workspaceAiPromptInput');
    const isAction = t.getAttribute?.('data-sb-field') === 'action';
    if (!isAi && !isAction) return;
    updateWorkspaceCharacterAutocomplete(t);
  };
  document.addEventListener('input', onInput);
  document.addEventListener('focusin', (e) => {
    const t = e.target;
    if (t?.getAttribute?.('data-sb-field') === 'action' || t?.id === 'workspaceAiPromptInput') {
      updateWorkspaceCharacterAutocomplete(t);
    }
  });
  document.addEventListener('keydown', (e) => {
    const st = WS.characterAcState;
    if (!st || qs('#workspaceCharacterAcMenu')?.hidden) return;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      st.activeIndex = Math.min(st.activeIndex + 1, st.matches.length - 1);
      qs('#workspaceCharacterAcMenu')?.querySelectorAll('.cg-workspace-character-ac-menu__item').forEach((el, i) => {
        el.classList.toggle('is-active', i === st.activeIndex);
      });
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      st.activeIndex = Math.max(st.activeIndex - 1, 0);
      qs('#workspaceCharacterAcMenu')?.querySelectorAll('.cg-workspace-character-ac-menu__item').forEach((el, i) => {
        el.classList.toggle('is-active', i === st.activeIndex);
      });
    } else if (e.key === 'Enter' || e.key === 'Tab') {
      if (st.matches[st.activeIndex]) {
        e.preventDefault();
        applyWorkspaceCharacterAcPick(st.matches[st.activeIndex]);
      }
    } else if (e.key === 'Escape') {
      hideWorkspaceCharacterAcMenu();
    }
  });
  document.addEventListener('click', (e) => {
    const pick = e.target.closest?.('.cg-workspace-character-ac-menu__item');
    if (pick && WS.characterAcState) {
      const i = Number(pick.getAttribute('data-ac-index'));
      if (WS.characterAcState.matches[i]) {
        applyWorkspaceCharacterAcPick(WS.characterAcState.matches[i]);
      }
      return;
    }
    if (!e.target.closest?.('#workspaceCharacterAcMenu')) hideWorkspaceCharacterAcMenu();
  });
}
function initWorkspaceCharactersPanelEvents() {
  qs('#workspaceCharactersBtn')?.addEventListener('click', () => {
    closeTextMenu();
    closeBrushMenu();
    closeSketchMenu();
    closeStoryboardMenu();
    closeSpreadsheetMenu();
    toggleWorkspaceCharacters();
  });
  qs('#workspaceCharactersCloseBtn')?.addEventListener('click', () => closeWorkspaceCharacters());
  qs('#workspaceCharactersAddBtn')?.addEventListener('click', () => {
    void appendWorkspaceCharacterAndActivate();
  });
  const actionMenu = qs('#workspaceCharacterActionMenu');
  if (actionMenu) {
    actionMenu.addEventListener('click', (e) => {
      const btn = e.target.closest?.('[data-char-action]');
      if (!btn || !WS.characterActionMenuState) return;
      const cid = WS.characterActionMenuState.characterId;
      const action = btn.getAttribute('data-char-action');
      hideWorkspaceCharacterActionMenu();
      if (!cid) return;
      const panel = qs('#workspaceCharactersPanel');
      if (action === 'upload') {
        const fileInput = panel?.querySelector(`[data-char-file="${cid}"]`);
        fileInput?.click();
      } else if (action === 'describe') {
        void describeWorkspaceCharacterFromImage(cid);
      } else if (action === 'generate') {
        void generateWorkspaceCharacterPortrait(cid);
      }
    });
  }
  document.addEventListener('click', (e) => {
    if (e.target.closest?.('#workspaceCharacterActionMenu')) return;
    if (e.target.closest?.('[data-char-action-toggle]')) return;
    hideWorkspaceCharacterActionMenu();
  });
  const panel = qs('#workspaceCharactersPanel');
  if (panel) {
    panel.addEventListener('click', (e) => {
      const tabBtn = e.target.closest?.('[data-char-tab]');
      if (tabBtn) {
        const cid = tabBtn.getAttribute('data-char-tab');
        if (cid) setWorkspaceCharacterActiveTab(cid);
        return;
      }
      const saveBtn = e.target.closest?.('[data-char-save]');
      if (saveBtn) {
        const cid = saveBtn.getAttribute('data-char-save');
        if (cid) void saveWorkspaceCharacterRow(cid);
        return;
      }
      const actionToggle = e.target.closest?.('[data-char-action-toggle]');
      if (actionToggle) {
        e.stopPropagation();
        const cid = actionToggle.getAttribute('data-char-action-toggle');
        if (cid) showWorkspaceCharacterActionMenu(actionToggle, cid);
        return;
      }
      const advToggle = e.target.closest?.('[data-char-advanced-toggle]');
      if (advToggle) {
        const cid = advToggle.getAttribute('data-char-advanced-toggle');
        if (cid) {
          if (!WS.charactersExpandedIds) WS.charactersExpandedIds = new Set();
          const card = getWorkspaceCharacterCardEl(cid);
          if (WS.charactersExpandedIds.has(cid)) {
            WS.charactersExpandedIds.delete(cid);
            card?.classList.remove('is-advanced-open');
            advToggle.textContent = 'Advanced ▸';
            advToggle.setAttribute('aria-expanded', 'false');
          } else {
            WS.charactersExpandedIds.add(cid);
            card?.classList.add('is-advanced-open');
            advToggle.textContent = 'Advanced ▾';
            advToggle.setAttribute('aria-expanded', 'true');
          }
        }
        return;
      }
      const previewBtn = e.target.closest?.('[data-char-portrait-preview]');
      if (previewBtn) {
        const src = previewBtn.getAttribute('data-char-portrait-preview') || previewBtn.querySelector('img')?.src || '';
        const card = previewBtn.closest('.cg-workspace-character-card');
        const name = card?.querySelector('[data-char-field="name"]')?.value || 'Character';
        if (src) openWorkspaceCharacterPortraitModal(src, `${name} portrait`);
        return;
      }
      const del = e.target.closest?.('[data-char-delete]');
      if (del) {
        const card = del.closest('.cg-workspace-character-card');
        const cid = card?.getAttribute('data-character-id');
        if (cid && WS.charactersExpandedIds) WS.charactersExpandedIds.delete(cid);
        if (String(WS.charactersActiveTabId) === String(cid)) WS.charactersActiveTabId = null;
        card?.remove();
        void persistWorkspaceCharactersFromPanel().then(() => renderWorkspaceCharactersPanel());
        return;
      }
    });
    panel.addEventListener('input', (e) => {
      const nameInput = e.target.closest?.('[data-char-field="name"]');
      if (!nameInput) return;
      const card = nameInput.closest('.cg-workspace-character-card');
      const cid = card?.getAttribute('data-character-id');
      if (!cid) return;
      const v = String(nameInput.value || '').trim() || 'Untitled';
      panel.querySelectorAll('[data-char-tab]').forEach((tab) => {
        if (tab.getAttribute('data-char-tab') !== cid) return;
        const labelEl = tab.querySelector('.cg-workspace-characters-tab__label');
        if (labelEl) labelEl.textContent = v;
        tab.title = v;
      });
    });
    panel.addEventListener('change', (e) => {
      const fileInput = e.target.closest?.('[data-char-file]');
      if (!fileInput?.files?.[0]) return;
      const cid = fileInput.getAttribute('data-char-file');
      const file = fileInput.files[0];
      fileInput.value = '';
      if (!cid) return;
      if (WS.characterDescribePendingId === cid) {
        WS.characterDescribePendingId = null;
        void (async () => {
          await uploadWorkspaceCharacterPortrait(cid, file, { skipDescribePrompt: true });
          void describeWorkspaceCharacterFromImage(cid, file);
        })();
        return;
      }
      void uploadWorkspaceCharacterPortrait(cid, file);
    });
  }
  initWorkspaceCharactersPanelDrag();
  initWorkspaceCharacterAutocomplete();
  qs('#workspaceCharacterPortraitModalClose')?.addEventListener('click', () => closeWorkspaceCharacterPortraitModal());
  qs('#workspaceCharacterPortraitModalBackdrop')?.addEventListener('click', () => closeWorkspaceCharacterPortraitModal());
  document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    const modal = qs('#workspaceCharacterPortraitModal');
    if (modal && !modal.hidden) closeWorkspaceCharacterPortraitModal();
  });
  window.addEventListener('resize', () => {
    if (!WS.charactersOpen) return;
    applyWorkspaceCharactersPanelPosition();
  });
}

function openWorkspaceTrash() {
  if (WS.trashOpen) return;
  closeWorkspaceLayers();
  closeWorkspaceCharacters();
  WS.trashOpen = true;
  const panel = getWorkspaceTrashPanel();
  const backdrop = getWorkspaceTrashBackdrop();
  if (panel) {
    panel.hidden = false;
    panel.setAttribute('aria-hidden', 'false');
  }
  if (backdrop) backdrop.hidden = false;
  loadWorkspaceTrashItems().catch(err => {
    console.error('Trash load error:', err);
    alert(err.message || 'Failed to load Trash.');
  });
}

function toggleWorkspaceTrash() {
  if (WS.trashOpen) closeWorkspaceTrash();
  else openWorkspaceTrash();
}

function showWorkspaceTrashContextMenuAt(x, y, itemId) {
  const clickedId = Number(itemId);
  const selected = Array.isArray(WS.trashSelectedItemIds) ? WS.trashSelectedItemIds.map(n => Number(n)).filter(n => Number.isFinite(n)) : [];
  const hasClicked = selected.includes(clickedId);
  const contextIds = hasClicked ? selected : [clickedId];
  WS.trashContextItemIds = Array.from(new Set(contextIds));
  WS.trashContextItemId = WS.trashContextItemIds[0] ?? clickedId;
  const menu = getWorkspaceTrashContextMenuEl();
  if (!menu) return;
  menu.hidden = false;
  menu.setAttribute('aria-hidden', 'false');
  const left = Math.max(12, Math.min(x, window.innerWidth - 240));
  const top = Math.max(12, Math.min(y, window.innerHeight - 160));
  workspacePositionFixedShellDescendantFromViewport(menu, left, top);
}

function hideWorkspaceTrashContextMenu() {
  const menu = getWorkspaceTrashContextMenuEl();
  if (!menu) return;
  menu.hidden = true;
  menu.setAttribute('aria-hidden', 'true');
  WS.trashContextItemIds = [];
  WS.trashContextItemId = null;
}
async function saveWorkspaceStroke(stroke) {
  const historyKey = assignHistoryKey(stroke, 'stroke');
  const formData = new FormData();
  if (stroke.id) formData.append('stroke_id', String(stroke.id));
  formData.append('board_id', String(WS.boardId));
  formData.append('tool', stroke.tool || 'brush');
  formData.append('stroke_data', stroke.stroke_data || '');
  formData.append('bounds_json', stroke.bounds_json || '');
  formData.append('style_json', stroke.style_json || '');
  formData.append('z_index', String(Number(stroke.z_index || 0)));
  if (stroke.item_id) formData.append('item_id', String(stroke.item_id));
  appendWorkspaceShareToFormData(formData);
  const data = await fetchJson('/api/freelance_kanban.php?action=save_workspace_stroke', {
    method: 'POST',
    body: formData
  });
  if (data.stroke) {
    data.stroke._historyKey = historyKey;
    const existingIndex = stroke.id ? WS.strokes.findIndex(entry => Number(entry.id) === Number(stroke.id)) : -1;
    if (existingIndex >= 0) {
      WS.strokes[existingIndex] = data.stroke;
    } else {
      const byHistoryIndex = WS.strokes.findIndex(entry => entry._historyKey === historyKey);
      if (byHistoryIndex >= 0) {
        WS.strokes[byHistoryIndex] = data.stroke;
      } else {
        WS.strokes.push(data.stroke);
      }
    }
    if (data.stroke.item_id) {
      renderItems();
    } else {
      workspaceStrokeSpatialIndexUpsert(data.stroke);
      scheduleWorkspaceRender({ strokes: true });
    }
    renderHeader();
    updateEmptyState();
    scheduleWorkspaceHistoryCapture();
  }
}
async function deleteWorkspaceStroke(strokeId) {
  const formData = new FormData();
  formData.append('stroke_id', String(strokeId));
  appendWorkspaceShareToFormData(formData);
  await fetchJson('/api/freelance_kanban.php?action=delete_workspace_stroke', {
    method: 'POST',
    body: formData
  });
  WS.strokes = WS.strokes.filter(entry => Number(entry.id) !== Number(strokeId));
  workspaceStrokeSpatialIndexRemove(strokeId);
  renderItems();
  scheduleWorkspaceRender({ strokes: true });
  renderHeader();
  updateEmptyState();
  scheduleWorkspaceHistoryCapture();
}
async function saveWorkspaceConnector(connector) {
  const historyKey = assignHistoryKey(connector, 'connector');
  const tempId = connector.id || `temp-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
  const optimisticConnector = { ...connector, id: tempId, _historyKey: historyKey };
  const existingIndex = WS.connectors.findIndex(entry => String(entry.id) === String(tempId));
  if (existingIndex >= 0) {
    WS.connectors[existingIndex] = optimisticConnector;
  } else {
    WS.connectors.push(optimisticConnector);
  }
  workspaceConnectorSpatialIndexUpsert(optimisticConnector);
  renderWorkspace();

  const payload = {
    board_id: Number(WS.boardId),
    label: connector.label || '',
    style_json: connector.style_json || '',
    z_index: Number(connector.z_index || 0),
  };
  if (connector.id) payload.connector_id = Number(connector.id);
  if (connector.from_item_id) payload.from_item_id = Number(connector.from_item_id);
  if (connector.to_item_id) payload.to_item_id = Number(connector.to_item_id);
  if (connector.start_x != null) payload.start_x = Number(connector.start_x);
  if (connector.start_y != null) payload.start_y = Number(connector.start_y);
  if (connector.end_x != null) payload.end_x = Number(connector.end_x);
  if (connector.end_y != null) payload.end_y = Number(connector.end_y);
  const data = await fetchJson(`/api/freelance_kanban.php?action=save_workspace_connector${workspaceShareQuerySuffix()}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
  if (data.connector) {
    data.connector._historyKey = historyKey;
    const nextIndex = WS.connectors.findIndex(entry => String(entry.id) === String(tempId));
    if (nextIndex >= 0) {
      WS.connectors[nextIndex] = data.connector;
    } else {
      const byHistoryIndex = WS.connectors.findIndex(entry => entry._historyKey === historyKey);
      if (byHistoryIndex >= 0) {
        WS.connectors[byHistoryIndex] = data.connector;
      } else {
        WS.connectors.push(data.connector);
      }
    }
    workspaceConnectorSpatialIndexUpsert(data.connector);
    scheduleWorkspaceRender({ connectors: true });
    renderHeader();
    updateEmptyState();
    scheduleWorkspaceHistoryCapture();
  }
}
async function deleteWorkspaceConnector(connectorId) {
  await fetchJson(`/api/freelance_kanban.php?action=delete_workspace_connector${workspaceShareQuerySuffix()}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ connector_id: Number(connectorId) }),
  });
  WS.connectors = WS.connectors.filter(entry => Number(entry.id) !== Number(connectorId));
  workspaceConnectorSpatialIndexRemove(connectorId);
  visibleConnectorMap.delete(Number(connectorId));
  scheduleWorkspaceRender({ connectors: true });
  renderHeader();
  updateEmptyState();
  scheduleWorkspaceHistoryCapture();
}
function createDefaultNotePayload(overrides = {}) {
  const stage = getStage();
  let centerWorld = { x: 0, y: 0 };
