function parseYouTubeEmbed(urlString) {
  try {
    const url = new URL(urlString);
    const host = url.hostname.replace(/^www\./, '').toLowerCase();
    if (host === 'youtu.be') {
      const videoId = url.pathname.split('/').filter(Boolean)[0]?.split('?')[0] || '';
      return /^[\w-]{11}$/.test(videoId) ? `https://www.youtube.com/embed/${videoId}` : '';
    }
    if (host.includes('youtube.com') || host === 'music.youtube.com') {
      const v = url.searchParams.get('v');
      if (v && /^[\w-]{11}$/.test(v)) return `https://www.youtube.com/embed/${v}`;
      const parts = url.pathname.split('/').filter(Boolean);
      const takeId = (key) => {
        const i = parts.indexOf(key);
        if (i < 0 || !parts[i + 1]) return '';
        const id = String(parts[i + 1]).split('?')[0];
        return /^[\w-]{11}$/.test(id) ? id : '';
      };
      const fromEmbed = takeId('embed');
      if (fromEmbed) return `https://www.youtube.com/embed/${fromEmbed}`;
      const fromShorts = takeId('shorts');
      if (fromShorts) return `https://www.youtube.com/embed/${fromShorts}`;
      const fromLive = takeId('live');
      if (fromLive) return `https://www.youtube.com/embed/${fromLive}`;
    }
  } catch (err) {}
  return '';
}
function parseGoogleMapsEmbed(urlString) {
  try {
    const url = new URL(urlString);
    const host = (url.hostname || '').replace(/^www\./i, '').toLowerCase();
    if (host === 'maps.app.goo.gl') {
      return `https://www.google.com/maps?q=${encodeURIComponent(urlString)}&output=embed`;
    }
    if (host === 'google.com' || host === 'maps.google.com' || host === 'google.co.in' || host.endsWith('.google.com')) {
      if (url.pathname.startsWith('/maps')) {
        return `https://www.google.com/maps?q=${encodeURIComponent(urlString)}&output=embed`;
      }
