  return item.item_type === 'image' || item.item_type === 'sticky_note' || item.item_type === 'text_card' || item.item_type === 'brush_card' || item.item_type === 'kanban_card' || item.item_type === 'palette_card' || item.item_type === WORKSPACE_STORYBOARD_ITEM_TYPE || item.item_type === WORKSPACE_TABLE_ITEM_TYPE;
}

async function applyAltDragDuplicate(altDupSnapshot, pointerUpEvent) {
  clearWorkspaceAltDragGhosts();
  if (!altDupSnapshot || workspaceIsClientView()) return;
  const idsToDuplicate = Array.isArray(altDupSnapshot.ids) ? altDupSnapshot.ids.map(Number).filter(Boolean) : [];
  if (!idsToDuplicate.length) return;
  const startX = Number(altDupSnapshot.startX || 0);
  const startY = Number(altDupSnapshot.startY || 0);
  const dx = (Number(pointerUpEvent?.clientX || 0) - startX) / Math.max(0.0001, WS.camera.scale || 1);
  const dy = (Number(pointerUpEvent?.clientY || 0) - startY) / Math.max(0.0001, WS.camera.scale || 1);
  const origins = altDupSnapshot.origins || {};
  const oldIdSet = new Set(idsToDuplicate);

  // Keep created copies above everything.
  let nextZ = Math.max(
    1,
    ...WS.items.map(entry => Number(entry.z_index || 0)),
    ...WS.strokes.map(entry => Number(entry.z_index || 0)),
    ...WS.connectors.map(entry => Number(entry.z_index || 0))
  ) + 1;

  WS.historyApplying = true;
  try {
    const itemIdMap = new Map(); // old item id -> new item id
    const createdIds = [];

    // 1) Duplicate items.
    for (const oldId of idsToDuplicate) {
      const item = getItemById(oldId);
      if (!item) continue;
      const ox = origins[oldId]?.x ?? Number(item.x || 0);
      const oy = origins[oldId]?.y ?? Number(item.y || 0);
      const payload = {
        item_type: item.item_type || 'sticky_note',
        title: item.title || '',
        content: item.content || '',
        source_url: item.source_url || '',
        embed_url: item.embed_url || '',
        image_path: item.image_path || '',
        x: ox + dx,
        y: oy + dy,
        width: Number(item.width || 280),
        height: Number(item.height || 180),
        rotation: Number(item.rotation || 0),
        z_index: nextZ,
        style_json: item.style_json || '',
        meta_json: item.meta_json || '',
      };
      const created = await createWorkspaceItem(payload);
      if (created && created.id != null) {
        const newId = Number(created.id);
        itemIdMap.set(oldId, newId);
        createdIds.push(newId);
        nextZ += 1;
      }
    }

    // 2) Duplicate strokes attached to duplicated items.
    const strokesToCopy = WS.strokes.filter(stroke => strokeHasAttachedItem(stroke) && oldIdSet.has(Number(stroke.item_id)));
    for (const stroke of strokesToCopy) {
      const oldStrokeItemId = Number(stroke.item_id);
      const newItemId = itemIdMap.get(oldStrokeItemId);
      if (!newItemId) continue;

      await saveWorkspaceStroke({
        item_id: newItemId,
        tool: stroke.tool || 'brush',
        stroke_data: stroke.stroke_data || '',
        bounds_json: stroke.bounds_json || '',
        style_json: stroke.style_json || '',
        z_index: Number(stroke.z_index || nextZ++),
      });
    }

    // 3) Duplicate connectors connecting duplicated items.
    const connectorsToCopy = WS.connectors.filter((c) => {
      const fromId = Number(c.from_item_id || 0);
      const toId = Number(c.to_item_id || 0);
      return oldIdSet.has(fromId) && oldIdSet.has(toId);
    });

    for (const connector of connectorsToCopy) {
      const fromNew = itemIdMap.get(Number(connector.from_item_id));
      const toNew = itemIdMap.get(Number(connector.to_item_id));
      if (!fromNew || !toNew) continue;

      await saveWorkspaceConnector({
        from_item_id: fromNew,
        to_item_id: toNew,
        start_x: connector.start_x,
        start_y: connector.start_y,
        end_x: connector.end_x,
        end_y: connector.end_y,
        label: connector.label || '',
        style_json: connector.style_json || '',
        z_index: Number(connector.z_index || 0),
      });
    }

    if (createdIds.length) {
      setSelectedItems(createdIds, createdIds[createdIds.length - 1]);
    }
  } finally {
    WS.historyApplying = false;
    scheduleWorkspaceHistoryCapture();
  }
}
function getWorkspaceGhostLayer() {
  return qs('#workspaceGhostLayer');
}
function clearWorkspaceAltDragGhosts() {
  const ghostLayer = getWorkspaceGhostLayer();
