}
function renderAltDragGhosts(altDupSnapshot) {
  const ghostLayer = getWorkspaceGhostLayer();
  if (!ghostLayer || !altDupSnapshot) return;

  clearWorkspaceAltDragGhosts();

  const idsToDuplicate = Array.isArray(altDupSnapshot.ids) ? altDupSnapshot.ids.map(Number).filter(Boolean) : [];
  if (!idsToDuplicate.length) return;

  const origins = altDupSnapshot.origins || {};
  const nextZBase = Math.max(
    1,
    ...WS.items.map(entry => Number(entry.z_index || 0)),
    ...WS.strokes.map(entry => Number(entry.z_index || 0)),
    ...WS.connectors.map(entry => Number(entry.z_index || 0))
  ) + 1;

  altDupSnapshot.ghostEls = {};
  altDupSnapshot.itemsById = {};

  let idx = 0;
  for (const oldId of idsToDuplicate) {
    const item = getItemById(oldId);
    if (!item) continue;
    const o = origins[oldId] || { x: Number(item.x || 0), y: Number(item.y || 0) };

    const ghostItem = {
      ...item,
      id: item.id, // keep same id, but pointer events are disabled in the ghost layer
      x: o.x,
      y: o.y,
      z_index: nextZBase + idx,
    };

    const tmp = document.createElement('div');
    tmp.innerHTML = itemMarkup(ghostItem);
    const ghostEl = tmp.firstElementChild;
    if (!ghostEl) continue;

    ghostEl.style.pointerEvents = 'none';
    ghostEl.classList.add('cg-workspace-item--ghost');
    ghostLayer.appendChild(ghostEl);

    altDupSnapshot.ghostEls[oldId] = ghostEl;
    altDupSnapshot.itemsById[oldId] = {
      item_type: item.item_type || 'sticky_note',
      width: Number(item.width || 280),
      height: Number(item.height || 180),
      rotation: Number(item.rotation || 0),
    };
    idx += 1;
  }
}
function updateAltDragGhosts(event) {
  if (!WS.altDuplicate) return;
  const altDup = WS.altDuplicate;
  const ghostEls = altDup.ghostEls || {};
  const itemsById = altDup.itemsById || {};
  const origins = altDup.origins || {};

  const dx = (Number(event.clientX || 0) - Number(altDup.startX || 0)) / Math.max(0.0001, WS.camera.scale || 1);
  const dy = (Number(event.clientY || 0) - Number(altDup.startY || 0)) / Math.max(0.0001, WS.camera.scale || 1);

  Object.keys(ghostEls).forEach((oldIdKey) => {
    const oldId = Number(oldIdKey);
    const el = ghostEls[oldIdKey];
    const snap = itemsById[oldId];
    const o = origins[oldId];
    if (!el || !snap || !o) return;

    const x = o.x + dx;
    const y = o.y + dy;
    el.style.width = `${snap.width.toFixed(2)}px`;
    el.style.height = `${snap.height.toFixed(2)}px`;

    const ghostRot = Number(snap.rotation || 0);
    if (ghostRot !== 0) {
      el.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0) rotate(${ghostRot}deg)`;
    } else {
      el.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0)`;
    }
  });
}
