    return;
  }
  if (WS.pan) {
    const panStartLocalX = Number.isFinite(WS.pan.startLocalX) ? WS.pan.startLocalX : local.x;
    const panStartLocalY = Number.isFinite(WS.pan.startLocalY) ? WS.pan.startLocalY : local.y;
