    const dragStartLocalY = Number.isFinite(drag.startLocalY) ? drag.startLocalY : local.y;
    const dx = (local.x - dragStartLocalX) / WS.camera.scale;
    const dy = (local.y - dragStartLocalY) / WS.camera.scale;
    const ids = drag.ids && drag.ids.length ? drag.ids : [drag.itemId];
    const origins = drag.origins || {};
    ids.forEach((id) => {
      const it = getItemById(id);
      if (!it) return;
      const o = origins[id];
      if (o) {
        it.x = o.x + dx;
        it.y = o.y + dy;
      } else if (Number(id) === Number(drag.itemId)) {
        it.x = drag.originX + dx;
        it.y = drag.originY + dy;
