    const groupOrigins = WS.resize.groupOrigins || {};
    const corner = String(WS.resize.corner || 'se').toLowerCase();
    const isAspect = item.item_type === 'image' || item.item_type === 'brush_card' || item.item_type === 'palette_card' || item.item_type === WORKSPACE_TABLE_ITEM_TYPE;
    let newW;
    let newH;
