      const resizeStartLocalX = Number.isFinite(WS.resize.startLocalX) ? WS.resize.startLocalX : local.x;
      const resizeStartLocalY = Number.isFinite(WS.resize.startLocalY) ? WS.resize.startLocalY : local.y;
