          aspect_ratio: newW / Math.max(1, newH),
        });
      }
      const ox0 = Number(WS.resize.originX);
      const oy0 = Number(WS.resize.originY);
      const ow0 = WS.resize.originWidth;
      const oh0 = WS.resize.originHeight;
      item.x = ox0 + ((corner === 'nw' || corner === 'sw') ? (ow0 - newW) : 0);
      item.y = oy0 + ((corner === 'nw' || corner === 'ne') ? (oh0 - newH) : 0);
    } else {
      groupIds.forEach((id) => {
        const it = getItemById(id);
        const og = groupOrigins[id];
        if (!it || !og) return;
        if (Number(id) === Number(WS.resize.itemId)) {
          it.width = newW;
          it.height = newH;
          if (it.item_type === 'palette_card') {
            const meta = parseMaybeJson(it.meta_json, {});
            it.meta_json = JSON.stringify({
              ...meta,
              aspect_ratio: newW / Math.max(1, newH),
