    let localPoint = null;
    if (WS.drawing.targetItemId) {
      const targetItem = getItemById(WS.drawing.targetItemId);
      if (targetItem) {
        const vb = getWorkspaceAttachedStrokeViewBoxSize(targetItem);
        const localX = point.x - Number(targetItem.x || 0);
        const localY = point.y - Number(targetItem.y || 0);
        const currW = Math.max(1, Number(targetItem.width || 1));
        const currH = Math.max(1, Number(targetItem.height || 1));
        const scaleX = vb.viewW / currW;
        const scaleY = vb.viewH / currH;
        localPoint = { x: localX * scaleX, y: localY * scaleY };
        WS.drawing.localPoints.push(localPoint);
        WS.drawing.localPreviewPath = pathFromPoints(WS.drawing.localPoints);
