    }
    const shiftAssist = !!(event.shiftKey || WS.drawing.shiftShapeAssistPending);
    if (WS.drawing.shiftShapeAssistPending) WS.drawing.shiftShapeAssistPending = false;
    if (event.shiftKey) WS.drawing.shiftAssistUsed = true;
    if (shiftAssist) {
      cancelSmartBrushSnapTimer();
      refreshBrushShiftShapeAssist(WS.drawing);
    } else if (WS.drawing.smartSnapShiftCirclePreserveFullPath && WS.drawing.smartSnapMode === 'circle') {
      // Keep fitted circle preview in sync with the growing raw stroke after Shift is released mid-stroke.
      cancelSmartBrushSnapTimer();
      refreshBrushShiftShapeAssist(WS.drawing);
    }
    if (WS.drawing.smartSnapApplied && WS.drawing.smartSnapMode === 'circle' && !WS.drawing.smartSnapShiftCirclePreserveFullPath) {
