    const moveEps = Math.max(0.45, brushSize * 0.18);
    const lastSig = WS.drawing.lastSignificantMovePoint || point;
    const movedEnough = distance(point, lastSig) >= moveEps;
    if (movedEnough && !WS.drawing.smartSnapApplied && !shiftAssist) {
      WS.drawing.lastMoveTime = getNowMs();
      WS.drawing.lastSignificantMovePoint = point;
      scheduleSmartBrushSnapTimer();
    }
    if (!WS.drawing.targetItemId && !WS.drawing.smartSnapShiftPreserveFullPath && !WS.drawing.smartSnapShiftCirclePreserveFullPath) {
      WS.drawing.previewPath = pathFromPoints(WS.drawing.points);
    }
    if (WS.drawing.smartSnapApplied && WS.drawing.smartSnapMode === 'line') {
      // While holding, allow endpoint direction changes but keep the line perfectly straight.
      const anchorWorld = WS.drawing.smartSnapAnchorWorld || WS.drawing.points[0];
      if (WS.drawing.smartSnapShiftPreserveFullPath) {
