        if (WS.drawing.targetItemId && localPoint) {
          const anchorLocal = WS.drawing.smartSnapAnchorLocal || WS.drawing.localPoints[0];
          WS.drawing.localPoints = [{ ...anchorLocal }, { ...localPoint }];
          WS.drawing.localPreviewPath = pathFromPoints(WS.drawing.localPoints);
