function onStagePointerUp(event) {
  const refDropZone = qs('.cg-workspace-ai-prompt__ref-drop');
  if (refDropZone) refDropZone.classList.remove('is-drag-hover');
  if (WS.marquee) {
    finishMarqueePointerInteraction(event);
  }
  const hadAltDuplicate = !!WS.altDuplicate;
  const altDupSnapshot = WS.altDuplicate;
  if (hadAltDuplicate) WS.altDuplicate = null;
  if (hadAltDuplicate) clearWorkspaceAltDragGhosts();
  const hadDrag = !!WS.drag;
  const hadResize = !!WS.resize;
  const resizeEndIds = WS.resize
    ? (WS.resize.groupIds && WS.resize.groupIds.length ? WS.resize.groupIds : [WS.resize.itemId])
    : [];
