  const hadPan = !!WS.pan;
  let workspaceDragEndSnapshot = null;
  let workspaceDragHandledAiRefDrop = false;
  if (WS.drag) {
    workspaceDragEndSnapshot = WS.drag;
    WS.drag = null;
    const item = getItemById(workspaceDragEndSnapshot.itemId);
    const promptWrap = getWorkspaceAiPromptWrap();
    const promptOpen = !!(promptWrap && !promptWrap.hidden);
    if (promptOpen && item && (item.item_type === 'image' || item.item_type === 'brush_card')) {
      const moveIds = workspaceDragEndSnapshot.ids && workspaceDragEndSnapshot.ids.length ? workspaceDragEndSnapshot.ids : [workspaceDragEndSnapshot.itemId];
      const itemEls = moveIds.map((id) => document.querySelector(`.cg-workspace-item[data-item-id="${id}"]`)).filter(Boolean);
      let under = null;
      try {
        itemEls.forEach((el) => { el.style.pointerEvents = 'none'; });
        under = document.elementFromPoint(event.clientX, event.clientY);
      } catch (err) {
        under = null;
      } finally {
        itemEls.forEach((el) => { el.style.pointerEvents = ''; });
      }
      if (under && under.closest('.cg-workspace-ai-prompt__ref-drop')) {
        workspaceDragHandledAiRefDrop = true;
        const origins = workspaceDragEndSnapshot.origins || {};
        moveIds.forEach((id) => {
          const it = getItemById(id);
          const o = origins[id];
          if (!it) return;
          if (o) {
            it.x = o.x;
            it.y = o.y;
          } else if (Number(id) === Number(workspaceDragEndSnapshot.itemId)) {
            it.x = workspaceDragEndSnapshot.originX;
            it.y = workspaceDragEndSnapshot.originY;
          }
        });
        updateWorkspaceItemsElements(moveIds);
        renderConnectors();
        queueWorkspaceItemsSave(moveIds);
        applyWorkspaceItemAsAiReference(item).catch((err) => {
          console.error('AI reference from card:', err);
          alert(err?.message || 'Could not use card as reference.');
        });
      }
    }
  }
  if (hadDrag && workspaceDragEndSnapshot && !workspaceDragHandledAiRefDrop) {
    const moveIds = workspaceDragEndSnapshot.ids && workspaceDragEndSnapshot.ids.length
      ? workspaceDragEndSnapshot.ids
      : [workspaceDragEndSnapshot.itemId];
    workspaceMarkItemsPositionProtected(moveIds);
    flushWorkspaceItemSavesImmediate(moveIds);
    workspaceSpatialIndexUpsertItems(moveIds);
    updateWorkspaceItemsElements(moveIds);
    scheduleWorkspaceRender({ all: true });
  }
  qsa('.cg-workspace-item.is-dragging, .cg-workspace-item.is-resizing').forEach((el) => {
    el.classList.remove('is-dragging', 'is-resizing');
  });
  if (WS.resize) WS.resize = null;
  if (WS.rotate) WS.rotate = null;
  if (WS.pan) stopPan();
  cancelSmartBrushSnapTimer();
  if (WS.eraserSession) {
    if (workspaceEraserRafId != null) {
      cancelAnimationFrame(workspaceEraserRafId);
      workspaceEraserRafId = null;
    }
    const persist = WS.eraserPersist;
    try {
      flushWorkspaceEraserDragSamples();
      const sess = WS.eraserSession;
      if (sess) {
        const tid = sess.targetItemId;
        const rest = sess.samples.slice();
        if (rest.length) applyWorkspaceEraserSessionLocal({ targetItemId: tid, samples: rest });
      }
    } catch (err) {
      console.error('Eraser error:', err);
      alert(err?.message || 'Eraser failed.');
    }
    WS.eraserSession = null;
    if (persist && (persist.serverDeletes.size || persist.saveByKey.size)) {
      void persistWorkspaceEraserDrag(persist).catch((err) => {
        console.error('Eraser save error:', err);
