function onStageWheel(event) {
  if (!getStage()) return;
  event.preventDefault();
  const stageRect = getStage().getBoundingClientRect();
  const vpScale = getWorkspaceViewportScale(getStage(), stageRect);
  const cursorX = (event.clientX - stageRect.left) / vpScale;
  const cursorY = (event.clientY - stageRect.top) / vpScale;
  const worldX = (cursorX - WS.camera.x) / WS.camera.scale;
  const worldY = (cursorY - WS.camera.y) / WS.camera.scale;
  const nextScale = clamp(WS.camera.scale * (event.deltaY < 0 ? 1.08 : 0.92), 0.01, 4);
  WS.camera.scale = nextScale;
  WS.camera.x = cursorX - worldX * nextScale;
  WS.camera.y = cursorY - worldY * nextScale;
  applyCamera({ interactive: true });
  scheduleWorkspaceHistoryCapture(320);
}
function bindDynamicItemEvents() {
