    if (!stage || !stage.contains(event.target)) return;
    const itemEl = event.target.closest('.cg-workspace-item');
    if (!itemEl) return;
    const itemId = Number(itemEl.dataset.itemId || 0);
    const item = getItemById(itemId);
    if (!item) return;
    if (isWorkspaceItemLayerLocked(item)) return;
    if (item.item_type === 'sticky_note') {
      event.preventDefault();
      event.stopPropagation();
      const wantsTitle = !!event.target.closest('.cg-workspace-note-view__title, .cg-workspace-item__title');
      enterItemEditMode(itemId, wantsTitle ? 'title' : 'content');
      return;
    }
    if (item.item_type === 'text_card') {
      event.preventDefault();
      event.stopPropagation();
      enterItemEditMode(itemId, 'content');
      return;
    }
    if (item.item_type === 'palette_card') {
      event.preventDefault();
      event.stopPropagation();
      enterPaletteEditMode(itemId);
      return;
    }
    if (item.item_type === 'brush_card') {
      event.preventDefault();
      event.stopPropagation();
      renameWorkspaceItem(itemId);
      return;
    }
    if (item.item_type === WORKSPACE_STORYBOARD_ITEM_TYPE) {
      event.preventDefault();
      event.stopPropagation();
      renameWorkspaceItem(itemId);
    }
  }, true);

