    const field = event.target.getAttribute('data-field');
    if (!field) return;
    const itemEl = event.target.closest('.cg-workspace-item');
    if (!itemEl) return;
    const item = getItemById(itemEl.dataset.itemId);
    if (!item) return;
    item[field] = event.target.value;
    queueItemSave(item.id, 420);
    scheduleWorkspaceHistoryCapture(700);
