      const itemEl = event.target.closest('.cg-workspace-item--storyboard_sheet');
      if (!itemEl) return;
      const item = getItemById(itemEl.dataset.itemId);
      if (!item || item.item_type !== WORKSPACE_STORYBOARD_ITEM_TYPE) return;
      const { meta, rows: sbRows, cols: sbCols, cells, characters } = parseStoryboardSheetModel(item.meta_json);
      const i = Number(sbIdx);
      if (!cells[i]) return;
      cells[i] = { ...cells[i], [sbField]: event.target.value };
