      window.requestAnimationFrame(() => {
        try { cell.input.focus({ preventScroll: true }); } catch (e) { cell.input.focus(); }
      });
    }
  }, true);
  document.addEventListener('input', function(event) {
    const pickerIndex = event.target.getAttribute('data-palette-index');
    if (pickerIndex == null) return;
    const itemEl = event.target.closest('.cg-workspace-item');
