    scheduleWorkspaceHistoryCapture(420);
  });
  document.addEventListener('click', function(event) {
    const deleteBtn = event.target.closest('[data-delete-item]');
    if (deleteBtn) {
      const itemId = deleteBtn.getAttribute('data-delete-item');
      if (itemId) {
        trashWorkspaceItem(Number(itemId)).catch(err => {
          if (isWorkspaceItemNotFoundError(err)) return;
          alert(err.message || 'Failed to delete item.');
        });
      }
      return;
    }
    const connectorEl = event.target.closest('.cg-workspace-connector-group[data-connector-id]');
    if (connectorEl && event.shiftKey) {
      const connectorId = connectorEl.getAttribute('data-connector-id');
      if (connectorId) {
        deleteWorkspaceConnector(Number(connectorId)).catch(err => alert(err.message || 'Failed to delete connector.'));
      }
    }
    const sbRegen = event.target.closest('[data-storyboard-regenerate]');
    if (sbRegen && sbRegen.getAttribute('data-storyboard-item-id')) {
      event.preventDefault();
      event.stopPropagation();
      const itemId = sbRegen.getAttribute('data-storyboard-item-id');
      const cellIndex = sbRegen.getAttribute('data-storyboard-regenerate');
      if (itemId != null && cellIndex != null) {
        regenerateWorkspaceStoryboardCell(itemId, cellIndex);
      }
      return;
    }
    const sbClear = event.target.closest('[data-storyboard-clear-image]');
    if (sbClear && sbClear.getAttribute('data-storyboard-item-id')) {
      event.preventDefault();
      event.stopPropagation();
