    const sbEdit = event.target.closest('[data-storyboard-edit-generate]');
    if (sbEdit && sbEdit.getAttribute('data-storyboard-item-id')) {
      event.preventDefault();
      event.stopPropagation();
      const itemId = sbEdit.getAttribute('data-storyboard-item-id');
      const cellIndex = sbEdit.getAttribute('data-storyboard-edit-generate');
      if (itemId != null && cellIndex != null) {
        openWorkspaceStoryboardCellEdit(itemId, cellIndex);
      }
      return;
    }
    const sbDl = event.target.closest('[data-storyboard-download-image]');
    if (sbDl && sbDl.getAttribute('data-storyboard-item-id')) {
      event.preventDefault();
      event.stopPropagation();
      const itemId = sbDl.getAttribute('data-storyboard-item-id');
