    }
    const sbGen = event.target.closest('[data-storyboard-generate]');
    if (sbGen && sbGen.getAttribute('data-storyboard-item-id')) {
      event.preventDefault();
      event.stopPropagation();
      const itemId = sbGen.getAttribute('data-storyboard-item-id');
      const cellIndex = sbGen.getAttribute('data-storyboard-generate');
      if (itemId != null && cellIndex != null) {
        openWorkspaceStoryboardCellGenerate(itemId, cellIndex);
      }
    }
  });
}
