function workspaceAiGenerationProgressParts(p) {
  if (WS.characterPortraitGeneratingId) {
    if (p < 40) {
      return { main: 'Preparing portrait', aria: 'Preparing character portrait…' };
    }
    if (p < 86) {
      return { main: 'Generating portrait', aria: 'Generating character portrait…' };
    }
    return { main: 'Saving portrait', aria: 'Saving character portrait…' };
  }
  if (p < 40) {
    return { main: 'Analyzing your prompt', aria: 'Analyzing your prompt…' };
  }
  if (p < 86) {
    return { main: 'Generating image', aria: 'Generating image…' };
  }
  return { main: 'Adding to your workspace', aria: 'Adding to your workspace.' };
}
function updateCharacterPortraitInlineProgressFor(characterId, percent) {
  if (!characterId) return;
  const card = getWorkspaceCharacterCardEl(characterId);
  const bar = card?.querySelector('.cg-workspace-characters-portrait__progress-bar');
  if (bar) bar.style.width = `${Math.max(0, Math.min(100, Math.round(Number(percent) || 0)))}%`;
