function updateCharacterPortraitInlineProgress(percent) {
  updateCharacterPortraitInlineProgressFor(WS.characterPortraitGeneratingId, percent);
}
function setCharacterPortraitGeneratingUI(characterId, active, label, percent) {
  const panel = qs('#workspaceCharactersPanel');
  if (!panel || !characterId) return;
  const card = getWorkspaceCharacterCardEl(characterId);
  const wrap = card?.querySelector('.cg-workspace-characters-portrait');
  if (!wrap) return;
  const thumbWrap = wrap.querySelector('.cg-workspace-characters-portrait__thumb-wrap');
  if (!thumbWrap) return;
  let prog = thumbWrap.querySelector('.cg-workspace-characters-portrait__progress');
