    wrap.classList.add('is-generating');
    const progressLabel = String(label || 'Generating…');
    if (!prog) {
      prog = document.createElement('div');
      prog.className = 'cg-workspace-characters-portrait__progress';
      prog.innerHTML = '<div class="cg-workspace-characters-portrait__progress-track"><div class="cg-workspace-characters-portrait__progress-bar"></div></div><span class="cg-workspace-characters-portrait__progress-label"></span>';
      thumbWrap.appendChild(prog);
