    }
  }
  if (pct) {
    if (WS.aiImageGenerating) {
      const { main } = workspaceAiGenerationProgressParts(p);
      pct.classList.add('cg-workspace-export-overlay__pct--ai');
      pct.innerHTML = `${escapeHtml(main)}<span class="cg-export-anim-dots" aria-hidden="true"><span>.</span><span>.</span><span>.</span></span>`;
    } else {
      pct.classList.remove('cg-workspace-export-overlay__pct--ai');
      pct.textContent = `${p}%`;
    }
  }
}
