function workspaceAiInferSurfaceFromSubject(text) {
  const s = String(text || '').toLowerCase();
  if (/\b(face|skin|portrait|person|people|human|model|man|woman|child|baby|hand|hands|body|skin tone|complexion)\b/.test(s)) {
    return 'skin';
  }
  if (/\b(bike|bicycle|car|metal|chrome|steel|aluminum|aluminium|motor|vehicle|motorcycle|truck|aircraft|propeller)\b/.test(s)) {
    return 'metal';
  }
  if (/\b(water|gel|liquid|ocean|sea|rain|pour|droplet|droplets|drink|juice|wine|pool|splash|river|stream)\b/.test(s)) {
    return 'liquid';
  }
  if (/\b(floor|concrete|dirt|asphalt|pavement|rock|stone|brick|terrain|ground|gravel|mud|path)\b/.test(s)) {
    return 'rough';
  }
  if (/\b(glass|window|bottle|mirror|crystal|lens|vase|jar)\b/.test(s)) {
    return 'glass';
  }
  if (/\b(fabric|cloth|cotton|silk|wool|denim|canvas|curtain|textile|weave|yarn|sweater|shirt|dress|jeans)\b/.test(s)) {
    return 'fabric';
  }
  if (/\b(plastic|pvc|toy|polymer|acrylic|nylon)\b/.test(s)) {
    return 'plastic';
  }
  return 'fabric';
}
function workspaceAiResolveSurfacePhrase(surfaceKey, subjectBlob) {
  const k = surfaceKey || 'auto';
  if (k === 'auto') {
    const inferred = workspaceAiInferSurfaceFromSubject(subjectBlob);
    return WS_AI_SURFACE_MAP[inferred] || WS_AI_SURFACE_MAP.fabric;
  }
  return WS_AI_SURFACE_MAP[k] || WS_AI_SURFACE_MAP.fabric;
}
