function syncWorkspaceAiStoryboardShotAngleSelects() {
  const shotSel = qs('#workspaceAiStoryboardShot');
  const angleSel = qs('#workspaceAiStoryboardAngle');
  if (!shotSel || !angleSel) return;
  const prevShot = String(shotSel.value || '');
  const prevAngle = String(angleSel.value || '');
  const fill = (sel, list, prev) => {
    while (sel.firstChild) sel.removeChild(sel.firstChild);
    list.forEach((entry) => {
      const opt = document.createElement('option');
      opt.value = entry.value;
      opt.textContent = entry.label;
      sel.appendChild(opt);
    });
    const allowed = new Set(list.map((e) => e.value));
    sel.value = allowed.has(prev) ? prev : '';
  };
  fill(shotSel, WS_AI_STORYBOARD_SHOT_OPTIONS, prevShot);
  fill(angleSel, WS_AI_STORYBOARD_ANGLE_ONLY_OPTIONS, prevAngle);
}
