    }
    if (WS.aiSketchPreviewUrl) {
      try { URL.revokeObjectURL(WS.aiSketchPreviewUrl); } catch (e) {}
    }
    WS.aiRefImageUrlOverride = '';
    WS.aiSketchBlob = blob;
    WS.aiSketchPreviewUrl = URL.createObjectURL(blob);
