async function resolveStoryboardTargetForMultiShot(shotCount, sbCtx) {
  if (sbCtx?.itemId != null) {
    const sb = getItemById(sbCtx.itemId);
    if (sb?.item_type === WORKSPACE_STORYBOARD_ITEM_TYPE) {
      const start = Number.isFinite(Number(sbCtx.cellIndex)) ? Number(sbCtx.cellIndex) : 0;
      ensureStoryboardCellCapacity(sb, start + shotCount);
      return { sbItem: sb, startIndex: start };
    }
  }
  let sel = WS.activeItemId ? getItemById(WS.activeItemId) : null;
  if (!sel && WS.selectedItemIds.length === 1) {
    sel = getItemById(WS.selectedItemIds[0]);
  }
  if (sel?.item_type === WORKSPACE_STORYBOARD_ITEM_TYPE) {
    const start = findFirstEmptyStoryboardCellIndex(sel);
    ensureStoryboardCellCapacity(sel, start + shotCount);
    return { sbItem: sel, startIndex: start };
  }
  const cols = Math.min(4, shotCount);
  const rows = Math.min(8, Math.ceil(shotCount / cols));
  const { rows: r, cols: c, cells } = buildWorkspaceStoryboardCells(rows, cols);
  const frame = computeWorkspaceStoryboardFrameSize(r, c);
  const centerWorld = getWorkspaceStageCenterWorldPoint();
  const zIndex = Math.max(1, ...WS.items.map((entry) => Number(entry.z_index || 0)), ...WS.strokes.map((entry) => Number(entry.z_index || 0)), ...WS.connectors.map((entry) => Number(entry.z_index || 0))) + 1;
  const item = await createWorkspaceItem(createPayloadAtWorldPoint({
    item_type: WORKSPACE_STORYBOARD_ITEM_TYPE,
    title: '',
    width: frame.width,
    height: frame.height,
    meta_json: JSON.stringify({
      rows: r,
      cols: c,
      cells,
      aspect_ratio: frame.width / Math.max(1, frame.height),
    }),
    z_index: zIndex,
  }, centerWorld));
  if (!item) throw new Error('Could not create storyboard.');
