}
function workspaceAiCameraLabelFromControls() {
  const styleEl = qs('#workspaceAiStyle');
  const styleIsSb = styleEl && String(styleEl.value || '').trim() === 'storyboard';
  const sbShotEl = qs('#workspaceAiStoryboardShot');
  const sbAngleEl = qs('#workspaceAiStoryboardAngle');
  const photoShotEl = qs('#workspaceAiPhotoShot');
  const photoAngleEl = qs('#workspaceAiPhotoAngle');
  const pickLabs = (shot, angle) => {
    const sLab = (shot && shot.selectedOptions && shot.selectedOptions[0])
      ? String(shot.selectedOptions[0].textContent || '').trim() : '';
    const aLab = (angle && angle.selectedOptions && angle.selectedOptions[0])
      ? String(angle.selectedOptions[0].textContent || '').trim() : '';
    return [sLab, aLab].filter((p) => p && !/^shot$/i.test(p) && !/^angle$/i.test(p));
  };
  if (styleIsSb) return pickLabs(sbShotEl, sbAngleEl).join(' · ');
  return pickLabs(photoShotEl, photoAngleEl).join(' · ');
}
function appendWorkspaceAiReferenceToFormData(formData, opts) {
  const referenceUrl = String(opts?.referenceUrl || '').trim();
  const useUserRefFirst = opts?.useUserRefFirst !== false;
  const strengthOverride = opts?.referenceStrength;
  const castSketch = opts?.referenceSketchBlob;
  const hasCastSketch = !!(castSketch && castSketch.size > 0);
  const hasSketch = !!(WS.aiSketchBlob && WS.aiSketchBlob.size > 0);
  let refUrl = '';
  if (useUserRefFirst && hasSketch) {
    formData.append('reference_sketch', WS.aiSketchBlob, 'sketch.png');
    formData.append('image_detail', getWorkspaceAiImageDetail());
    refUrl = 'sketch';
  } else if (hasCastSketch) {
    formData.append('reference_sketch', castSketch, 'cast-board-ref.png');
    formData.append('image_detail', getWorkspaceAiImageDetail());
    refUrl = 'sketch';
  } else if (referenceUrl && /^https:\/\//i.test(referenceUrl)) {
    refUrl = referenceUrl;
    formData.append('reference_image_url', refUrl);
    formData.append('image_detail', getWorkspaceAiImageDetail());
  } else if (useUserRefFirst) {
    const userRef = getWorkspaceAiResolvedReferenceImageUrl();
    if (userRef) {
      refUrl = userRef;
      formData.append('reference_image_url', refUrl);
      formData.append('image_detail', getWorkspaceAiImageDetail());
    }
  }
  if (refUrl) {
    const rs = qs('#workspaceAiRefStrength');
    const parsedStrength = rs ? parseInt(String(rs.value), 10) : NaN;
    let n = Number.isFinite(parsedStrength) ? Math.max(0, Math.min(100, parsedStrength)) : 50;
    if (strengthOverride != null && Number.isFinite(Number(strengthOverride))) {
      n = Math.max(0, Math.min(100, Math.floor(Number(strengthOverride))));
    } else if (opts?.sequenceAnchorRef && referenceUrl && /^https:\/\//i.test(referenceUrl) && !hasSketch && !hasCastSketch) {
      n = Math.max(n, 88);
    } else if ((referenceUrl && /^https:\/\//i.test(referenceUrl) || hasCastSketch) && !hasSketch) {
      n = Math.max(n, hasCastSketch ? 86 : 52);
    }
    if (workspaceAiIsStoryboardStyle() && !workspaceAiStoryboardUsesDetailedSketch()) {
      const lightCap = opts?.sequenceAnchorRef ? 72 : 68;
      n = Math.min(n, lightCap);
    }
    formData.append('reference_strength', String(n));
  }
}
function appendWorkspaceStoryboardSketchModeToFormData(formData) {
  if (!workspaceAiIsStoryboardStyle() || !formData) return;
  formData.append('storyboard_sketch_mode', buildWorkspaceStoryboardSketchModeFlag());
}
function buildWorkspaceAiGenerationFormData(prompt, placementOpts) {
  const defaultWidth = 340;
  const defaultHeight = 260;
  const centerWorld = getWorkspaceStageCenterWorldPoint();
  const x = Number.isFinite(Number(placementOpts?.x)) ? Number(placementOpts.x) : Number(centerWorld.x || 0) - (defaultWidth / 2);
  const y = Number.isFinite(Number(placementOpts?.y)) ? Number(placementOpts.y) : Number(centerWorld.y || 0) - (defaultHeight / 2);
  const zIndex = Math.max(1, ...WS.items.map((entry) => Number(entry.z_index || 0)), ...WS.strokes.map((entry) => Number(entry.z_index || 0)), ...WS.connectors.map((entry) => Number(entry.z_index || 0))) + 1;
  const formData = new FormData();
  formData.append('board_id', String(WS.boardId || ''));
  formData.append('prompt', prompt);
  formData.append('x', String(x));
  formData.append('y', String(y));
  formData.append('width', String(defaultWidth));
  formData.append('height', String(defaultHeight));
  formData.append('rotation', '0');
  formData.append('z_index', String(zIndex));
  appendWorkspaceShareToFormData(formData);
  appendWorkspaceAiReferenceToFormData(formData, placementOpts || {});
  if (!placementOpts?.skipStoryboardSketchMode) {
    appendWorkspaceStoryboardSketchModeToFormData(formData);
  }
  const aspectEl = qs('#workspaceAiAspect');
  if (aspectEl && aspectEl.value) {
    formData.append('size', aspectEl.value);
  }
  return formData;
}
function mergeGeneratedImageIntoStoryboardCell(sbItem, cellIndex, genItem, actionText) {
  const imagePath = String(genItem?.image_path || '').trim();
  const imageDisplayUrl = String(genItem?.image_display_url || '').trim();
  if (!sbItem || sbItem.item_type !== WORKSPACE_STORYBOARD_ITEM_TYPE || !(imagePath || imageDisplayUrl)) {
    return false;
  }
  const { meta, rows: sbRows, cols: sbCols, cells, characters } = parseStoryboardSheetModel(sbItem.meta_json);
  const idx = Number(cellIndex);
  if (!(idx >= 0 && idx < cells.length)) return false;
  const styleEl = qs('#workspaceAiStyle');
  const styleLabel = (styleEl && styleEl.selectedOptions && styleEl.selectedOptions[0])
    ? String(styleEl.selectedOptions[0].textContent || '').trim() : '';
  const camLabel = workspaceAiCameraLabelFromControls();
  cells[idx] = {
    ...cells[idx],
    image_path: imagePath,
    image_display_url: imageDisplayUrl,
    action: String(actionText || '').trim(),
    style: styleLabel,
    camera_detail: camLabel,
    camera_title: (camLabel || String(cells[idx].camera_title || '')).trim(),
  };
  sbItem.meta_json = stringifyStoryboardSheetMeta(meta, sbRows, sbCols, cells, characters);
  const genId = Number(genItem.id);
  const storyIdx = WS.items.findIndex((entry) => Number(entry.id) === Number(sbItem.id));
  if (storyIdx >= 0) WS.items[storyIdx] = sbItem;
  if (!WS.pendingStoryboardGenTrashIds) WS.pendingStoryboardGenTrashIds = new Set();
  WS.pendingStoryboardGenTrashIds.add(genId);
  workspaceProtectStoryboardMeta(sbItem.id, sbItem.meta_json);
  applyWorkspaceItemRemoval(genId, { captureHistory: false, notify: false });
  void trashWorkspaceItem(genId, { captureHistory: false, notify: false }).finally(() => {
    WS.pendingStoryboardGenTrashIds?.delete(genId);
  });
  try {
    const c = window.__cgWorkspaceCollab;
    if (c && typeof c.upsertItem === 'function') c.upsertItem(sbItem);
  } catch (e) {}
  return true;
}
function workspaceAiSequenceReferenceUrl(genItem) {
  const pathRef = buildWorkspacePublicImageUrl(String(genItem?.image_path || '').trim());
  if (pathRef && /^https:\/\//i.test(pathRef)) return pathRef;
  const displayRef = buildWorkspacePublicImageUrl(String(genItem?.image_display_url || '').trim());
  if (displayRef && /^https:\/\//i.test(displayRef)) return displayRef;
  return '';
}
function workspaceCancelPendingItemSaves(itemIds) {
  (itemIds || []).forEach((id) => {
    const n = Number(id);
    if (!n) return;
    if (WS.itemSaveTimers[n]) {
      clearTimeout(WS.itemSaveTimers[n]);
      delete WS.itemSaveTimers[n];
    }
  });
}
async function runWorkspaceMultiSceneGeneration(sceneLines, sbCtx) {
  const shotCount = sceneLines.length;
  const { sbItem, startIndex } = await resolveStoryboardTargetForMultiShot(shotCount, sbCtx);
  workspaceCancelPendingItemSaves([sbItem.id]);
  const genCtx = getWorkspaceCharacterGenerationContext(sceneLines);
  const detailedSketch = workspaceAiStoryboardUsesDetailedSketch();
  const sequenceOptsBase = {
    totalScenes: shotCount,
    characterLock: genCtx.characterLock,
    allPromptLines: sceneLines,
    portraitRefUrl: genCtx.portraitRefUrl,
    detailedSketch,
  };
  let anchorRefUrl = '';
  let cp = Math.max(0, Math.floor(Number(WS.cinePoints) || 0));
  const hasUserRef = !!(WS.aiSketchBlob && WS.aiSketchBlob.size > 0) || !!getWorkspaceAiResolvedReferenceImageUrl();

  for (let i = 0; i < shotCount; i++) {
    const lineCtx = getWorkspaceCharacterGenerationContext([sceneLines[i]]);
    const shotLock = [genCtx.characterLock, lineCtx.characterLock].filter(Boolean).join('. ');
    let prompt = buildWorkspaceStructuredImagePromptFromText(sceneLines[i], {
      ...sequenceOptsBase,
      sceneIndex: i,
      characterLock: shotLock,
    });
    if (!prompt) throw new Error(`Scene ${i + 1} has an empty prompt.`);
    if (prompt.length > 4000) prompt = prompt.slice(0, 4000);

    const progressTitle = shotCount > 1
      ? `Generating scene ${i + 1} of ${shotCount}…`
      : 'Generating image…';
    const refOpts = await resolveWorkspaceGenerationReferenceOpts(sceneLines[i], i, anchorRefUrl);
    const usesVisionRef = !!(WS.aiSketchBlob && WS.aiSketchBlob.size) || hasUserRef
      || refOpts.referenceSketchBlob || (refOpts.referenceUrl && /^https:\/\//i.test(refOpts.referenceUrl));
    startWorkspaceAiImageProgress(i === 0 && usesVisionRef ? 'Analyzing reference & generating…' : progressTitle);

    const formData = buildWorkspaceAiGenerationFormData(prompt, refOpts);

    const data = await fetchJson('/api/freelance_kanban.php?action=generate_workspace_ai_image', {
      method: 'POST',
      body: formData,
    });
    stopWorkspaceAiImageProgress(i === shotCount - 1 ? 100 : Math.min(88, 24 + Math.round(((i + 1) / shotCount) * 64)));

    const item = data?.item || null;
    if (!item) throw new Error(`Scene ${i + 1} failed to generate.`);

    if (!mergeGeneratedImageIntoStoryboardCell(sbItem, startIndex + i, item, sceneLines[i])) {
      throw new Error(`Could not add scene ${i + 1} to the storyboard.`);
    }

    workspaceReplaceWorkspaceItemElement(sbItem);
    fitStoryboardActionTextareasInRoot(document.querySelector(`.cg-workspace-item[data-item-id="${storyboardEscapeDataItemId(sbItem.id)}"]`) || document);
    setSelectedItems([Number(sbItem.id)], Number(sbItem.id));

    if (i === 0) {
      const firstRef = workspaceAiSequenceReferenceUrl(item);
      if (firstRef) anchorRefUrl = firstRef;
    }

    if (data && data.cine_points != null) {
      WS.cinePoints = Math.max(0, Math.floor(Number(data.cine_points)));
    } else {
      WS.cinePoints = Math.max(0, cp - 1);
    }
    cp = WS.cinePoints;
    syncWorkspaceAiGenerateButtonLabel();
  }

  scheduleWorkspaceHistoryCapture();
  notifyWorkspaceCollabItemsChanged();
  try {
    await saveWorkspaceItem(sbItem);
  } catch (err) {
    console.error('Storyboard save:', err);
    throw new Error('Scenes generated but saving the storyboard failed. Try saving again or refresh the page.');
  }
}
async function submitWorkspaceAiPrompt() {
  if (WS.aiImageGenerating) return;
  const input = getWorkspaceAiPromptInput();
  if (!input) return;
  const inputSnapshot = String(input.value || '').trim();
  if (workspaceAiIsStoryboardStyle()) syncWorkspaceAiShotCountFromPrompt();
  const shotCount = getWorkspaceAiShotCount();
  const multiShot = workspaceAiIsMultiShotMode();

  if (multiShot) {
    const sceneLines = parseWorkspaceAiMultiSceneLines(inputSnapshot);
    const shotCountSynced = shotCount;
    if (!sceneLines.length) {
      input.focus({ preventScroll: true });
      alert('Add one scene per line (use bullets).');
      return;
    }
    if (sceneLines.length < shotCountSynced) {
      input.focus({ preventScroll: true });
      alert(`Add ${shotCountSynced} scene lines — one per line. You entered ${sceneLines.length}.`);
      return;
    }
    const scenes = sceneLines.slice(0, shotCountSynced);
    const cpMulti = Math.max(0, Math.floor(Number(WS.cinePoints) || 0));
    if (cpMulti < shotCountSynced) {
      WS.aiStoryboardContext = null;
      await runInsufficientCinePointsFakeFlow(inputSnapshot);
      return;
    }
    const sbCtx = WS.aiStoryboardContext;
    WS.aiStoryboardContext = null;
    WS.aiImageGenerating = true;
    setWorkspaceAiPromptBusy(true);
    closeWorkspaceAiPrompt({ keepFocus: true, force: true });
    let shouldReopenPrompt = false;
    try {
      await runWorkspaceMultiSceneGeneration(scenes, sbCtx);
      input.value = '';
      clearWorkspaceAiSketch();
    } catch (err) {
      stopWorkspaceAiImageProgress(0, 160);
      const msg = String(err?.message || err || '');
      if (/cinepoints|exhausted/i.test(msg)) {
        WS.cinePoints = 0;
        syncWorkspaceAiGenerateButtonLabel();
        openInsufficientCinePointsModal(inputSnapshot);
      } else {
        shouldReopenPrompt = true;
        alert(workspaceUserFacingErrorMessage(msg, 'Multi-scene generation failed.'));
      }
    } finally {
      WS.aiImageGenerating = false;
      setWorkspaceAiPromptBusy(false);
      hideWorkspaceExportOverlay();
      if (shouldReopenPrompt) {
        WS.aiStoryboardContext = sbCtx;
        openWorkspaceAiPrompt(inputSnapshot);
      } else {
        focusWorkspaceStage();
      }
    }
    return;
  }

  let prompt = buildWorkspaceStructuredImagePrompt();
  if (!prompt) {
    input.focus({ preventScroll: true });
    return;
  }
  if (prompt.length > 4000) {
    prompt = prompt.slice(0, 4000);
  }

  const cp = Math.max(0, Math.floor(Number(WS.cinePoints) || 0));
  if (cp < 1) {
    WS.aiStoryboardContext = null;
    await runInsufficientCinePointsFakeFlow(inputSnapshot);
    return;
  }

  const sbCtx = WS.aiStoryboardContext;
  WS.aiStoryboardContext = null;

  const hasSketch = !!(WS.aiSketchBlob && WS.aiSketchBlob.size > 0);
  const refUrl = getWorkspaceAiResolvedReferenceImageUrl();
  const genCtxSingle = workspaceAiIsStoryboardStyle()
    ? getWorkspaceCharacterGenerationContext([inputSnapshot])
    : { portraitRefUrl: '', characterLock: '' };
  let promptSingle = prompt;
  if (workspaceAiIsStoryboardStyle() && genCtxSingle.characterLock) {
    promptSingle = buildWorkspaceStructuredImagePromptFromText(inputSnapshot, {
      characterLock: genCtxSingle.characterLock,
      allPromptLines: [inputSnapshot],
      detailedSketch: workspaceAiStoryboardUsesDetailedSketch(),
    });
    if (promptSingle.length > 4000) promptSingle = promptSingle.slice(0, 4000);
  }
  const refOptsSingle = workspaceAiIsStoryboardStyle()
    ? await resolveWorkspaceGenerationReferenceOpts(inputSnapshot, 0, '')
    : {
      referenceUrl: '',
      useUserRefFirst: true,
      referenceStrength: null,
      sequenceAnchorRef: false,
      referenceSketchBlob: null,
    };
  const formData = buildWorkspaceAiGenerationFormData(promptSingle, refOptsSingle);

  WS.aiImageGenerating = true;
  setWorkspaceAiPromptBusy(true);
  closeWorkspaceAiPrompt({ keepFocus: true, force: true });
  const usesVisionRefSingle = !!(WS.aiSketchBlob && WS.aiSketchBlob.size) || !!refUrl
    || refOptsSingle.referenceSketchBlob
    || (refOptsSingle.referenceUrl && /^https:\/\//i.test(refOptsSingle.referenceUrl));
  startWorkspaceAiImageProgress(usesVisionRefSingle ? 'Analyzing reference & generating…' : '');

  let shouldReopenPrompt = false;
  try {
    const data = await fetchJson('/api/freelance_kanban.php?action=generate_workspace_ai_image', {
      method: 'POST',
      body: formData
    });
    stopWorkspaceAiImageProgress(100);
    const item = data?.item || null;
    if (!item) throw new Error('Image generation failed.');

    if (sbCtx && sbCtx.itemId != null && sbCtx.cellIndex != null) {
      const sbItem = getItemById(sbCtx.itemId);
      if (sbItem && mergeGeneratedImageIntoStoryboardCell(sbItem, sbCtx.cellIndex, item, inputSnapshot)) {
        renderWorkspace();
        setSelectedItems([Number(sbItem.id)], Number(sbItem.id));
        scheduleWorkspaceHistoryCapture();
        notifyWorkspaceCollabItemsChanged();
        void saveWorkspaceItem(sbItem).catch((err) => console.error('Storyboard save:', err));
        input.value = '';
        clearWorkspaceAiSketch();
        if (data && data.cine_points != null) {
          WS.cinePoints = Math.max(0, Math.floor(Number(data.cine_points)));
        } else {
          WS.cinePoints = Math.max(0, cp - 1);
        }
        syncWorkspaceAiGenerateButtonLabel();
        return;
      }
    }

    const existingIndex = WS.items.findIndex(entry => Number(entry.id) === Number(item.id));
    if (existingIndex >= 0) {
      WS.items[existingIndex] = item;
    } else {
      WS.items.push(item);
    }
    renderWorkspace();
    setSelectedItems([Number(item.id)], Number(item.id));
    scheduleWorkspaceHistoryCapture();
    try {
      const c = window.__cgWorkspaceCollab;
      if (c && typeof c.upsertItem === 'function') c.upsertItem(item);
    } catch (e) {}
    notifyWorkspaceCollabItemsChanged();
    input.value = '';
    clearWorkspaceAiSketch();
    if (data && data.cine_points != null) {
      WS.cinePoints = Math.max(0, Math.floor(Number(data.cine_points)));
    } else {
      WS.cinePoints = Math.max(0, cp - 1);
    }
    syncWorkspaceAiGenerateButtonLabel();
  } catch (err) {
    stopWorkspaceAiImageProgress(0, 160);
    const msg = String(err?.message || err || '');
    if (/cinepoints|exhausted/i.test(msg)) {
      WS.cinePoints = 0;
      syncWorkspaceAiGenerateButtonLabel();
      shouldReopenPrompt = false;
      openInsufficientCinePointsModal(inputSnapshot);
    } else {
      shouldReopenPrompt = true;
      alert(workspaceUserFacingErrorMessage(msg, 'Failed to generate image.'));
    }
  } finally {
    WS.aiImageGenerating = false;
    setWorkspaceAiPromptBusy(false);
    /** Overlay hide is timer-deferred from stopWorkspaceAiImageProgress; slow awaits (e.g. trash/save) can miss that window while aiImageGenerating was still true — dismiss explicitly. */
    hideWorkspaceExportOverlay();
    const cineModal = qs('#workspaceInsufficientCineModal');
    const insufficientModalOpen = cineModal && !cineModal.hidden;
    if (shouldReopenPrompt) {
      WS.aiStoryboardContext = sbCtx;
      openWorkspaceAiPrompt(inputSnapshot);
    } else if (!insufficientModalOpen) {
      focusWorkspaceStage();
    }
  }
}
/** html2canvas cannot paint cross-origin iframe pixels; use thumbnails / link cards instead. */
function extractYouTubeVideoIdFromUrl(url) {
  if (!url || typeof url !== 'string') return '';
  try {
    const u = new URL(url, 'https://www.youtube.com');
    const host = u.hostname.replace(/^www\./, '').toLowerCase();
    if (host === 'youtu.be') {
      const id = (u.pathname.split('/').filter(Boolean)[0] || '').split('?')[0];
      return /^[\w-]{11}$/.test(id) ? id : '';
    }
    if (host === 'youtube.com' || host === 'm.youtube.com' || host === 'youtube-nocookie.com' || host === 'music.youtube.com') {
      const v = u.searchParams.get('v');
      if (v && /^[\w-]{11}$/.test(v)) return v;
      const parts = u.pathname.split('/').filter(Boolean);
      const pick = (seg) => {
        const i = parts.indexOf(seg);
        if (i < 0 || !parts[i + 1]) return '';
        const id = String(parts[i + 1]).split('?')[0];
        return /^[\w-]{11}$/.test(id) ? id : '';
      };
      return pick('embed') || pick('shorts') || pick('live') || '';
    }
  } catch (e) {}
  return '';
}
function getWorkspaceExportItemTitleFromClone(itemRoot) {
  if (!itemRoot) return '';
  const t = itemRoot.querySelector('.cg-workspace-item__floating-title');
  if (t && t.textContent) return String(t.textContent).trim();
  const inp = itemRoot.querySelector('.cg-workspace-item__title');
  if (inp && inp.value) return String(inp.value).trim();
  return '';
}
function buildWorkspaceExportGenericEmbedCard(src, titleText, isDark, kind) {
  const wrap = document.createElement('div');
  const bg = isDark ? '#1e293b' : '#f1f5f9';
  const fg = isDark ? '#e2e8f0' : '#0f172a';
  const mg = isDark ? '#94a3b8' : '#64748b';
  wrap.style.cssText = `box-sizing:border-box;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:18px 14px;text-align:center;width:100%;height:100%;min-height:120px;flex:1 1 auto;align-self:stretch;border-radius:8px;background:${bg};border:2px solid rgba(100,116,139,0.45);-webkit-print-color-adjust:exact;print-color-adjust:exact;`;
  let host = '';
  try {
    if (src) host = new URL(src, 'https://example.com').hostname.replace(/^www\./, '');
  } catch (e) {}
  const kindLabel = kind === 'map' ? 'MAP' : (kind === 'instagram' ? 'INSTAGRAM' : (kind === 'video' ? 'VIDEO' : 'LINK'));
  const badge = document.createElement('div');
  badge.textContent = kindLabel;
  badge.style.cssText = `font:800 10px system-ui,-apple-system,sans-serif;letter-spacing:0.06em;color:${mg};`;
  const label = titleText || host || (kind === 'map' ? 'Embedded map' : (kind === 'instagram' ? 'Instagram post' : (kind === 'video' ? 'Video embed' : 'Embedded page')));
  const t = document.createElement('div');
  t.textContent = label;
  t.style.cssText = `font:700 14px system-ui,-apple-system,sans-serif;color:${fg};word-break:break-word;max-width:100%;line-height:1.35;`;
  wrap.appendChild(badge);
  wrap.appendChild(t);
  if (src) {
    const u = document.createElement('div');
    u.textContent = src.length > 200 ? `${src.slice(0, 200)}…` : src;
