function prepareWorkspaceExportImagesInClone(root) {
  const base = window.location.href;
  root.querySelectorAll('img').forEach((img) => {
    const s = img.getAttribute('src');
    if (s && !s.startsWith('data:') && !s.startsWith('blob:')) {
      try {
        img.setAttribute('src', new URL(s, base).href);
      } catch (e) {}
    }
    img.removeAttribute('loading');
    img.loading = 'eager';
  });
}
function waitForWorkspaceExportImages(root) {
  const imgs = Array.from(root.querySelectorAll('img'));
  if (!imgs.length) return Promise.resolve();
  return Promise.all(imgs.map((img) => new Promise((resolve) => {
    const finish = () => {
      if (typeof img.decode === 'function') {
        img.decode().then(resolve).catch(resolve);
      } else {
        resolve();
      }
    };
    if (img.complete && img.naturalWidth > 0) {
      finish();
      return;
    }
    img.addEventListener('load', () => finish(), { once: true });
    img.addEventListener('error', () => finish(), { once: true });
    window.setTimeout(finish, 9000);
  })));
}
function sanitizeWorkspaceExportClone(clone, isDark) {
  clone.classList.remove('is-active', 'is-secondary-selected', 'is-connector-source');
  clone.removeAttribute('data-workspace-multi-selection');
  clone.style.boxShadow = 'none';
  clone.querySelectorAll('.cg-workspace-item__transform').forEach((n) => n.remove());
  if (clone.classList.contains('cg-workspace-item--storyboard_sheet')) {
    clone.style.background = '#ffffff';
    const body = clone.querySelector('.cg-workspace-item__body');
    if (body) body.style.background = '#ffffff';
    const sheet = clone.querySelector('.cg-workspace-storyboard-sheet');
    if (sheet) {
      sheet.style.background = '#ffffff';
      sheet.style.gap = '6px';
    }
  }
  clone.querySelectorAll('.cg-workspace-item--instagram_embed .cg-workspace-item__instagram').forEach((instaWrap) => {
    let href = '';
    const link = instaWrap.querySelector('a[href]');
    if (link) href = link.getAttribute('href') || '';
    if (!href) {
      const bq = instaWrap.querySelector('blockquote[data-instgrm-permalink]');
      if (bq) href = bq.getAttribute('data-instgrm-permalink') || '';
    }
    if (!href) {
      const ifr = instaWrap.querySelector('iframe[src*="instagram.com"]');
      if (ifr) {
        const isrc = ifr.getAttribute('src') || '';
        try {
          const u = new URL(isrc, window.location.origin);
          href = u.searchParams.get('url') || isrc;
        } catch (e) {
          href = isrc;
        }
      }
    }
    const itemRoot = instaWrap.closest('.cg-workspace-item');
    const titleText = getWorkspaceExportItemTitleFromClone(itemRoot);
    instaWrap.innerHTML = '';
    instaWrap.appendChild(buildWorkspaceExportGenericEmbedCard(href || '', titleText, isDark, 'instagram'));
  });
  clone.querySelectorAll('.cg-workspace-text-card__body').forEach((ta) => {
    if (ta.tagName === 'TEXTAREA') {
      const div = document.createElement('div');
      div.className = 'cg-workspace-text-card__view';
      div.textContent = ta.value;
      const st = ta.getAttribute('style');
      if (st) div.setAttribute('style', st);
      ta.parentNode.replaceChild(div, ta);
    }
  });
  clone.querySelectorAll('.cg-workspace-item__content[data-field="content"]').forEach((ta) => {
    if (ta.tagName === 'TEXTAREA') {
      const div = document.createElement('div');
      div.className = 'cg-workspace-item__content';
      div.textContent = ta.value;
      ta.parentNode.replaceChild(div, ta);
    }
  });
  clone.querySelectorAll('input.cg-workspace-item__title[data-field="title"]').forEach((inp) => {
    if (inp.tagName === 'INPUT') {
      const div = document.createElement('div');
      div.className = 'cg-workspace-item__floating-title';
      div.textContent = inp.value;
      inp.parentNode.replaceChild(div, inp);
    }
  });
  const replaceIframe = (iframe) => {
    const itemRoot = iframe.closest('.cg-workspace-item');
    const src = iframe.getAttribute('src') || '';
    const ytId = extractYouTubeVideoIdFromUrl(src);
    let replacement;
    if (ytId) {
      replacement = buildWorkspaceExportYoutubePlaceholder(iframe, isDark);
    } else {
      const titleText = getWorkspaceExportItemTitleFromClone(itemRoot);
      const kind = itemRoot && itemRoot.classList.contains('cg-workspace-item--map_embed') ? 'map' : 'link';
      replacement = buildWorkspaceExportGenericEmbedCard(src, titleText, isDark, kind);
    }
    if (iframe.parentNode) iframe.parentNode.replaceChild(replacement, iframe);
  };
  for (let pass = 0; pass < 4; pass += 1) {
    const frames = Array.from(clone.querySelectorAll('iframe'));
    if (!frames.length) break;
    frames.forEach(replaceIframe);
  }
  clone.querySelectorAll('.cg-workspace-item__header').forEach((h) => h.remove());
  clone.querySelectorAll('input[type="color"], input[type="file"], input[type="range"]').forEach((el) => el.remove());
  clone.querySelectorAll('.cg-workspace-item__frame, .cg-workspace-item__image-wrap, .cg-workspace-item__instagram').forEach((el) => {
    el.style.display = 'flex';
    el.style.flexDirection = 'column';
    el.style.flex = '1 1 auto';
    el.style.minHeight = '120px';
  });
}
async function exportWorkspaceRegionToCanvas(bundle, options = {}) {
  const onProgress = typeof options.onProgress === 'function' ? options.onProgress : () => {};
  const { minX, minY, maxX, maxY, items, connectors } = bundle;
  const bw = Math.max(1, maxX - minX);
  const bh = Math.max(1, maxY - minY);
  const isDark = document.body.classList.contains('kanban-theme-dark');
  const bg = isDark ? '#0f172a' : '#f8fafc';
  const dot = isDark ? 'rgba(248,250,252,0.08)' : 'rgba(15,23,42,0.12)';
  onProgress(5);
  const host = document.createElement('div');
  host.style.cssText = `position:fixed;left:-32000px;top:0;width:${bw}px;height:${bh}px;overflow:hidden;background:${bg};z-index:2147483000;`;
  host.style.backgroundImage = `radial-gradient(circle, ${dot} 1px, transparent 1.22px)`;
  host.style.backgroundSize = '14px 14px';
  const svgNs = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(svgNs, 'svg');
  svg.setAttribute('width', String(bw));
  svg.setAttribute('height', String(bh));
  svg.style.cssText = 'position:absolute;left:0;top:0;pointer-events:none;overflow:visible';
  const g = document.createElementNS(svgNs, 'g');
  g.setAttribute('transform', `translate(${-minX},${-minY})`);
  for (const connector of connectors) {
    const fromItem = getItemById(connector.from_item_id);
    const toItem = getItemById(connector.to_item_id);
    if (!fromItem || !toItem) continue;
    const pts = getConnectorEndpointsForItems(fromItem, toItem);
    const dx = pts.end.x - pts.start.x;
    const dy = pts.end.y - pts.start.y;
    const len = Math.hypot(dx, dy) || 1;
    const ux = dx / len;
    const uy = dy / len;
    const controlDist = Math.min(Math.max(48, len * 0.38), len * 0.55);
    const d = `M ${pts.start.x} ${pts.start.y} C ${pts.start.x + ux * controlDist} ${pts.start.y + uy * controlDist}, ${pts.end.x - ux * controlDist} ${pts.end.y - uy * controlDist}, ${pts.end.x} ${pts.end.y}`;
    const st = parseConnectorStyleJson(connector);
    const path = document.createElementNS(svgNs, 'path');
    path.setAttribute('d', d);
    path.setAttribute('fill', 'none');
    path.setAttribute('stroke', resolveWorkspaceStrokeColorForDisplay(st.color));
    path.setAttribute('stroke-width', String(st.strokeWidth));
    path.setAttribute('stroke-dasharray', '3 8');
    path.setAttribute('stroke-linecap', 'round');
    path.setAttribute('opacity', '0.9');
    g.appendChild(path);
  }
  svg.appendChild(g);
  host.appendChild(svg);
  const layer = document.createElement('div');
  layer.style.cssText = `position:absolute;left:0;top:0;width:${bw}px;height:${bh}px;`;
  const sorted = [...items].sort((a, b) => Number(a.z_index || 0) - Number(b.z_index || 0));
  const n = sorted.length || 1;
  for (let i = 0; i < sorted.length; i += 1) {
    const item = sorted[i];
    const el = document.querySelector(`.cg-workspace-item[data-item-id="${item.id}"]`);
    if (!el) continue;
    const clone = el.cloneNode(true);
    sanitizeWorkspaceExportClone(clone, isDark);
    const x = Number(item.x || 0) - minX;
    const y = Number(item.y || 0) - minY;
    clone.style.transform = `translate3d(${x}px, ${y}px, 0)`;
    clone.style.position = 'absolute';
    clone.style.left = '0';
    clone.style.top = '0';
    clone.style.margin = '0';
    clone.style.zIndex = String(Math.round(Number(item.z_index || 1) + 10));
    layer.appendChild(clone);
    onProgress(8 + Math.round(((i + 1) / n) * 22));
  }
  host.appendChild(layer);
  prepareWorkspaceExportImagesInClone(host);
  document.body.appendChild(host);
  await waitForWorkspaceExportImages(host);
  await new Promise((r) => {
    requestAnimationFrame(() => requestAnimationFrame(r));
  });
  onProgress(34);
  let canvas;
  let tick = 34;
  const tickTimer = setInterval(() => {
    tick = Math.min(tick + 2, 86);
    onProgress(tick);
  }, 280);
  try {
    if (typeof html2canvas === 'undefined') {
      throw new Error('Export library (html2canvas) failed to load.');
    }
    canvas = await html2canvas(host, {
      backgroundColor: bg,
      scale: Math.min(2, Math.max(1, Math.floor(2400 / Math.max(bw, bh)))),
      useCORS: true,
      logging: false,
      allowTaint: true,
    });
  } finally {
    clearInterval(tickTimer);
    host.remove();
  }
  onProgress(90);
  return canvas;
}
function workspaceExportBaseFilename(suffix) {
  const board = WS.bootstrap?.boards?.find((b) => String(b.id) === String(WS.boardId));
  const raw = (board?.name || 'workspace').toString().replace(/[^\w\-]+/g, '-').replace(/^-+|-+$/g, '') || 'workspace';
  return `${raw}-${suffix}-${Date.now()}`;
}
function downloadWorkspaceDataUrl(filename, dataUrl) {
  const a = document.createElement('a');
  a.href = dataUrl;
  a.download = filename;
  a.rel = 'noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
}
function addCanvasToPdfFitWidthPaged(pdf, canvas, options = {}) {
  const pageW = pdf.internal.pageSize.getWidth();
  const pageH = pdf.internal.pageSize.getHeight();
  const marginRatio = Number.isFinite(Number(options.marginRatio)) ? Number(options.marginRatio) : 0.02;
  const margin = Math.max(8, Math.round(Math.min(pageW, pageH) * marginRatio));
  const innerW = Math.max(1, pageW - margin * 2);
  const innerH = Math.max(1, pageH - margin * 2);
  const srcW = Math.max(1, Number(canvas.width || 1));
  const srcH = Math.max(1, Number(canvas.height || 1));
  const scale = innerW / srcW;
  const renderedH = srcH * scale;
  if (renderedH <= innerH) {
    const dy = margin + (innerH - renderedH) / 2;
    pdf.addImage(canvas.toDataURL('image/png'), 'PNG', margin, dy, innerW, renderedH);
    return;
  }
  const srcSliceH = Math.max(1, Math.floor(innerH / scale));
  let y = 0;
  let page = 0;
  while (y < srcH) {
    const h = Math.min(srcSliceH, srcH - y);
    const slice = document.createElement('canvas');
    slice.width = srcW;
    slice.height = h;
    const ctx = slice.getContext('2d');
    if (!ctx) break;
    ctx.drawImage(canvas, 0, y, srcW, h, 0, 0, srcW, h);
    const drawH = h * scale;
    if (page > 0) pdf.addPage();
    pdf.addImage(slice.toDataURL('image/png'), 'PNG', margin, margin, innerW, drawH);
    y += h;
    page += 1;
  }
}
async function runWorkspaceStageExport(kind, selectedOnly) {
  const bundle = getWorkspaceExportBundle(!!selectedOnly);
  if (!bundle) {
    alert(selectedOnly ? 'Select one or more cards to export.' : 'Nothing on the board to export.');
    return;
  }
  closeStageContextMenu();
  showWorkspaceExportOverlay();
  const titleEl = qs('#workspaceExportOverlayTitle');
  if (titleEl) titleEl.textContent = kind === 'pdf' ? 'Exporting PDF…' : 'Exporting image…';
  try {
    const canvas = await exportWorkspaceRegionToCanvas(bundle, {
      onProgress: (p) => setWorkspaceExportProgress(p),
    });
    const base = workspaceExportBaseFilename(selectedOnly ? 'selected' : 'all');
    if (kind === 'png') {
      setWorkspaceExportProgress(96);
      downloadWorkspaceDataUrl(`${base}.png`, canvas.toDataURL('image/png'));
      setWorkspaceExportProgress(100);
      return;
    }
    if (kind === 'pdf') {
      if (!window.jspdf || !window.jspdf.jsPDF) {
        throw new Error('PDF library failed to load.');
      }
      setWorkspaceExportProgress(93);
      const { jsPDF } = window.jspdf;
      const w = canvas.width;
      const h = canvas.height;
      const orientation = w >= h ? 'landscape' : 'portrait';
      const pdf = new jsPDF({ orientation, unit: 'pt', format: 'a4' });
      const pageW = pdf.internal.pageSize.getWidth();
      const pageH = pdf.internal.pageSize.getHeight();
      const ratio = Math.min((pageW * 0.92) / w, (pageH * 0.92) / h);
      const imgW = w * ratio;
      const imgH = h * ratio;
      const mx = (pageW - imgW) / 2;
      const my = (pageH - imgH) / 2;
      pdf.addImage(canvas.toDataURL('image/png'), 'PNG', mx, my, imgW, imgH);
      setWorkspaceExportProgress(98);
      pdf.save(`${base}.pdf`);
      setWorkspaceExportProgress(100);
    }
  } catch (err) {
    console.error(err);
    alert(err.message || 'Export failed.');
  } finally {
    window.setTimeout(() => hideWorkspaceExportOverlay(), 420);
  }
}
async function runWorkspaceItemExport(kind, itemId, labelSuffix = 'item') {
  const bundle = getWorkspaceExportBundleForItem(itemId);
  if (!bundle) {
    alert('Selected card is unavailable for export.');
    return;
  }
  showWorkspaceExportOverlay();
  const titleEl = qs('#workspaceExportOverlayTitle');
  if (titleEl) titleEl.textContent = kind === 'pdf' ? 'Exporting PDF…' : 'Exporting image…';
  try {
    const canvas = await exportWorkspaceRegionToCanvas(bundle, {
      onProgress: (p) => setWorkspaceExportProgress(p),
    });
    const base = workspaceExportBaseFilename(labelSuffix);
    if (kind === 'png') {
      setWorkspaceExportProgress(96);
      downloadWorkspaceDataUrl(`${base}.png`, canvas.toDataURL('image/png'));
      setWorkspaceExportProgress(100);
      return;
    }
    if (kind === 'pdf') {
      if (!window.jspdf || !window.jspdf.jsPDF) {
        throw new Error('PDF library failed to load.');
      }
      setWorkspaceExportProgress(93);
      const { jsPDF } = window.jspdf;
      const w = canvas.width;
      const h = canvas.height;
      const orientation = w >= h ? 'landscape' : 'portrait';
      const pdf = new jsPDF({ orientation, unit: 'pt', format: 'a4' });
      if (labelSuffix === 'storyboard-card') {
        // Keep storyboard readable: fill page width and continue on extra pages.
        addCanvasToPdfFitWidthPaged(pdf, canvas, { marginRatio: 0.015 });
      } else {
        const pageW = pdf.internal.pageSize.getWidth();
        const pageH = pdf.internal.pageSize.getHeight();
        const ratio = Math.min((pageW * 0.92) / w, (pageH * 0.92) / h);
        const imgW = w * ratio;
        const imgH = h * ratio;
        const mx = (pageW - imgW) / 2;
        const my = (pageH - imgH) / 2;
        pdf.addImage(canvas.toDataURL('image/png'), 'PNG', mx, my, imgW, imgH);
      }
      setWorkspaceExportProgress(98);
      pdf.save(`${base}.pdf`);
      setWorkspaceExportProgress(100);
    }
  } catch (err) {
    console.error(err);
    alert(err.message || 'Export failed.');
  } finally {
    window.setTimeout(() => hideWorkspaceExportOverlay(), 420);
  }
}
const WS_SHARE_ROLE_STORAGE_KEY = 'cg_workspace_share_role_v1';
const WS_SHARE_ROLE_COPY = {
  collaborator: 'Signed-in CineGrid users: read and write this workspace.',
  guest: 'No sign-in required. Temporary read and write; link and session expire 24 hours after first open.',
  client: 'No sign-in required. Read only; card placement and positions update in real time.',
};
function buildWorkspaceShareUrl(role) {
  const base = `${window.location.origin}${window.location.pathname}`;
  const params = new URLSearchParams();
  const nextRole = String(role || 'collaborator').toLowerCase();
  if (nextRole === 'guest' || nextRole === 'client') {
    const wsToken = workspaceBuildShareToken(nextRole);
    if (wsToken) params.set('ws', wsToken);
    params.set('share', nextRole);
  } else {
    if (WS.boardId) params.set('board_id', String(WS.boardId));
    params.set('share', 'collaborator');
  }
  return `${base}?${params.toString()}`;
}
function syncWorkspaceShareModalFromRole() {
  const sel = qs('#workspaceShareRoleSelect');
  const input = qs('#workspaceShareLinkInput');
  const desc = qs('#workspaceShareRoleDesc');
  if (!sel || !input || !desc) return;
  const role = sel.value || 'collaborator';
  input.value = buildWorkspaceShareUrl(role);
  desc.textContent = WS_SHARE_ROLE_COPY[role] || WS_SHARE_ROLE_COPY.collaborator;
  try {
    localStorage.setItem(WS_SHARE_ROLE_STORAGE_KEY, role);
  } catch (err) {
    /* ignore */
  }
}
function openWorkspaceShareModal() {
  if (!String(WS.boardId || '').trim()) {
    alert('Select a board before sharing.');
    return;
  }
  const modal = qs('#workspaceShareModal');
  const titleEl = qs('#workspaceShareTitle');
  const ownerEmail = qs('#workspaceShareOwnerEmail');
  const avatar = qs('#workspaceShareOwnerAvatar');
  const boardTitle = (qs('#workspaceBoardTitle')?.textContent || 'Workspace').trim() || 'Workspace';
  if (titleEl) titleEl.textContent = `Share “${boardTitle}”`;
  const email = (typeof window !== 'undefined' && window.userInfo && window.userInfo.user_email)
    ? String(window.userInfo.user_email)
    : '';
  if (ownerEmail) ownerEmail.textContent = email || 'You';
  if (avatar) {
    const letter = (email || 'Y').trim().charAt(0).toUpperCase() || '?';
    avatar.textContent = letter;
  }
  const sel = qs('#workspaceShareRoleSelect');
  if (sel) {
    let initial = 'collaborator';
    try {
      const stored = localStorage.getItem(WS_SHARE_ROLE_STORAGE_KEY);
      if (stored && WS_SHARE_ROLE_COPY[stored]) initial = stored;
    } catch (err) {
      /* ignore */
    }
    sel.value = initial;
  }
  syncWorkspaceShareModalFromRole();
  if (modal) {
    modal.hidden = false;
    modal.setAttribute('aria-hidden', 'false');
  }
}
function closeWorkspaceShareModal() {
  const modal = qs('#workspaceShareModal');
  if (!modal) return;
  modal.hidden = true;
  modal.setAttribute('aria-hidden', 'true');
  cgWorkspaceFlushDeferredPollRender();
}
function closeWorkspaceStoryboardAddCellsModal() {
