function openWorkspaceStoryboardAddCellsModal(itemId) {
  const item = getItemById(itemId);
  if (!item || item.item_type !== WORKSPACE_STORYBOARD_ITEM_TYPE) return;
  const { rows, cols } = parseStoryboardSheetModel(item.meta_json);
  const rowsInput = qs('#workspaceStoryboardAddRowsInput');
  const colsInput = qs('#workspaceStoryboardAddColsInput');
  const hint = qs('#workspaceStoryboardAddCellsHint');
  if (rowsInput) {
    rowsInput.min = '1';
    rowsInput.max = String(Math.max(1, 8 - rows));
    rowsInput.value = '1';
  }
  if (colsInput) {
    colsInput.min = String(cols);
    colsInput.max = String(cols);
    colsInput.value = String(cols);
  }
  if (hint) {
    hint.textContent = `Current grid: ${rows} Row x ${cols} Col`;
  }
  WS.storyboardAddCellsItemId = Number(itemId);
  const modal = qs('#workspaceStoryboardAddCellsModal');
  if (!modal) return;
  modal.hidden = false;
  modal.setAttribute('aria-hidden', 'false');
  window.requestAnimationFrame(() => {
    if (rowsInput) rowsInput.focus();
  });
}
async function handleWorkspaceStageContextAction(action) {
