  closeStageContextMenu();
  try {
    switch (action) {
      case 'share':
        if (!workspaceStageMayShowShare()) return;
        openWorkspaceShareModal();
        break;
      case 'new-note':
        await createWorkspaceItem(createPayloadAtWorldPoint(createDefaultNotePayload(), wp));
        break;
      case 'new-text':
        await createTextCardAtWorldPoint(wp);
        break;
      case 'new-sketch':
        await createSketchCardAtWorldPoint(wp);
        break;
      case 'new-image':
        WS.importImageWorldPoint = wp;
        qs('#workspaceImageInput').click();
        break;
      case 'new-palette':
        await addPaletteCardAtWorldPoint(wp);
        break;
      case 'new-storyboard':
        await createWorkspaceStoryboardSheetAtWorldPoint(wp);
        break;
      case 'new-spreadsheet':
        WS.stageContextWorldPoint = wp;
        openSpreadsheetMenu();
        break;
      case 'import-palette':
        await addPaletteCardAtWorldPoint(wp);
        break;
      case 'import-storyboard':
        await createWorkspaceStoryboardSheetAtWorldPoint(wp);
        break;
      case 'import-spreadsheet':
        WS.stageContextWorldPoint = wp;
        openSpreadsheetMenu();
        break;
      case 'import-text':
        qs('#workspaceImportTextInput').click();
        break;
      case 'import-sheet':
        qs('#workspaceImportSheetInput').click();
        break;
      case 'import-image':
        WS.importImageWorldPoint = wp;
        qs('#workspaceImageInput').click();
        break;
      case 'export-all-png':
        await runWorkspaceStageExport('png', false);
        break;
      case 'export-all-pdf':
        await runWorkspaceStageExport('pdf', false);
        break;
      case 'export-selected-png':
        await runWorkspaceStageExport('png', true);
        break;
      case 'export-selected-pdf':
        await runWorkspaceStageExport('pdf', true);
        break;
      case 'refresh':
        await workspaceRefreshPageFromStageMenu();
        break;
      default:
        break;
    }
  } catch (err) {
    console.error(err);
    alert(err.message || 'Action failed.');
  }
}
async function createSketchCardFromCustomSize() {
