function buildWorkspaceStoryboardCells(rows, cols) {
  const r = Math.max(1, Math.min(8, Math.floor(Number(rows)) || 1));
  const c = Math.max(1, Math.min(8, Math.floor(Number(cols)) || 1));
  const cells = [];
  const total = r * c;
  for (let i = 0; i < total; i++) {
    const row = Math.floor(i / c);
    cells.push({
      shot: `SHOT ${i + 1}`,
      scene: `SCENE ${row + 1}`,
      camera_title: '',
      action: '',
      style: '',
      camera_detail: '',
      dialog: '',
      image_path: '',
      image_display_url: '',
    });
  }
  return { rows: r, cols: c, cells };
}
function computeWorkspaceStoryboardFrameSize(r, c) {
  const gap = 10;
  const pad = 12;
  const cellMinW = 160;
  const cellMinH = 248;
  const width = pad * 2 + c * cellMinW + Math.max(0, c - 1) * gap;
  const height = pad * 2 + r * cellMinH + Math.max(0, r - 1) * gap;
  return { width, height };
}
function isWorkspaceStoryboardCellEmpty(cell) {
  if (!cell || typeof cell !== 'object') return true;
  if (String(cell.image_path || '').trim() !== '') return false;
  if (String(cell.image_display_url || '').trim() !== '') return false;
  if (String(cell.action || '').trim() !== '') return false;
  if (String(cell.style || '').trim() !== '') return false;
  if (String(cell.camera_detail || '').trim() !== '') return false;
  if (String(cell.camera_title || '').trim() !== '') return false;
  if (String(cell.dialog || '').trim() !== '') return false;
  return true;
}
async function createWorkspaceStoryboardSheetAtWorldPoint(worldPoint) {
  const rowsIn = qs('#workspaceStoryboardRowsInput');
  const colsIn = qs('#workspaceStoryboardColsInput');
  const r = clamp(Math.floor(Number(rowsIn?.value ?? 3)), 1, 8);
  const c = clamp(Math.floor(Number(colsIn?.value ?? 3)), 1, 8);
  if (rowsIn) rowsIn.value = String(r);
  if (colsIn) colsIn.value = String(c);
  const { rows, cols, cells } = buildWorkspaceStoryboardCells(r, c);
  const { width, height } = computeWorkspaceStoryboardFrameSize(rows, cols);
  const item = await createWorkspaceItem(createPayloadAtWorldPoint({
    item_type: WORKSPACE_STORYBOARD_ITEM_TYPE,
    title: '',
    width,
    height,
    meta_json: stringifyStoryboardSheetMeta(
      { aspect_ratio: width / Math.max(1, height) },
      rows,
      cols,
      cells,
      []
    ),
    z_index: Math.max(1, ...WS.items.map(entry => Number(entry.z_index || 0)), ...WS.strokes.map(entry => Number(entry.z_index || 0)), ...WS.connectors.map(entry => Number(entry.z_index || 0))) + 1,
  }, worldPoint));
  if (!item) return;
  setSelectedItems([Number(item.id)], Number(item.id));
  setWorkspaceMode('select');
  openWorkspaceCharacters();
}
async function createWorkspaceStoryboardSheetFromMenu() {
  const stage = getStage();
  if (!stage) return;
  const rect = stage.getBoundingClientRect();
  const centerWorld = stagePointToWorld(rect.left + rect.width / 2, rect.top + rect.height / 2);
  await createWorkspaceStoryboardSheetAtWorldPoint(centerWorld);
}
async function appendWorkspaceStoryboardCells(sourceItemId, addRows, addCols) {
  if (workspaceIsClientView()) return;
  const source = getItemById(sourceItemId);
  if (!source || source.item_type !== WORKSPACE_STORYBOARD_ITEM_TYPE) return;
  const { meta, rows, cols, cells, characters } = parseStoryboardSheetModel(source.meta_json);
  const rAdd = clamp(Math.floor(Number(addRows || 0)), 1, 8);
  const cAdd = clamp(Math.floor(Number(addCols || 0)), 1, 8);
  if (cAdd !== cols) {
    throw new Error(`This storyboard uses ${cols} columns. Enter ${cols} for Col.`);
  }
  const nextRows = rows + rAdd;
  if (nextRows > 8) {
    throw new Error(`This storyboard already has ${rows} rows. Maximum rows is 8.`);
  }
  const nextCells = cells.map((cell) => ({ ...cell }));
  const baseIndex = nextCells.length;
  const baseScene = rows;
  for (let i = 0; i < rAdd * cols; i++) {
    const localRow = Math.floor(i / cols);
    nextCells.push({
      shot: `SHOT ${baseIndex + i + 1}`,
      scene: `SCENE ${baseScene + localRow + 1}`,
      camera_title: '',
      action: '',
      style: '',
      camera_detail: '',
      dialog: '',
      image_path: '',
      image_display_url: '',
    });
  }
  const prevRows = Math.max(1, Number(rows || 1));
  source.height = Math.max(160, Number(source.height || 1) * (nextRows / prevRows));
  source.meta_json = stringifyStoryboardSheetMeta(
    { ...meta, aspect_ratio: Number(source.width || 1) / Math.max(1, Number(source.height || 1)) },
    nextRows,
    cols,
    nextCells,
    characters
  );
  renderWorkspace();
  scheduleWorkspaceHistoryCapture();
  try {
    const c = window.__cgWorkspaceCollab;
    if (c && typeof c.upsertItem === 'function') c.upsertItem(source);
  } catch (e) {}
  notifyWorkspaceCollabItemsChanged();
  await saveWorkspaceItem(source);
  setSelectedItems([Number(source.id)], Number(source.id));
}
async function deleteWorkspaceStoryboardEmptyCells(sourceItemId) {
  if (workspaceIsClientView()) return;
  const source = getItemById(sourceItemId);
  if (!source || source.item_type !== WORKSPACE_STORYBOARD_ITEM_TYPE) return;
  const { meta, rows, cols, cells, characters } = parseStoryboardSheetModel(source.meta_json);
  const nextCells = cells.filter((cell) => !isWorkspaceStoryboardCellEmpty(cell));
  if (nextCells.length === cells.length) {
    alert('No empty cells to delete.');
    return;
  }
  const nextRows = Math.max(1, Math.ceil(nextCells.length / Math.max(1, cols)));
  const prevRows = Math.max(1, Number(rows || 1));
  source.height = Math.max(160, Number(source.height || 1) * (nextRows / prevRows));
  source.meta_json = stringifyStoryboardSheetMeta(
    { ...meta, aspect_ratio: Number(source.width || 1) / Math.max(1, Number(source.height || 1)) },
    nextRows,
    cols,
    nextCells,
    characters
  );
  renderWorkspace();
  scheduleWorkspaceHistoryCapture();
  try {
    const c = window.__cgWorkspaceCollab;
    if (c && typeof c.upsertItem === 'function') c.upsertItem(source);
  } catch (e) {}
  notifyWorkspaceCollabItemsChanged();
  await saveWorkspaceItem(source);
  setSelectedItems([Number(source.id)], Number(source.id));
}
/** Split a multi-cell storyboard sheet into separate 1×1 storyboard items (one per shot), preserving cell fields and image actions. */
async function breakWorkspaceStoryboardIntoShotCards(sourceItemId) {
  if (workspaceIsClientView()) return;
  const source = getItemById(sourceItemId);
  if (!source || source.item_type !== WORKSPACE_STORYBOARD_ITEM_TYPE) return;
  const { cells } = parseStoryboardSheetModel(source.meta_json);
  if (!Array.isArray(cells) || cells.length <= 1) {
    alert('This storyboard only has one shot — nothing to break apart.');
    return;
  }
  const { width: newW, height: newH } = computeWorkspaceStoryboardFrameSize(1, 1);
  const gap = 24;
  const baseZ = Math.max(
    1,
    ...WS.items.map((e) => Number(e.z_index || 0)),
    ...WS.strokes.map((e) => Number(e.z_index || 0)),
    ...WS.connectors.map((e) => Number(e.z_index || 0))
  ) + 1;
  const srcX = Number(source.x || 0);
  const srcY = Number(source.y || 0);
  const srcW = Number(source.width || newW);
  const startX = srcX + srcW + gap;
  const startY = srcY;
  const srcRot = Number(source.rotation || 0);
  const createPromises = cells.map((cell, i) => {
    const cellCopy = JSON.parse(JSON.stringify(cell));
    const centerWorld = {
      x: startX + i * (newW + gap) + newW / 2,
      y: startY + newH / 2,
    };
    const payload = createPayloadAtWorldPoint({
      item_type: WORKSPACE_STORYBOARD_ITEM_TYPE,
      title: '',
      width: newW,
      height: newH,
      meta_json: JSON.stringify({
        rows: 1,
        cols: 1,
        cells: [cellCopy],
        aspect_ratio: newW / Math.max(1, newH),
      }),
      z_index: baseZ + i,
      rotation: srcRot,
    }, centerWorld);
    return createWorkspaceItem(payload, null, { deferVisualSync: true });
  });
  const createdItems = await Promise.all(createPromises);
  const createdIds = createdItems.filter(Boolean).map((it) => Number(it.id));
  if (createdIds.length === 0) {
    alert('Failed to create shot cards.');
    return;
  }
  try {
    await trashWorkspaceItem(sourceItemId, { render: false, captureHistory: false, notify: false });
  } catch (err) {
    if (!isWorkspaceItemNotFoundError(err)) {
      console.error(err);
      alert(err?.message || 'Created shot cards but could not remove the original storyboard.');
    }
  }
  renderWorkspace();
  scheduleWorkspaceHistoryCapture();
  try {
    const c = window.__cgWorkspaceCollab;
    if (c && typeof c.deleteItem === 'function') c.deleteItem(sourceItemId);
  } catch (e) {}
  notifyWorkspaceCollabItemsChanged();
  setSelectedItems(createdIds, createdIds[createdIds.length - 1]);
}
async function addImageFromFile(file, worldPoint = null) {
  if (!file) return;
  const imageEl = await loadImageElement(file);
  const imageSize = getWorkspaceImageDisplaySize(
    imageEl.naturalWidth || imageEl.width || 1,
    imageEl.naturalHeight || imageEl.height || 1
  );
  const previewUrl = URL.createObjectURL(file);
  const tempId = (WS.nextTempWorkspaceItemId = (WS.nextTempWorkspaceItemId || 0) - 1);
  const tempItem = createPayloadAtWorldPoint({
    id: tempId,
    item_type: 'image',
    title: '',
    width: imageSize.width,
    height: imageSize.height,
    image_path: previewUrl,
    meta_json: JSON.stringify({
      aspect_ratio: imageSize.aspectRatio,
      natural_width: imageSize.naturalWidth,
      natural_height: imageSize.naturalHeight,
    }),
    _uploading: true,
    _uploadSurfaceOnly: true,
    _uploadProgress: 2,
    _uploadLabel: '',
    z_index: Math.max(1, ...WS.items.map(entry => Number(entry.z_index || 0)), ...WS.strokes.map(entry => Number(entry.z_index || 0)), ...WS.connectors.map(entry => Number(entry.z_index || 0))) + 1,
  }, worldPoint, worldPoint ? { anchor: 'topleft' } : null);
  assignHistoryKey(tempItem, 'item');
  WS.items.push(tempItem);
  /* Block workspace_sync immediately: polls used to run during the rAF/compress gap and drop this temp row. */
  WS.workspaceImageUploadDepth = (WS.workspaceImageUploadDepth || 0) + 1;
  renderWorkspace();
  setSelectedItems([tempItem.id], tempItem.id);
  await new Promise((r) => {
    if (typeof requestAnimationFrame !== 'undefined') {
      requestAnimationFrame(() => requestAnimationFrame(r));
    } else {
      setTimeout(r, 0);
    }
  });

  let workspaceImageUploadSucceeded = false;
  try {
    stopBoardCardSyncPolling();
    tempItem._uploadProgress = 4;
    updateWorkspaceUploadProgressElement(tempItem);
    const optimizedFile = await compressImageForWorkspace(file, 650 * 1024, { preloadedImage: imageEl });
    tempItem._uploadProgress = 8;
    updateWorkspaceUploadProgressElement(tempItem);

    const historyKey = tempItem._historyKey;
    const formData = new FormData();
    const payload = {
      item_type: 'image',
      title: String(tempItem.title || '').trim(),
      x: Number(tempItem.x || 0),
      y: Number(tempItem.y || 0),
      width: Number(tempItem.width || 340),
      height: Number(tempItem.height || 260),
      z_index: Number(tempItem.z_index || 0),
      rotation: Number(tempItem.rotation || 0),
      style_json: tempItem.style_json || '',
      meta_json: tempItem.meta_json || '',
    };
    Object.entries(payload).forEach(([key, value]) => {
      if (value === undefined || value === null) return;
      formData.append(key, String(value));
    });
    formData.append('board_id', String(WS.boardId));
    formData.append('image', optimizedFile, optimizedFile.name || 'workspace-image.jpg');
    appendWorkspaceShareToFormData(formData);

    const data = await uploadJsonWithProgress('/api/freelance_kanban.php?action=create_workspace_item', formData, (percent) => {
      const surface = !!tempItem._uploadSurfaceOnly;
      if (percent < 0) {
        if (!surface) tempItem._uploadLabel = 'Saving on server...';
        tempItem._uploadProgress = 99;
        tempItem._uploadServerWait = true;
        delete tempItem._uploadWireTail;
      } else {
        const p = clamp(percent, 8, 99);
        tempItem._uploadProgress = p;
        if (p >= 99) {
          tempItem._uploadWireTail = true;
          if (!surface) tempItem._uploadLabel = 'Finishing upload…';
        } else {
          delete tempItem._uploadWireTail;
          if (!surface) tempItem._uploadLabel = 'Uploading image...';
        }
        delete tempItem._uploadServerWait;
      }
      updateWorkspaceUploadProgressElement(tempItem);
    });
    const nextItem = data.item || null;
    if (!nextItem) throw new Error('Image upload failed.');
    /* Server row used create-time geometry; user may have moved/resized while uploading. */
    nextItem.x = Number(tempItem.x ?? nextItem.x ?? 0);
    nextItem.y = Number(tempItem.y ?? nextItem.y ?? 0);
    nextItem.width = Number(tempItem.width ?? nextItem.width ?? 340);
    nextItem.height = Number(tempItem.height ?? nextItem.height ?? 260);
    nextItem.rotation = Number(tempItem.rotation ?? nextItem.rotation ?? 0);
    nextItem.z_index = Number(tempItem.z_index ?? nextItem.z_index ?? 0);
    if (tempItem.style_json != null) nextItem.style_json = tempItem.style_json || nextItem.style_json || '';
    if (tempItem.meta_json != null) nextItem.meta_json = tempItem.meta_json || nextItem.meta_json || '';
    if (String(tempItem.title || '').trim() !== '') nextItem.title = tempItem.title;
    delete nextItem._uploading;
    delete nextItem._uploadSurfaceOnly;
    delete nextItem._uploadProgress;
    delete nextItem._uploadLabel;
    delete nextItem._uploadServerWait;
    delete nextItem._uploadWireTail;
    nextItem._historyKey = historyKey;
    const tempIndex = WS.items.findIndex(entry => String(entry.id) === String(tempItem.id));
    if (tempIndex >= 0) {
      WS.items[tempIndex] = nextItem;
    } else {
      WS.items.push(nextItem);
    }
    const oldTempNumericId = Number(tempItem.id);
    const newRealNumericId = Number(nextItem.id);
    if (Number.isFinite(oldTempNumericId) && oldTempNumericId < 0 && Number.isFinite(newRealNumericId) && newRealNumericId > 0
      && WS.selectedItemIds.some((id) => Number(id) === oldTempNumericId)) {
      const nextIds = [...new Set(WS.selectedItemIds.map((id) => (Number(id) === oldTempNumericId ? newRealNumericId : Number(id))))];
      const nextActive = Number(WS.activeItemId) === oldTempNumericId ? newRealNumericId : WS.activeItemId;
      setSelectedItems(nextIds, nextActive);
    }
    workspaceMarkItemsPositionProtected([newRealNumericId]);
    renderWorkspace();
    scheduleWorkspaceHistoryCapture();
    try {
      const c = window.__cgWorkspaceCollab;
      if (c && typeof c.deleteItem === 'function') c.deleteItem(tempItem.id);
      if (c && typeof c.upsertItem === 'function') c.upsertItem(nextItem);
    } catch (e) {}
    workspaceRegisterRecentUploadSnapshot(nextItem);
    void saveWorkspaceItem(nextItem).catch((err) => console.error('Post-upload layout save:', err));
    notifyWorkspaceCollabItemsChanged();
    workspaceImageUploadSucceeded = true;
  } catch (err) {
    WS.items = WS.items.filter(entry => String(entry.id) !== String(tempItem.id));
    renderWorkspace();
    try {
      const c = window.__cgWorkspaceCollab;
      if (c && typeof c.deleteItem === 'function') c.deleteItem(tempItem.id);
    } catch (e) {}
    notifyWorkspaceCollabItemsChanged();
    throw err;
  } finally {
    WS.workspaceImageUploadDepth = Math.max(0, (WS.workspaceImageUploadDepth || 0) - 1);
    if (workspaceImageUploadSucceeded) {
      void pollWorkspaceOnce();
    }
    if (String(WS.boardId || '').trim()) {
      startBoardCardSyncPolling();
    }
    const blobUrl = previewUrl;
    const revoke = () => {
      try {
        URL.revokeObjectURL(blobUrl);
      } catch (e) {}
    };
    if (typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function') {
      window.requestAnimationFrame(() => {
        window.requestAnimationFrame(revoke);
      });
    } else {
      setTimeout(revoke, 0);
    }
  }
}
function extractDroppedText(dataTransfer) {
  if (!dataTransfer) return '';
  const uriList = String(dataTransfer.getData('text/uri-list') || '').split(/\r?\n/).map(line => line.trim()).filter(line => line && !line.startsWith('#'));
  if (uriList.length) return uriList[0];
  return getDataTransferText(dataTransfer, ['text/plain', 'text', 'Text', 'public.utf8-plain-text']);
}
function isPointerInsideStage(clientX, clientY) {
  const stage = getStage();
  if (!stage) return false;
  const rect = stage.getBoundingClientRect();
  return clientX >= rect.left && clientX <= rect.right && clientY >= rect.top && clientY <= rect.bottom;
}
function onStageDragOver(event) {
  if (workspaceIsClientView()) return;
  const dataTransfer = event.dataTransfer;
  if (!dataTransfer) return;
  const dragTypes = Array.from(dataTransfer.types || []);
  if (WS.dragFromTrash || dragTypes.includes('application/x-cg-trash-origin')) {
    event.preventDefault();
    return;
  }
  const hasStoredKanbanDrag = !!getStoredDraggedKanbanCard();
  const hasImageFile = Array.from(dataTransfer.files || []).some(file => file.type && file.type.startsWith('image/'));
  const hasKanbanCardType = dragTypes.includes('application/x-cinegrid-kanban-card') || dragTypes.includes('text/x-cinegrid-kanban-card');
  const hasLinkType = hasStoredKanbanDrag || hasKanbanCardType || dragTypes.includes('text/uri-list') || dragTypes.includes('text/plain') || dragTypes.includes('text') || dragTypes.includes('Text') || dragTypes.includes('public.url') || dragTypes.includes('public.utf8-plain-text');
  const hasFileType = dragTypes.includes('Files');
  if (!hasImageFile && !hasLinkType && !hasFileType) return;
  event.preventDefault();
  dataTransfer.dropEffect = (hasImageFile || hasFileType || hasStoredKanbanDrag || hasKanbanCardType) ? 'copy' : 'link';
}
function onWorkspaceDragOver(event) {
  if (!isPointerInsideStage(event.clientX, event.clientY)) return;
  onStageDragOver(event);
}
async function handleDrop(event) {
  if (workspaceIsClientView()) return;
  const dataTransfer = event.dataTransfer;
  if (!dataTransfer) return;
  if (!isPointerInsideStage(event.clientX, event.clientY)) return;
  const dragTypes = Array.from(dataTransfer.types || []);
  if (WS.dragFromTrash || dragTypes.includes('application/x-cg-trash-origin')) {
    event.preventDefault();
    event.stopPropagation();
    WS.dragFromTrash = false;
    return;
  }
  const worldPoint = stagePointToWorld(event.clientX, event.clientY);
  const droppedKanbanCard = extractDroppedKanbanCard(dataTransfer);
  const droppedImages = Array.from(dataTransfer.files || []).filter(file => file.type && file.type.startsWith('image/'));
  const droppedText = extractDroppedText(dataTransfer);
  const payload = await normalizeWorkspacePayload(inferItemFromPastedText(droppedText));
  if (!droppedKanbanCard && !droppedImages.length && !payload) return;
  event.preventDefault();
  closeBrushMenu();
  closeTextMenu();
  closeTextPropertyPanel();
  closeImageContextMenu();
  if (droppedKanbanCard) {
    await createWorkspaceItem(createPayloadAtWorldPoint(buildWorkspaceKanbanCardPayload(droppedKanbanCard), worldPoint));
    clearStoredDraggedKanbanCard();
    return;
  }
  if (droppedImages.length) {
    for (const [index, file] of droppedImages.entries()) {
      const nextPoint = {
        x: worldPoint.x + (index * 24),
        y: worldPoint.y + (index * 24),
      };
      await addImageFromFile(file, nextPoint);
    }
    return;
  }
  await createWorkspaceItem(createPayloadAtWorldPoint(payload, worldPoint));
}
async function handlePaste(event) {
  const workspaceRoot = document.querySelector('.cg-workspace-page');
  const target = event.target instanceof HTMLElement ? event.target : document.body;
  const activeElement = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const focusTarget = activeElement && activeElement !== document.body ? activeElement : target;
  const inWorkspace = focusTarget === document.body || focusTarget === document.documentElement || (workspaceRoot && workspaceRoot.contains(focusTarget));
  if (!inWorkspace) return;
  const inAiPrompt = (el) => el && el.closest && el.closest('.cg-workspace-ai-prompt');
  if (inAiPrompt(target) || inAiPrompt(focusTarget)) {
    return;
  }
  const clipboard = event.clipboardData;
  if (!clipboard) return;
  const imageItems = Array.from(clipboard.items || []).filter(item => item.type && item.type.startsWith('image/'));
  const imageFiles = Array.from(clipboard.files || []).filter(file => file.type && file.type.startsWith('image/'));
  const pastedImages = imageItems.length
    ? imageItems.map(item => item.getAsFile()).filter(Boolean)
    : imageFiles;
  const text = clipboard.getData('text/plain');
  const pasteWorld = getWorldPointForWorkspacePaste();
  /* Infer synchronously so we can bail out before any await — otherwise the event loop runs default paste into the focused field and we also create a canvas item. */
  const inferredSync = inferItemFromPastedText(text);
  const richCanvasPaste = pastedImages.length > 0 || (inferredSync && inferredSync.item_type && inferredSync.item_type !== 'sticky_note');
  if (isPasteBlockedTarget(focusTarget) && !richCanvasPaste) return;
  if (WS.mode === 'text' && text && text.trim() && !pastedImages.length) {
    const trimmed = text.trim();
    const urlOnly = trimmed.match(/^https?:\/\/\S+$/i);
    if (!urlOnly && (!inferredSync || inferredSync.item_type === 'sticky_note' || inferredSync.item_type === 'text_card')) {
      event.preventDefault();
      const inferred = inferItemFromPastedText(text);
      const base = inferred && typeof inferred === 'object' ? inferred : { title: '', content: text };
      await createWorkspaceItem(createPayloadAtWorldPoint({
        ...base,
        item_type: 'text_card',
        meta_json: JSON.stringify(buildTextCardMetaFromUi()),
      }, pasteWorld, { anchor: 'topleft' }));
      return;
    }
  }
  const payload = await normalizeWorkspacePayload(inferredSync);
  if (pastedImages.length) {
    event.preventDefault();
    for (const [idx, file] of pastedImages.entries()) {
      if (!file) continue;
      const wp = pasteWorld
        ? { x: pasteWorld.x + (idx * 24), y: pasteWorld.y + (idx * 24) }
        : null;
      await addImageFromFile(file, wp);
    }
    return;
  }
  if (!payload) return;
  event.preventDefault();
  await createWorkspaceItem(createPayloadAtWorldPoint(payload, pasteWorld));
}
function workspaceItemIncludedInViewFit(item) {
  if (!item) return false;
  if (workspaceItemHiddenFromCanvas(item)) return false;
  if (isWorkspaceItemLayerHidden(item)) return false;
  return true;
}
function getWorkspaceItemAxisBounds(item) {
  const x = Number(item.x || 0);
  const y = Number(item.y || 0);
  const width = Math.max(1, Number(item.width || 1));
  const height = Math.max(1, Number(item.height || 1));
  const rot = Number(item.rotation || 0);
  if (!Number.isFinite(rot) || Math.abs(rot % 360) < 0.01) {
    return { minX: x, minY: y, maxX: x + width, maxY: y + height };
  }
  const rad = (rot * Math.PI) / 180;
  const cos = Math.abs(Math.cos(rad));
  const sin = Math.abs(Math.sin(rad));
  const rotW = width * cos + height * sin;
  const rotH = width * sin + height * cos;
  const cx = x + width / 2;
  const cy = y + height / 2;
  return {
    minX: cx - rotW / 2,
    minY: cy - rotH / 2,
    maxX: cx + rotW / 2,
    maxY: cy + rotH / 2,
  };
}
function getWorkspaceVisibleContentBounds() {
  const acc = { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity };
  let count = 0;
  WS.items.forEach((item) => {
    if (!workspaceItemIncludedInViewFit(item)) return;
    const b = getWorkspaceItemAxisBounds(item);
    if (!Number.isFinite(b.minX) || !Number.isFinite(b.minY)) return;
    acc.minX = Math.min(acc.minX, b.minX);
    acc.minY = Math.min(acc.minY, b.minY);
    acc.maxX = Math.max(acc.maxX, b.maxX);
    acc.maxY = Math.max(acc.maxY, b.maxY);
    count += 1;
  });
  return count > 0 && Number.isFinite(acc.minX) ? acc : null;
}
function resetView() {
  const stage = getStage();
  if (!stage) {
    WS.camera = { x: 160, y: 100, scale: 1 };
    applyCamera();
    focusWorkspaceStage();
    scheduleWorkspaceHistoryCapture();
    return;
  }
  const bounds = getWorkspaceVisibleContentBounds();
  if (!bounds) {
    WS.camera = { x: 160, y: 100, scale: 1 };
    applyCamera();
    focusWorkspaceStage();
    scheduleWorkspaceHistoryCapture();
    return;
  }
  const rect = stage.getBoundingClientRect();
  const padding = 72;
  const boundsWidth = Math.max(1, bounds.maxX - bounds.minX);
  const boundsHeight = Math.max(1, bounds.maxY - bounds.minY);
  const availableWidth = Math.max(1, rect.width - (padding * 2));
  const availableHeight = Math.max(1, rect.height - (padding * 2));
  const fitScale = Math.min(availableWidth / boundsWidth, availableHeight / boundsHeight);
  const nextScale = clamp(Math.min(1, fitScale), 0.01, 1);
  const centerX = bounds.minX + (boundsWidth / 2);
  const centerY = bounds.minY + (boundsHeight / 2);
  WS.camera.scale = nextScale;
  WS.camera.x = (rect.width / 2) - (centerX * nextScale);
  WS.camera.y = (rect.height / 2) - (centerY * nextScale);
  applyCamera();
  focusWorkspaceStage();
  scheduleWorkspaceHistoryCapture();
}
async function clearWorkspaceDocument() {
  const hasContent = WS.items.length || WS.strokes.length || WS.connectors.length;
  if (!hasContent) {
    resetView();
    return;
  }
  const clearOk = typeof window.cgPortalConfirm === 'function'
    ? await window.cgPortalConfirm('Clear all workspace elements and start with a blank stage?', { title: 'Clear workspace' })
    : window.confirm('Clear all workspace elements and start with a blank stage?');
  if (!clearOk) return;

  Object.values(WS.itemSaveTimers || {}).forEach(timerId => clearTimeout(timerId));
  WS.itemSaveTimers = {};

  const snapshot = {
    items: [...WS.items],
    strokes: [...WS.strokes],
    connectors: [...WS.connectors],
    activeItemId: WS.activeItemId,
    selectedItemIds: [...WS.selectedItemIds],
  };

  const itemIds = snapshot.items.map(item => Number(item.id)).filter(Boolean);
  const strokeIds = snapshot.strokes.map(stroke => Number(stroke.id)).filter(Boolean);
  const connectorIds = snapshot.connectors.map(connector => Number(connector.id)).filter(Boolean);

  WS.items = [];
  WS.strokes = [];
  WS.connectors = [];
  WS.activeItemId = null;
  WS.selectedItemIds = [];
  closeBrushMenu();
  renderWorkspace();
  resetView();
  notifyWorkspaceCollabItemsChanged();

  try {
    await Promise.all(connectorIds.map(connectorId => deleteWorkspaceConnector(connectorId)));
    await Promise.all(strokeIds.map(strokeId => deleteWorkspaceStroke(strokeId)));
    await Promise.all(itemIds.map(itemId => deleteWorkspaceItem(itemId)));
    WS.items = [];
    WS.strokes = [];
    WS.connectors = [];
    WS.activeItemId = null;
    WS.selectedItemIds = [];
    renderWorkspace();
    resetView();
    resetWorkspaceHistory();
    notifyWorkspaceCollabItemsChanged();
  } catch (err) {
    WS.items = snapshot.items;
    WS.strokes = snapshot.strokes;
    WS.connectors = snapshot.connectors;
    WS.activeItemId = snapshot.activeItemId;
    WS.selectedItemIds = snapshot.selectedItemIds;
    renderWorkspace();
    notifyWorkspaceCollabItemsChanged();
    alert(err.message || 'Failed to clear workspace.');
  }
}

