const workspaceLayersListEl = qs('#workspaceLayersList');
initWorkspaceLayersPanelDnD();
workspaceLayersListEl?.addEventListener('click', (event) => {
  if (WS.layersPanelSuppressRowClick) {
    WS.layersPanelSuppressRowClick = false;
    return;
  }
  if (event.button !== 0) return;
  const pt = layersPanelPointerTargetEl(event);
  if (!pt || typeof pt.closest !== 'function') return;
  const layerActionBtn = pt.closest('[data-layer-action]');
  if (layerActionBtn) {
    event.preventDefault();
    event.stopPropagation();
    const itemId = Number(layerActionBtn.getAttribute('data-layer-item-id'));
    const action = layerActionBtn.getAttribute('data-layer-action');
    if (action === 'visibility') toggleWorkspaceLayerItemVisibility(itemId);
    else if (action === 'lock') toggleWorkspaceLayerItemLock(itemId);
    return;
  }
  const groupActionBtn = pt.closest('[data-layer-group-action]');
  if (groupActionBtn) {
    event.preventDefault();
    event.stopPropagation();
    const gid = groupActionBtn.getAttribute('data-group-id');
    const action = groupActionBtn.getAttribute('data-layer-group-action');
    if (action === 'visibility') toggleWorkspaceLayerGroupVisibility(gid);
    else if (action === 'lock') toggleWorkspaceLayerGroupLock(gid);
    return;
  }
  const toggleBtn = pt.closest('.cg-workspace-layer-group__toggle');
  const groupHeader = pt.closest('.cg-workspace-layer-group__header');
  if (toggleBtn || groupHeader) {
    const wrap = (toggleBtn || groupHeader).closest('.cg-workspace-layer-group');
    const gid = wrap?.getAttribute('data-group-id');
    if (gid) {
      event.preventDefault();
      event.stopPropagation();
      const now = isWorkspaceLayerGroupExpanded(gid);
      setWorkspaceLayerGroupExpanded(gid, !now);
      renderWorkspaceLayersPanel();
    }
    return;
  }
  const row = pt.closest('.cg-workspace-layer-row');
  if (!row) return;
  const clickedId = Number(row.getAttribute('data-layer-item-id'));
  if (!Number.isFinite(clickedId)) return;
  const rowItem = getItemById(clickedId);
  if (rowItem && isWorkspaceItemLayerLocked(rowItem)) return;
  const sorted = getWorkspaceLayersSortedItems();
  const clickedIndex = sorted.findIndex(it => Number(it.id) === clickedId);
  const ctrlOrMeta = event.ctrlKey || event.metaKey;
  if (event.shiftKey) {
    const anchorIndex = WS.layersSelectionAnchorIndex != null ? WS.layersSelectionAnchorIndex : clickedIndex;
    if (anchorIndex == null || clickedIndex < 0) return;
    WS.layersSelectionAnchorIndex = anchorIndex;
    const start = Math.min(anchorIndex, clickedIndex);
    const end = Math.max(anchorIndex, clickedIndex);
    const ids = sorted.slice(start, end + 1)
      .map(it => Number(it.id))
      .filter(Number.isFinite)
      .filter((id) => !isWorkspaceItemLayerLocked(getItemById(id)));
    if (!ids.length) return;
    setSelectedItems(ids, clickedId);
    return;
  }
  if (ctrlOrMeta) {
    selectWorkspaceItem(clickedId, true);
    WS.layersSelectionAnchorIndex = WS.selectedItemIds.length ? clickedIndex : null;
    return;
  }
  setSelectedItems([clickedId], clickedId);
  WS.layersSelectionAnchorIndex = clickedIndex >= 0 ? clickedIndex : null;
});
workspaceLayersListEl?.addEventListener('contextmenu', (event) => {
  const pt = layersPanelPointerTargetEl(event);
  const header = pt && typeof pt.closest === 'function' ? pt.closest('.cg-workspace-layer-group__header') : null;
  if (!header) {
    hideWorkspaceLayerGroupContextMenu();
    return;
  }
  if (workspaceIsClientView()) return;
  event.preventDefault();
  event.stopPropagation();
  const wrap = header.closest('.cg-workspace-layer-group');
  const gid = wrap?.getAttribute('data-group-id');
  if (!gid) return;
  showWorkspaceLayerGroupContextMenuAt(event.clientX, event.clientY, gid);
});

const workspaceTrashListEl = qs('#workspaceTrashList');
workspaceTrashListEl?.addEventListener('click', (event) => {
  if (event.button !== 0) return;
  const itemEl = event.target.closest('.cg-workspace-trash-item');
  if (!itemEl) return;
  const clickedId = Number(itemEl.getAttribute('data-trash-item-id'));
  if (!Number.isFinite(clickedId)) return;

  const clickedIndex = WS.trashItems.findIndex(it => Number(it.id) === clickedId);
  const ctrlOrMeta = event.ctrlKey || event.metaKey;

  if (event.shiftKey) {
    const anchorIndex = WS.trashSelectionAnchorIndex != null ? WS.trashSelectionAnchorIndex : clickedIndex;
    if (anchorIndex == null || clickedIndex < 0) return;
    WS.trashSelectionAnchorIndex = anchorIndex;
    const start = Math.min(anchorIndex, clickedIndex);
    const end = Math.max(anchorIndex, clickedIndex);
    WS.trashSelectedItemIds = WS.trashItems.slice(start, end + 1).map(it => Number(it.id)).filter(n => Number.isFinite(n));
  } else if (ctrlOrMeta) {
    const set = new Set((WS.trashSelectedItemIds || []).map(n => Number(n)).filter(n => Number.isFinite(n)));
    if (set.has(clickedId)) set.delete(clickedId);
    else set.add(clickedId);
    WS.trashSelectedItemIds = Array.from(set);
    WS.trashSelectionAnchorIndex = WS.trashSelectedItemIds.length ? clickedIndex : null;
  } else {
    WS.trashSelectedItemIds = [clickedId];
    WS.trashSelectionAnchorIndex = clickedIndex >= 0 ? clickedIndex : null;
  }

  syncWorkspaceTrashSelectionUi();
});

workspaceTrashListEl?.addEventListener('contextmenu', (event) => {
  const itemEl = event.target.closest('.cg-workspace-trash-item');
  if (!itemEl) return;
  event.preventDefault();
  event.stopPropagation();
  const clickedId = Number(itemEl.getAttribute('data-trash-item-id'));
  if (!Number.isFinite(clickedId)) return;

  const selectedSet = new Set((WS.trashSelectedItemIds || []).map(n => Number(n)).filter(n => Number.isFinite(n)));
  if (!selectedSet.has(clickedId)) {
    WS.trashSelectedItemIds = [clickedId];
    const clickedIndex = WS.trashItems.findIndex(it => Number(it.id) === clickedId);
    WS.trashSelectionAnchorIndex = clickedIndex >= 0 ? clickedIndex : null;
    syncWorkspaceTrashSelectionUi();
  }

  showWorkspaceTrashContextMenuAt(event.clientX, event.clientY, clickedId);
});

qs('#workspaceTrashRestoreBtn')?.addEventListener('click', async () => {
  const itemId = Array.isArray(WS.trashContextItemIds) ? WS.trashContextItemIds[0] : WS.trashContextItemId;
  if (!itemId) return;
  try {
    const formData = new FormData();
    formData.append('item_id', String(itemId));
    await fetchJson('/api/freelance_kanban.php?action=restore_workspace_item', {
      method: 'POST',
      body: formData
    });
    hideWorkspaceTrashContextMenu();
    await loadWorkspaceTrashItems();
    await pollWorkspaceOnce();
  } catch (err) {
    alert(err.message || 'Failed to restore item.');
  }
});

qs('#workspaceTrashDeleteForeverBtn')?.addEventListener('click', async () => {
  const ids = Array.isArray(WS.trashContextItemIds) && WS.trashContextItemIds.length
    ? WS.trashContextItemIds
    : (WS.trashContextItemId ? [WS.trashContextItemId] : []);
  const normalizedIds = Array.from(new Set((ids || []).map(n => Number(n)).filter(n => Number.isFinite(n))));
  if (!normalizedIds.length) {
    alert('No Trash items selected.');
    return;
  }
  try {
    const formData = new FormData();
    formData.append('board_id', String(WS.boardId));
    formData.append('item_ids', JSON.stringify(normalizedIds));
    await fetchJson('/api/freelance_kanban.php?action=delete_workspace_items_forever', {
      method: 'POST',
      body: formData
    });
    WS.trashSelectedItemIds = [];
    WS.trashContextItemIds = [];
    WS.trashContextItemId = null;
    WS.trashSelectionAnchorIndex = null;
    hideWorkspaceTrashContextMenu();
    await loadWorkspaceTrashItems();
    await pollWorkspaceOnce();
    scheduleWorkspaceBoardStorageRefresh();
    console.info(`Deleted forever: ${normalizedIds.length} item(s). This cannot be restored.`);
  } catch (err) {
    alert(err.message || 'Failed to delete forever.');
  }
});

