// Prevent dragging Trash thumbnails/cards onto the workspace stage.
document.addEventListener('dragstart', (event) => {
  const trashPanel = qs('#workspaceTrashPanel');
  if (!trashPanel || trashPanel.hidden) return;
  const target = event.target instanceof HTMLElement ? event.target : null;
  if (!target || !trashPanel.contains(target)) return;
  const dt = event.dataTransfer;
  if (!dt) return;
  try {
    dt.setData('application/x-cg-trash-origin', '1');
    dt.effectAllowed = 'none';
    dt.dropEffect = 'none';
    WS.dragFromTrash = true;
  } catch (e) {}
}, true);

document.addEventListener('dragend', () => {
  WS.dragFromTrash = false;
});
document.addEventListener('dragcancel', () => {
  WS.dragFromTrash = false;
});

document.addEventListener('dragstart', (e) => {
  const pull = e.target && e.target.closest ? e.target.closest('[data-cg-board-chat-source="1"]') : null;
  if (!pull || !e.dataTransfer) return;
  const itemEl = pull.closest('.cg-workspace-item--kanban_card');
  if (!itemEl) return;
  const item = getItemById(itemEl.dataset.itemId);
  const payload = workspaceBuildKanbanDragPayloadForBoardChat(item);
  if (!payload) return;
  const json = JSON.stringify(payload);
  try {
    localStorage.setItem(WORKSPACE_KANBAN_DRAG_STORAGE_KEY, JSON.stringify({ at: Date.now(), payload }));
  } catch (err) {}
  e.dataTransfer.effectAllowed = 'copy';
  try {
    e.dataTransfer.setData('application/x-cinegrid-kanban-card', json);
  } catch (err) {}
  try {
    e.dataTransfer.setData('text/x-cinegrid-kanban-card', json);
  } catch (err) {}
  try {
    e.dataTransfer.setData('text/plain', WORKSPACE_KANBAN_DRAG_PREFIX + json);
  } catch (err) {}
}, true);

