document.addEventListener('keydown', (event) => {
  const tableCell = workspaceTableCellFromEventTarget(event.target);
  if (tableCell && (event.metaKey || event.ctrlKey)) {
    const key = String(event.key || '').toLowerCase();
    const item = getItemById(tableCell.itemId);
    const baseSel = normalizeWorkspaceTableRange(WS.tableSelection)
      || { itemId: tableCell.itemId, r1: tableCell.row, c1: tableCell.col, r2: tableCell.row, c2: tableCell.col };
    if (item && item.item_type === WORKSPACE_TABLE_ITEM_TYPE && (key === 'c' || key === 'x')) {
      event.preventDefault();
      const tsv = workspaceTableSelectionToTsv(item, baseSel);
      const writeClipboard = async () => {
        if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
          await navigator.clipboard.writeText(tsv);
        }
      };
      writeClipboard().catch(() => {});
      if (key === 'x') {
        const model = parseWorkspaceTableModel(item.meta_json);
        const sel = normalizeWorkspaceTableRange(baseSel);
        if (sel) {
          for (let r = sel.r1; r <= sel.r2; r++) {
            for (let c = sel.c1; c <= sel.c2; c++) {
              if (model.cells[r]) model.cells[r][c] = '';
            }
          }
          item.meta_json = JSON.stringify({ rows: model.rows, cols: model.cols, cells: model.cells, base_width: model.baseWidth, base_height: model.baseHeight });
          queueItemSave(item.id, 260);
          renderItems();
        }
      }
      return;
    }
  }
  const isUndoShortcut = (event.metaKey || event.ctrlKey) && !event.shiftKey && String(event.key).toLowerCase() === 'z';
  const isRedoShortcut = ((event.metaKey || event.ctrlKey) && event.shiftKey && String(event.key).toLowerCase() === 'z')
    || (event.ctrlKey && !event.metaKey && !event.shiftKey && String(event.key).toLowerCase() === 'y');
  if (isUndoShortcut && !isEditableTarget(event.target)) {
    if (event.repeat) return;
    event.preventDefault();
    undoWorkspaceChange().catch(err => {
      console.error('Workspace undo error:', err);
      alert(err.message || 'Failed to undo workspace change.');
    });
    return;
  }
  if (isRedoShortcut && !isEditableTarget(event.target)) {
    if (event.repeat) return;
    event.preventDefault();
    redoWorkspaceChange().catch(err => {
      console.error('Workspace redo error:', err);
      alert(err.message || 'Failed to redo workspace change.');
    });
    return;
  }
  const isClearAllShortcut = (event.metaKey || event.ctrlKey) && event.shiftKey && (event.key === 'Delete' || event.key === 'Backspace');
  if (isClearAllShortcut) {
    event.preventDefault();
    clearWorkspaceDocument().catch(err => {
      console.error('Workspace clear error:', err);
      alert(err.message || 'Failed to clear workspace.');
    });
    return;
  }
  if (WS.drawing && !isEditableTarget(event.target) && !event.repeat) {
    if (event.code === 'ShiftLeft' || event.code === 'ShiftRight') {
      WS.drawing.shiftShapeAssistPending = true;
      WS.drawing.shiftAssistUsed = true;
      refreshBrushShiftShapeAssist(WS.drawing);
      if (WS.drawing.targetItemId) renderItems(); else scheduleWorkspaceRender({ strokes: true });
    }
  }
  if (event.altKey || event.ctrlKey || event.metaKey) return;
  if (event.code === 'Space' && !isEditableTarget(event.target)) {
    WS.spacePressed = true;
  }
  if (!isEditableTarget(event.target)) {
    if (event.key === 'Tab') {
      event.preventDefault();
      if (WS.aiPromptOpen) {
        closeWorkspaceAiPrompt();
      } else {
        openWorkspaceAiPrompt();
      }
      return;
    }
    // Prevent workspace tool hotkeys from firing while the user is trying to type.
    // Also suppress hotkeys when a text/note card is selected.
    if (WS.selectedItemIds && WS.selectedItemIds.length) {
      const hasTextOrNote = WS.selectedItemIds.some((id) => {
        const item = getItemById(id);
        return item && (item.item_type === 'sticky_note' || item.item_type === 'text_card');
      });
      if (hasTextOrNote) {
        const k = String(event.key || '').toLowerCase();
        if (k !== 'z' && k !== 'g' && k !== 'l' && k !== 'c' && event.key !== 'Delete' && event.key !== 'Backspace') return;
      }
    }
    if (event.repeat) return;
    const key = (event.key || '').toLowerCase();
    if (key === 'v') {
      event.preventDefault();
      setWorkspaceMode('select');
      return;
    }
    if (key === 'h') {
      event.preventDefault();
      setWorkspaceMode(WS.mode === 'pan' ? 'select' : 'pan');
      return;
    }
    if (key === 'i') {
      event.preventDefault();
      qs('#workspaceImageInput').click();
      return;
    }
    if (key === 'p') {
      event.preventDefault();
      if (event.shiftKey) {
        closeSpreadsheetMenu();
        if (WS.storyboardMenuOpen) closeStoryboardMenu();
        else openStoryboardMenu();
      } else {
        closeStoryboardMenu();
        closeSpreadsheetMenu();
        addPaletteCard().catch(err => alert(err.message || 'Failed to create palette.'));
      }
      return;
    }
    if (key === 'b') {
      event.preventDefault();
      setWorkspaceMode(WS.mode === 'brush' ? 'select' : 'brush');
      return;
    }
    if (key === 'e') {
      event.preventDefault();
      closeSketchMenu();
      if (WS.mode === 'eraser') {
        setWorkspaceMode('select');
        closeBrushMenu();
      } else {
        setWorkspaceMode('eraser');
        if (!WS.brushMenuOpen) openBrushMenu();
      }
      return;
    }
    if (key === 'k') {
      event.preventDefault();
      if (WS.sketchMenuOpen) {
        closeSketchMenu();
      } else {
        openSketchMenu();
      }
      return;
    }
    if (key === 's') {
      event.preventDefault();
      addStickyNote().catch(err => alert(err.message || 'Failed to create note.'));
      return;
    }
    if (key === 't') {
      event.preventDefault();
      if (event.shiftKey) {
        closeTextMenu();
        closeStoryboardMenu();
        if (WS.spreadsheetMenuOpen) closeSpreadsheetMenu();
        else openSpreadsheetMenu();
        return;
      }
      closeBrushMenu();
      closeSketchMenu();
      if (WS.mode === 'text') {
        setWorkspaceMode('select');
        return;
      }
      setWorkspaceMode('text');
      openTextMenu();
      return;
    }
    if (key === 'c') {
      event.preventDefault();
      if (getSelectedConnectorIds().length) {
        disconnectSelectedItems().catch(err => alert(err.message || 'Failed to disconnect selected cards.'));
      } else {
        connectSelectedItems().catch(err => alert(err.message || 'Failed to connect selected cards.'));
      }
      return;
    }
    if (key === 'z') {
      event.preventDefault();
      resetView();
      return;
    }
    if (key === 'x') {
      event.preventDefault();
      toggleWorkspaceTrash();
      return;
    }
    if (key === 'l') {
      event.preventDefault();
      toggleWorkspaceLayers();
      return;
    }
    if (key === 'g') {
      event.preventDefault();
      groupSelectedWorkspaceItems().catch(err => {
        console.error('Group items error:', err);
        alert(err.message || 'Failed to group cards.');
      });
      return;
    }
  }
  if ((event.key === 'Delete' || event.key === 'Backspace') && !isEditableTarget(event.target)) {
    if (event.repeat) return;
    const permanent = !!event.shiftKey;
    const toDelete = WS.selectedItemIds.length
      ? [...WS.selectedItemIds]
      : (WS.activeItemId ? [WS.activeItemId] : []);
    const toDeleteUnlocked = toDelete.filter((id) => !isWorkspaceItemLayerLocked(getItemById(id)));
    if (!toDeleteUnlocked.length) return;
    event.preventDefault();
    (async () => {
      const deleteFn = permanent ? deleteWorkspaceItem : trashWorkspaceItem;
      const batchDelete = toDeleteUnlocked.length > 1;
      const removedIds = [];
      for (const itemId of toDeleteUnlocked) {
        try {
          if (batchDelete) {
            removeWorkspaceItemElement(itemId);
            removedIds.push(itemId);
          }
          await deleteFn(itemId, { render: !batchDelete, captureHistory: !batchDelete });
        } catch (err) {
          if (isWorkspaceItemNotFoundError(err)) continue;
          alert(err.message || (permanent ? 'Failed to delete item permanently.' : 'Failed to delete item.'));
          break;
        }
      }
      if (batchDelete && removedIds.length) {
        scheduleWorkspaceItemRemovalEffects();
        scheduleWorkspaceHistoryCapture();
      }
      setSelectedItems([], null);
    })();
  }
  if (event.key === 'Escape') {
    closeWorkspaceAiPrompt({ keepFocus: true });
    closeWorkspaceFontPicker();
    if (WS.marquee) {
      WS.marquee = null;
      hideMarqueeOverlay();
      const st = getStage();
      if (st) st.classList.remove('is-marquee-active');
    }
    closeTextPropertyPanel();
    closeTextMenu();
    exitItemEditMode();
    exitPaletteEditMode();
    closeImageContextMenu();
    closeConnectorContextMenu();
    closeStageContextMenu();
    setSelectedItems([], null);
    if (WS.mode !== 'select') setWorkspaceMode('select');
  }
});
document.addEventListener('keyup', (event) => {
