  }
});
document.addEventListener('contextmenu', (event) => {
  const workspaceRoot = qs('.cg-workspace-page');
  if (!workspaceRoot || !workspaceRoot.contains(event.target)) return;
  if (workspaceIsClientView()) {
    event.preventDefault();
    closeStageContextMenu();
    closeImageContextMenu();
    closeConnectorContextMenu();
    return;
  }
  const connectorGroup = event.target.closest('.cg-workspace-connector-group[data-connector-id]');
  if (connectorGroup) {
    event.preventDefault();
    const connectorId = Number(connectorGroup.getAttribute('data-connector-id') || 0);
    if (connectorId) {
      openConnectorContextMenu(connectorId, event.clientX, event.clientY);
    }
    return;
  }
  const menuItemEl = event.target.closest('.cg-workspace-item--image, .cg-workspace-item--sticky_note, .cg-workspace-item--text_card, .cg-workspace-item--brush_card, .cg-workspace-item--palette_card, .cg-workspace-item--storyboard_sheet, .cg-workspace-item--table_card, .cg-workspace-item--kanban_card, .cg-workspace-item--youtube_embed, .cg-workspace-item--iframe_embed, .cg-workspace-item--map_embed, .cg-workspace-item--instagram_embed');
  if (menuItemEl) {
    event.preventDefault();
    const itemId = Number(menuItemEl.dataset.itemId || 0);
    if (itemId) {
      const tableCell = workspaceTableCellFromEventTarget(event.target);
      WS.tableContextCell = tableCell && Number(tableCell.itemId || 0) === itemId
        ? { itemId, row: Number(tableCell.row), col: Number(tableCell.col) }
        : null;
      setSelectedItems([itemId], itemId);
      openImageContextMenu(itemId, event.clientX, event.clientY);
    }
    return;
  }
  const stageEl = event.target.closest('#workspaceStage');
  if (stageEl && !event.target.closest('.cg-workspace-item') && !event.target.closest('.cg-workspace-connector-group')) {
    event.preventDefault();
    WS.stageContextWorldPoint = stagePointToWorld(event.clientX, event.clientY);
    WS.contextMenuAnchor = { x: event.clientX, y: event.clientY };
    openStageContextMenu(event.clientX, event.clientY);
    return;
  }
  closeStageContextMenu();
  closeImageContextMenu();
  closeConnectorContextMenu();
  event.preventDefault();
});
