async function workspaceApplyTableStructureInsert(mode) {
  const ctx = WS.tableContextCell;
  if (!ctx || !ctx.itemId) return;
  const item = getItemById(ctx.itemId);
  if (!item || item.item_type !== WORKSPACE_TABLE_ITEM_TYPE) return;
  const model = parseWorkspaceTableModel(item.meta_json);
  const row = Math.max(0, Math.min(model.rows - 1, Number(ctx.row || 0)));
  const col = Math.max(0, Math.min(model.cols - 1, Number(ctx.col || 0)));
  if (mode === 'row-above' || mode === 'row-below') {
    const insAt = mode === 'row-above' ? row : row + 1;
    const newRow = Array.from({ length: model.cols }, () => '');
    model.cells.splice(insAt, 0, newRow);
    if (model.cells.length > 80) model.cells = model.cells.slice(0, 80);
    model.rows = model.cells.length;
  } else if (mode === 'col-right') {
    const insAt = col + 1;
    model.cells = model.cells.map((r) => {
      const out = Array.isArray(r) ? r.slice(0, 16) : [];
      out.splice(insAt, 0, '');
      if (out.length > 16) out.length = 16;
      while (out.length < Math.max(1, Math.min(16, model.cols + 1))) out.push('');
      return out;
    });
    model.cols = Math.max(1, Math.min(16, model.cols + 1));
  } else {
    return;
  }
  const natural = workspaceTableNaturalSize(model.rows, model.cols);
  model.baseWidth = natural.width;
  model.baseHeight = natural.height;
  item.width = Math.max(Number(item.width || 0), Number(model.baseWidth || 0));
  item.height = Math.max(Number(item.height || 0), Number(model.baseHeight || 0));
  item.meta_json = JSON.stringify({ rows: model.rows, cols: model.cols, cells: model.cells, base_width: model.baseWidth, base_height: model.baseHeight });
  await saveWorkspaceItem(item);
  renderItems();
}
