function angleDeltaDeg(fromDeg, toDeg) {
  let d = Number(toDeg) - Number(fromDeg);
  if (!Number.isFinite(d)) return 0;
  while (d > 180) d -= 360;
  while (d < -180) d += 360;
  return d;
}
function normalizeRotationDeg(deg) {
  let d = Number(deg);
  if (!Number.isFinite(d)) d = 0;
  d = d % 360;
  if (d > 180) d -= 360;
  if (d < -180) d += 360;
  return d;
}
function toggleImageFlipFlag(item, key) {
  const meta = parseMaybeJson(item.meta_json, {});
  meta[key] = !meta[key];
  item.meta_json = JSON.stringify(meta);
}
function applyImageRotationDelta(item, deltaDeg) {
  item.rotation = normalizeRotationDeg(Number(item.rotation || 0) + Number(deltaDeg || 0));
}
async function applyImageTransformAndSave(itemId, fn) {
  const item = getItemById(itemId);
  const type = String(item?.item_type || '');
  if (!item || (type !== 'image' && type !== 'text_card')) return;
  fn(item);
  await saveWorkspaceItem(item);
}
