const workspaceConnectorColorPickBtn = qs('#workspaceConnectorColorPickBtn');
if (workspaceConnectorColorPickBtn) {
  workspaceConnectorColorPickBtn.addEventListener('pointerdown', (event) => event.stopPropagation());
  workspaceConnectorColorPickBtn.addEventListener('click', async (event) => {
    event.preventDefault();
    event.stopPropagation();
    const id = WS.connectorContextMenuConnectorId;
    if (!id) return;
    closeConnectorContextMenu();
    let hex = '';
    try {
      if (window.EyeDropper) {
        const ed = new EyeDropper();
        const result = await ed.open();
        hex = normalizeHexColor(result.sRGBHex);
      } else {
        hex = await new Promise((resolve) => {
          const inp = document.createElement('input');
          inp.type = 'color';
          inp.value = '#111827';
          inp.setAttribute('aria-hidden', 'true');
          inp.style.cssText = 'position:fixed;left:-120px;top:0;width:1px;height:1px;opacity:0;pointer-events:none;';
          document.body.appendChild(inp);
          inp.addEventListener('change', () => {
            const h = normalizeHexColor(inp.value) || '';
            inp.remove();
            resolve(h);
          }, { once: true });
          inp.click();
        });
      }
    } catch (err) {
      return;
    }
    if (!hex) return;
    applyConnectorStylePatch(id, { color: hex }).catch((err) => alert(err.message || 'Failed to update connector.'));
  });
}
