  });
}
document.addEventListener('paste', (event) => {
  const cell = workspaceTableCellFromEventTarget(event.target);
  if (cell) {
    const item = getItemById(cell.itemId);
    if (item && item.item_type === WORKSPACE_TABLE_ITEM_TYPE) {
      const text = String(event.clipboardData?.getData('text/plain') || '');
      const matrix = parseWorkspaceClipboardMatrix(text);
      if (matrix && matrix.length) {
        event.preventDefault();
        const model = parseWorkspaceTableModel(item.meta_json);
        const baseSel = normalizeWorkspaceTableRange(WS.tableSelection);
        const startRow = baseSel && Number(baseSel.itemId) === Number(cell.itemId) ? baseSel.r1 : cell.row;
        const startCol = baseSel && Number(baseSel.itemId) === Number(cell.itemId) ? baseSel.c1 : cell.col;
        const targetHeight = matrix.length;
        const targetWidth = matrix.reduce((m, row) => Math.max(m, row.length), 0);
        while (model.cells.length < Math.min(80, startRow + targetHeight)) {
          model.cells.push(Array.from({ length: model.cols }, () => ''));
        }
        if (model.cols < Math.min(16, startCol + targetWidth)) {
          const nextCols = Math.min(16, startCol + targetWidth);
          model.cells = model.cells.map((row) => {
            const out = row.slice(0, nextCols);
            while (out.length < nextCols) out.push('');
            return out;
          });
          model.cols = nextCols;
        }
        for (let r = 0; r < matrix.length; r++) {
          for (let c = 0; c < matrix[r].length; c++) {
            const rr = startRow + r;
            const cc = startCol + c;
            if (rr < 0 || cc < 0 || rr >= 80 || cc >= 16) continue;
            if (!model.cells[rr]) model.cells[rr] = Array.from({ length: model.cols }, () => '');
            model.cells[rr][cc] = String(matrix[r][c] ?? '');
          }
        }
        model.rows = model.cells.length;
        const natural = workspaceTableNaturalSize(model.rows, model.cols);
        model.baseWidth = natural.width;
        model.baseHeight = natural.height;
        item.width = Math.max(Number(item.width || 0), Number(model.baseWidth || 0));
        item.height = Math.max(Number(item.height || 0), Number(model.baseHeight || 0));
        item.meta_json = JSON.stringify({ rows: model.rows, cols: model.cols, cells: model.cells, base_width: model.baseWidth, base_height: model.baseHeight });
        queueItemSave(item.id, 200);
        setWorkspaceTableSelection({
          itemId: item.id,
          r1: startRow,
          c1: startCol,
          r2: startRow + Math.max(0, matrix.length - 1),
          c2: startCol + Math.max(0, targetWidth - 1),
        });
        renderItems();
      }
      return;
    }
  }
  handlePaste(event).catch(err => {
    console.error('Workspace paste error:', err);
    alert(err.message || 'Paste failed.');
  });
});
